/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20190225-9","meetingId":"r01-cm02","date":"2019年2月25日","dateIso":"2019-02-25","committee":"文教委員会","time":"午前１０時００分～午後 ３時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を92件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１５号議案、品川区子ども・子育て会議条例の一部を改正する条例","agenda":"第１５号議案、品川区子ども・子育て会議条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"改正理由のところに、「会議の運営内容に応じた庶務所管とすることで効率的な運営を図る」とありますけれども、当初は子ども育成課がふさわしいということで、内容的なもので保育課に移したほうがいいと、子ども・子育て会議の内容とかが変わったのか、その辺をもうちょっと詳しく教えてください。","respondent":"高山子ども育成課長","answer":"当初は子ども・子育て会議の審議の内容は、子ども・子育て支援事業計画という、主に保育の関係の内容を審議する計画と、それから次世代育成支援対策推進行動計画というのがございまして、これが青少年の健全育成、少子化対策などに資するような内容の計画と。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"確認","question":"ありがとうございました。わかりました。今回の条例は、所管がかわるということだけで、ほかは何もないのかどうか、そこの確認をできますでしょうか。","respondent":"高山子ども育成課長","answer":"今回の改正理由の中に書かせていただきましたとおり、その内容にふさわしい所管が庶務事項を所管するといった以上の変更は今回ご提案するものではございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"確認させていただきたいのですが、そうすると、庶務の担当の方は、子ども育成課のほうにいたのですけれども、今度は保育課のほうでこの庶務所管の職務というんですか、役割をまた庶務担当の方が新しくどなたかなると。そういうことに関しては、特に条例云々ではなくて、組織が変わるのかなと思うんですけれども、その辺の扱いはどのようになるのでしょうか。","respondent":"高山子ども育成課長","answer":"いわゆる会議の開催にかかわるさまざまな事務処理事項、そういったものを保育課で一手に担うとともに、今回の平成３１年度当初予算においても、これまで１目子ども育成費という予算においてこの会議にかかる費用を計上してきたのですが、今回の平成３１年度予算から。","voiceIndex":10,"id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、保育課のほうの係長かどなたかがこれを担当することになるのでしょうか。そこのところを、すみません。","respondent":"高山子ども育成課長","answer":"今回の条例改正とともに規則のほうも変更を加えまして、保育課の係にこれまで子ども育成課の庶務係で担っていた事務そのものを移すというようなことですので、保育課の係において処理していくということとなります。","voiceIndex":12,"id":"exchange-004"}]},{"id":"topic-02","title":"第１６号議案、品川区女性福祉資金貸付条例を廃止する条例","agenda":"第１６号議案、品川区女性福祉資金貸付条例を廃止する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"目的に対する利用実績が少ないということがどういうことなのかということです。ちょっとそのあたりも含めて教えていただきたいというのが１つです。利息もそんなに高くはないけれどもやっていたという状況に対して、品川区としては、検討の過程の中で他区の状況も検討されたと思うのですが、その後どういうふうに評価しているかという、とりあえず、３点よろしくお願いいたします。","respondent":"廣田子ども家庭支援課長","answer":"１番目に、利用実績についての考え方ですけれども、その次の質問と関係するのですが、平成２５年の改正のときにもほぼ活用することはなく、修学資金等のみ活用されているというところでこれだけ残したという経過があるのですが、その際になぜ残したかという理由が。","voiceIndex":26,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で見たときに、この制度の役割は終わったと認識していると受けとめていいのかというのを伺いたいと思うのです。そういうことでいいのかと非常に気になるので、改めてそこの考え方を伺っておきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"女性の自立の支援としてどうかというお話があったのですけれども、現在女性福祉資金については、お子さんの就学関係の資金のみ残しておりまして。","voiceIndex":28,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"今、現状の実績と５年前になくしていった以前のいろいろな修学資金、技能習得資金、事業を起業する際の資金、いろいろな種類があったそこの利用状況と、廃止した後の他の制度で充実して対応できているというそこの制度の状況がどういうふうになっているのかを見ないと、廃止してもいいとはなりませんので、教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"それで、女性福祉資金はもう平成２５年からほかの制度についてはなくしておりますので、事業の継続等については直接は関係ないのではないかと思いますが、母子福祉資金で事業開始であるとか事業継続であるとかという貸し付けを受ける方は、年間に１名あるかないかというところで。","voiceIndex":30,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"女性の創業のところでどの程度の実績があるかというと、やはり１年間で十数件です。もう少し借りれるような内容に工夫をしていくべきではないかと思っているのです。最後に、この５年間いろいろな制度を切ってきて、修学資金と就学支度資金とこの２つを残してきたその中で、いろいろ借りやすいようにと工夫した実績というのはどういうところがあるのか、あったら教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"自立の話なのですけれども、ものづくりであったり事業の資金についてはあくまでも自営で自分が立ち上げる人の話でありまして、現在、就労の支援で自立支援プログラムという就職させるための制度がございまして、プログラムに申し込んだ毎年三十数名の方については。","voiceIndex":32,"id":"exchange-008"},{"speaker":"南委員","kind":"確認","question":"したがって、そこについてはどうだったのか、改めて伺いたいと思います。借りにくくなっている一つの理由、大きな理由として保証人があるのではないかと思うわけですが、そこについての、ではなくすためには利子をいただくということをおっしゃっていたけれども、それだけなのかどうかも含めて確認したいと思います。","respondent":"廣田子ども家庭支援課長","answer":"そこが拾えるようになったので、この資金の役割は終わったと考えておりまして、保証人については母子福祉資金も女性福祉資金も、都からおりてきた制度で２３区共通のもので行っているので、品川区独自で変えるということは余り考えにくく。","voiceIndex":34,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"自治体としてはやはりこういった貸付制度があることで、ここの課で女性の立場が把握できるという大事な重要な仕事があると思うのですが、一つずつの貸し付けがそれぞれの制度で賄われているからいいと考えているのか、改めてそこをもう一度聞きたいのと、あと、今までの実績の教育のところで貸付継続者として大学生１名と２８名の償還をされている方が。","respondent":"廣田子ども家庭支援課長","answer":"２８名貸し付けている方につきましては、今細かいデータは持っていませんけれども、修学のために借りた資金となっておりまして、ほぼ大学です。","voiceIndex":37,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"確認","question":"２８名の方、ほぼ修学のためというところにおいて、５年前にこの制度が狭められた後のことなのか、その以前の方はもういないのか、ちょっとそこをもう一度確認したいのと、窓口があるので女性の状況を把握できるということですけれども、自分のところでやっている貸付制度がなくなってしまって、はい、これはあちら、はい、これはこちらというふうに振り分けていくこと自体。","respondent":"廣田子ども家庭支援課長","answer":"母子福祉資金の貸し付けについては、今も審査から貸し付け、償還まで子ども家庭支援課で行っておりますので人に渡すわけではございませんし、社会福祉協議会につきましても、連携をとりながら母子福祉資金に当てはまるかそちらにご紹介するかについては。","voiceIndex":39,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"今出ました転宅資金、引っ越し資金とか、あと生活再建資金とか、こういうのはではほかのところで十分受けとめられているということなのでしょうか。社会福祉協議会に問い合わせたら、生活福祉資金で貸しているのは、ほとんど教育のことなのです。私はそこがそうなっていないのではないかと受けとめているのですけれども、いかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"生活福祉資金等につきましては、こちらの窓口で受けておりますので、母子福祉資金等で賄えるものはこちらでお貸ししていまして、それ以上所得が低い方については社会福祉協議会をご案内しますけれども、それ以上所得が低い方は生保になりますので。","voiceIndex":41,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"所得の低い方は貸しても返せないということであると思うのですが、そういう人たちはその先の、生保も含めてきちんとした生活ができるような援助が実際に行われているのかどうか。どのくらい行われているのか、その辺も教えてください。","respondent":"廣田子ども家庭支援課長","answer":"それ以上の支援といいますか、社会福祉協議会と生保の間には暮らし・しごと応援センターがありますので、そちらにまずご案内して、そこから生保かどうなるかというところにつないでおります。","voiceIndex":43,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"そういった意味で、私はこの暮らし・しごと応援センターですか、この辺もなかなか実態に合って使われていないということも聞いておりますので、最終的にはあきらめざるを得ないという実態があるのではないかと思いますが、その点はいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"その人の人生、今の生活を含めて、過去と現在と未来についてつなげていく場合に、総合的に品川区自体がありとあらゆるところを活用して、やはり考えていってほしいという意味においては、そこの一つの女性福祉の問題であっても、やはりどれだけ連携が取れているのかというところなので、担当課としてはやはりそこに習熟をしていない限り活用ができないのではないかと思って質問してみましたが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今回この条例の廃止がなぜこの時期に上がってきたのかという背景を改めて教えていただきたいと思います。例えば、来年度予算をいろいろ考えている中で、いわゆる予算をつける中で、この制度は一定その役割を終えたのだなという判断をして今回上がってきたのか、その背景を改めて教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"この女性福祉資金あたりの年齢でさらに借りるとなると、やはり保証人を立てられないという方が多く、下のご兄弟が２０歳未満だから母子が借りられますよといっても、下の子たちも進学させなければならないので、やはり保証人が立てられない方については。","voiceIndex":49,"id":"exchange-016"},{"speaker":"つる委員","kind":"質問","question":"これは貸付金の部分の財源の確保につながる部分と、事務経費というところは大きく２つに分かれるとは思うのですが、今後その辺の事務経費は大きくなるのか小さくなるのか、あと債権が完了した段階では当然債権を回収する経費というのはなくなるとは思うのですけれども、その経費的な部分ではどうなっているのか、そのあたりを教えてください。","respondent":"廣田子ども家庭支援課長","answer":"払えない人は払えないなりの確認をしないと、不納欠損で落とすこともできませんので、払える人には払っていただく、払えない人の分は落としていくという処理、６名の大体のめどがついたというところですので、近い将来事務費としては消えていく予定です。","voiceIndex":52,"id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"ただ、それを回収するというところについての事務というのは今後も続くというところが今のところでありますし、そういう滞納者に対する対応、早期の解決というところでの経費はボリュームが少しつくという理解をする中で、要するに回収すること全体として数年かかるのかもしれないのですが、経費的な部分でどの程度財源的なところでは変わるのかというのは教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"弁護士委任については平成２７年から行っておりますので、貸し付けの事務が減り、その辺は横ばいなのですけれども、若干、遠方にいらっしゃる方について所在の確認をしなければいけない部分については委託を考えております。","voiceIndex":54,"id":"exchange-018"},{"speaker":"つる委員","kind":"質問・要望","question":"そこと合わせると平成３０年度と多分１２０万円ぐらいの差があると思っていまして、予算特別委員会の中でもこの辺は確認したいと思うのですが、要は、これまで制度として、今いろいろな議論があって、今後そうした支援が必要な方に対する部分については、丁寧な説明ですとか結びつきをしっかりとやっていくということ、これは当然今後強化をしていただきたいというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"反対します。理由は、自治体のあり方というか、非常に経済的にもいろいろな状況のところで苦労しておられる方々への支援を、他の制度に変わるということでなくしてしまうわけにはいかないと。やはり、女性の自立というところをしっかりとフォローする制度は残していただきたい、そういうことです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-020"}]},{"id":"topic-03","title":"第１７号議案、品川区児童育成手当条例の一部を改正する条例、(4)第１８号議案、品川区ひとり親家庭等の医療費の助成に関する条例の一部を改正する条例","agenda":"第１７号議案、品川区児童育成手当条例の一部を改正する条例、(4)第１８号議案、品川区ひとり親家庭等の医療費の助成に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この表の中で点線の中に入っている「同一生計配偶者のうち合計所得金額が１,０００万円以下である居住者の配偶者」という、ここのところが入ることで今までと同じ状況にあるという説明でしたが、これがもし入らないとどういうことになるのか、その違いを教えてください。","respondent":"廣田子ども家庭支援課長","answer":"私の説明が悪かったのかもしれないのですけれども、「控除対象配偶者」という名称がそのままですと、この点線の中の方だけを指してしまうので、今までどおりにするためには「同一生計配偶者」と呼ぶというふうになっただけで、この中身については。","voiceIndex":68,"id":"exchange-021"}]},{"id":"topic-04","title":"第１９号議案、品川区子どもの医療費の助成に関する条例の一部を改正する条例","agenda":"第１９号議案、品川区子どもの医療費の助成に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"償還払いとした理由が余りよくわからないのですけれども、この高校生まで対象を広げるということは私たちも主張してきたことなので大歓迎したいなと思っています。とりわけ入院まで含めたというところはいいなと思ってはいるのですけれども、医療証を発行しないで償還払いにすることの、それ以前の小さなお子さんたちとの関係でどういうふうに振り分けたのか、そのあたりの説明をお願いします。","respondent":"廣田子ども家庭支援課長","answer":"償還払いという形が一元的に、医療証を発行して各病院に手配する手間暇を考えると、事務効率がいいのではないかということで検討いたしました。","voiceIndex":88,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"ただし、今後の問題としてそういった外来、通院の部分も対応していただけるように求めていきたいということは言っておきたいと思います。それで、今の償還払いというところはそういう状況があるのだということは了解したのですけれども、いろいろあるのですが、ぐちゃぐちゃになってしまうのでやめて、償還払いにしたという理由はわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問","question":"ちょっとお伺いしたいのですけれども、これはいわゆる例えば１８歳の子が３月３０日から４月にまたいで入院した場合というのは、入院した日がこの対象の中の年齢だったら、年度をまたいでも支払っていただけるのかというのと、あとは、システムの改修費は毎回何かあると出てくるのです。","respondent":"廣田子ども家庭支援課長","answer":"入院費の年度またぎなのですけれども、医療費は月ごとの支払いになりますので、３月末に入院されても３月分と４月分と医療費の支払いは分かれると思いますので４月分の支払い分、４月１日の支払い分以降から適用になると考えております。","voiceIndex":92,"id":"exchange-024"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"わかりました。それはそのシステムをつくっているところの仕事ですから、一定の金額がかかるのはわかるのですけれども、予算書を見ると、このシステム改修費は毎回いろいろ出てくるのです。大体１,０００万円単位で出てくるので、先ほど今後はいろいろまとめて事務効率が上がってくるのではないかという話でしたけれども、これはでも本当にそういうふうなものにしていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問","question":"話が外れてしまったら申し訳ありませんが、婚姻の年齢、これはあれですよね、お子さんでも結婚している方の話ですよね。とすると、支給しないということですけれども、これは条例でそういうふうに付け加えてあるのですけれども、女性の婚姻年齢が変わったらまた条例も変えるのですか。","respondent":"廣田子ども家庭支援課長","answer":"婚姻していて、事実婚も入るのですけれども、何を言っているかというと、保護者に支給するので扶養の関係に入っているかどうかというところで、婚姻していれば生計を別にしているであろうというところであったり、ここの説明はすごくざっくりしているのですけれども。","voiceIndex":96,"id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認で、女性の婚姻年齢が１８歳になったとしても、それによって影響がない記述の方向だということですか。","respondent":"廣田子ども家庭支援課長","answer":"そのとおりです。","voiceIndex":98,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとそこを具体的に一つお伺いしたいのと、あと、今回は、入院のみということなのですけれども、例えば通院を含めて試算をするとこの予算が幾らぐらいになるのか。多分計算されているのではないかと思うので、教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"品川区は７,０００人おりますので、千代田区でかかったお金を単純に率でかけると１億円以上、単純計算ですけれども１億８,０００万円になってしまうので、ちょっとそこまではどうなのかなというところで、入院のみでというのが妥当な線かなというところを検討しています。","voiceIndex":101,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"数字を教えていただいてありがとうあります。簡単に計算して１億８,０００万円ということなので、私たちとしてはぜひ早い時期に通院も含めて１８歳までの医療費ゼロを実現してほしいなと思うのと、先ほど償還払いの説明もいただいたのですけれども、できたら保護者の方々の負担を考え、窓口負担をゼロにしていく方向での検討もさらに進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-029"},{"speaker":"つる委員","kind":"質問・要望","question":"今回の条例改正、公明党としても高校生までの医療費の助成を求めてきて、その中でもせめてということで入院費のところもあわせて求めてきたところなので、今回の改正については歓迎してしっかりと、今各委員からもありましたけれども、支払い手続等の中でも少しでも負担軽減になるような形もまた一方で図っていただきたいという思いがあります。そうした中で、今システムのお話もありました。","respondent":"廣田子ども家庭支援課長","answer":"児童福祉総合システム、児童手当であるとかさまざまな手当、全国で共通であったりとかいろいろあるのですけれども、今回システム更新、今年度予定して、予算とかはもっと前なのですが、ほかの区の共通の制度を持っていて、２３区でほかでも仕事をしているところを探して、同じ区。","voiceIndex":105,"id":"exchange-030"},{"speaker":"つる委員","kind":"質問・要望","question":"システムのところは細かい話ですけれども、ただ、どうしても表に見えない部分で、また知的財産ではないですが、そういったところの評価は非常に難しい部分があるのかなと思いながら、ただ、事務効率はそれはそれで上がる、窓口等またそういう職員のいろいろな部分での業務効率が上がるというところにおいては必要な経費なので、その限りではないと思うんですけれども。","respondent":"廣田子ども家庭支援課長","answer":"ですので、その試算よりも多目に予算を取らせていただいて、該当する方には足りなければどこかほかの財源を確保してお支払いするというところでは考えておりますが、参考からいうとこの程度でおさまる範囲と。","voiceIndex":107,"id":"exchange-031"},{"speaker":"つる委員","kind":"質問","question":"今の五、六万円の参考値というのは、入院の部分についての試算での五、六万円という計算でよろしいですね。そこになおかつ品川区はプラスアルファして予算立てをしているという考えでいいのか教えてください。","respondent":"廣田子ども家庭支援課長","answer":"北区と品川区で１６歳から１８歳の児童人口がほぼ同じぐらいだったので、実績がないのでこれを参考にしたというところで、データが出てくればまた変わってくるかもしれません。","voiceIndex":109,"id":"exchange-032"},{"speaker":"つる委員","kind":"質問・要望","question":"北区は入院だけでしたね。千代田区は全部。失礼しました。今回、入院ということで品川区も高校生まで広げていただいたということで、引き続き公明党としても高校生等の医療費全体の拡大ということは求めていく立ち位置ですが、今回この入院まで拡大されたということをしっかりと、先ほども申し上げたとおり、事務手続等少しでも簡便になるように努力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-033"}]},{"id":"topic-05","title":"第２６号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第２６号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"改正の理由のところに、「都立学校の学校医、学校歯科医及び学校薬剤師の公務災害補償に関する条例」の一部が変わったことにあわせてこちらも変わったということなのですけれども、額が変わるということにおいて何を持ってきて基準として改定が行われるのか、大もとのところは何を基準にしているのか教えていただきたいのと、あともう一つ。","respondent":"篠田学務課長","answer":"今回もそうなのですけれども、いつも東京都と合わせて変更しているのですが、これはもともとの制度の経緯が、平成１４年から区のほうで独自の条例という形で設定しているのですけれども、それまではずっと東京都の条例のもとにやってきたといったことがあること、あと。","voiceIndex":125,"id":"exchange-034"}]},{"id":"topic-06","title":"第２７号議案、幼稚園教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例、(8)第２８号議案、学校教育職員の勤務時間、休日","agenda":"第２７号議案、幼稚園教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例、(8)第２８号議案、学校教育職員の勤務時間、休日","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"最初のご説明にありました、国家公務員と同様に区固有教員、あと幼稚園教員も超過勤務の上限を取り入れるといった後に、勤務時間のガイドラインの条例ですか、ちょっと聞きとれなかったのですが、それがどういうものなのか教えてください。","respondent":"熊谷指導課長","answer":"今回はあくまでも超過勤務を行うことができる上限時間について定める条例ということになっております。","voiceIndex":139,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"人事委員会の勧告というのは、具体的にもう出されているのでしょうか。ちょっとそこが余りはっきり聞き取れなかったので。人事委員会勧告の、多分まだ出ていない時期に区によってばらばらにこの条例が出されるところと出されないところとあるというのを伺ったのですが。なぜこの時期にこれを品川区が出してきたのかというあたりをまずお伺いします。","respondent":"熊谷指導課長","answer":"ですので、教員は別物ですよということではなくて、公務員として同じようにこの超勤の上限を定める必要があるということが文部科学省から示されたということで、今回の条例改正をお願いしたところです。","voiceIndex":141,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「準じる」という書き方をしているのと、参考の（１）と（２）のところで、（１）のところは１カ月について４５時間以下、１年については３６０時間以下と書かれていますが、（２）のところは他律的な業務の比重の高い部署に勤務する職員といって、ここの時間は飛び抜けて多い、過労死ラインをはるかに超えている部分なので、これを書くこと自体がどういう意味があるのかというのと。","respondent":"熊谷指導課長","answer":"ですので、まだ実は中身について、規則案については都からも、それから幼稚園関係の特別区人事・厚生事務組合からも全く案は示されておりませんので、国家公務員の例ということで出させていただきましたけれども、（２）のほうは。","voiceIndex":143,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"元来、労使間の合意というのは普通の労働者は労使間で３６協定が結ばれているのだけれども、そういう結ばれ方もしていないのが教員だという捉え方をするのと、あと現状において、さっきの文部科学省の新しいガイドラインを今策定中とおっしゃったけれども、それとこれは別ですということだったのですが、教員の働き方の今の多忙化、超長時間労働、このあり方の検討も全然示されないまま。","respondent":"熊谷指導課長","answer":"ただ、教育公務員については、４％の調整手当が出ているので、一律これに横引きで持ってくるということについて難しい部分もありますけれども、ただ、今回の条例はそういったことで改正になっているということです。","voiceIndex":145,"id":"exchange-038"},{"speaker":"石田（し）委員","kind":"質問","question":"第１０条第３項の「人事委員会の承認を得て、規則で定める」というところだけを改正するのであれば、別にそのガイドラインが示されてからというのか同時というのか、そのときの改正でいいのではないかと思ってしまうのだけれども、何で今回なのか、先ほどの説明でいまいちわからなかったので、改めて教えてください。","respondent":"熊谷指導課長","answer":"あくまでもこれから規則で何時間にしますというのが来ます、これから決めますというところで、まず今までは全く「上限」という言葉が出てこなかったところに、それを示すための条例改正ということになります。","voiceIndex":148,"id":"exchange-039"},{"speaker":"石田（し）委員","kind":"提案","question":"何となく理解をしたのですけれども、でもこれはレアケースですよね。超過勤務の上限というのが今までなかったのだけれども、それをつけますよ、それで規則でそれは何時間ですよというのを同時に提案しても、そんなに問題はないのかなと思うのです。私の今までの記憶の中にはこんな２段階の条例の改正は余りイメージがないのだけれども、何でなのかというのがもしわかれば教えてください。","respondent":"熊谷指導課長","answer":"それに伴って文部科学省からも同じようにやってくださいということで来ていますので、順番として、一緒にやるということもあるかと思うのですけれども、条例改正をした上で規則改正をしていく。","voiceIndex":150,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"反対します。ちょっと意見をよろしいですか。非常に悩んだところです。もう一点は、規則を見ないとどういうふうに書かれているかわからないというところで、とても判断ができないといった意味では、国の大もとの法律のところにとても危険な中身が書かれているということで反対せざるを得ないということで、反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-041"}]},{"id":"topic-07","title":"ただいま１２時少し前でございますけれども、次の議題に入りたいと思います。 次に、(9)第２９号議案、学校教育職員の給与に関する条例の一部を改正する条例","agenda":"ただいま１２時少し前でございますけれども、次の議題に入りたいと思います。 次に、(9)第２９号議案、学校教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"本当にこう思っているのですかね。有為な人材を確保、１,０００円、もちろん上がるのはすごくいいことというか必要な部分があるのはわかるのですけれども、どうなのかなと。これは都が行っていることですから余り言うことでもないのかなと思うのだけれども、その辺の考え方というか、今すごく教員の倍率も低くなってきてしまっているのですよね。","respondent":"熊谷指導課長","answer":"確かに１,０００円というのが有為な人材を確保するのに適しているかどうかというところは難しいところでもあるのですけれども、やはり教員になりたいという思いを持って、それを実現できる若者というのはこれから非常に日本の国をつくっていく上で大事ではないかと思っています。","voiceIndex":170,"id":"exchange-042"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１,０００円引き上げる等々も含めて環境整備というのはしっかりしていかなければいけないのかなと思います。それは教育委員会の大きな役割の一つになってくるのかなと思うので、ぜひ環境整備という部分では、効率化も含めて取り組んでいっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほどの条例のところにかかわるのですけれども、文部科学省で勤務時間のガイドラインを策定中ということで、教員固有のところの見直しについて、東京都においてもそういった検討とか実態に合わせたものに変えていこうというような議論があるのかどうか、ちょっと膨らむのですが、教えていただきたいと思います。","respondent":"熊谷指導課長","answer":"都のほうでも働き方改革についてはさまざま進めておりまして、働き方改革の成果の今後の展開についてということで示されているところなのですけれども、ちなみに、品川区の教育委員会の働き方改革の取り組みや。","voiceIndex":174,"id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"ちょっと細かい部分で教えていただきたいのですが、今言った、今回の改正に該当する方というのが９名という理解でいいのかという確認と、ここに言うところの、これは給料表自体の事務的な確認をさせていただきたいと思うのですが、質疑の間、改めて新旧対照表を確認してみたところ、いわゆる初任層というのは、職員の一人ひとりの資格ですとかそうしたものも当然あるのでしょうが。","respondent":"熊谷指導課長","answer":"今の段階で区の固有教員、対象となるところなのですが、２級の９号給から２級の３０号給までが対象となっておりまして、今年度は平成３０年４月、昨年の４月に初めて大学を卒業して教員になった方から、２年目、３年目、それから産休等でお休みされていた方。","voiceIndex":177,"id":"exchange-045"},{"speaker":"つる委員","kind":"意見","question":"１級、２級というのは、大学の、短大とかの、僕はどうかなと思うのだけれども、短大と四大のあれで１と２と等級でいうと違うのでしたか。","respondent":"熊谷指導課長","answer":"１・２級につきましてはご指摘のとおりで、短期大学卒業、四年制大学卒業ともにおるということになっております。","voiceIndex":179,"id":"exchange-046"},{"speaker":"つる委員","kind":"確認","question":"そうすると、これは全体としての特別区人事委員会の報告とか、それから東京都の人事委員会勧告による初任層というのは、ずっと見ていけば３級の６号給までぐらい、ちょっとその先、細く見てないのですけれども、いずれにしてもその中で品川区においては２級の３０号給までの中におさまる方が９名いて、それが今回対象ですと、そういうことですか、確認です。","respondent":"熊谷指導課長","answer":"そのとおりです。１級はおりませんので、２級の３０号給までが対象となっております。","voiceIndex":181,"id":"exchange-047"}]},{"id":"topic-08","title":"平成３１年請願第５号、一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"平成３１年請願第５号、一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"南委員","kind":"質問","question":"就学前までの保育を保障できる認可保育園を増設してくださいというふうに続いて書かれているわけですけれども、これの言わんとしているところ、私の理解は、３歳になったら小規模保育所から認可保育園に転園するとか、認証保育園も３歳未満のところが結構あるので、そこから認可保育園に転園希望を出すとかそういう現状があることを。","respondent":"大澤保育支援課長","answer":"３歳からの保育につきましては、今認証・小規模を卒園された方全員が認可保育園に入るだけの数は確実に確保していますので、そういった意味では整っていると認識しています。","voiceIndex":196,"id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"やはり子どもがそれこそ一貫した保育体制の中で就学まで同じ環境の中で育てていただけるということが大事ではないかと思っていますので、３歳の年齢で環境ががらっと変わってしまう、そういう状況が起きてしまっていることに対して、区はどういうふうに認識しているか伺いたいと思います。","respondent":"大澤保育支援課長、佐藤保育課長","answer":"保育士の数は、後にさせていただいて、３歳児の転園につきましては、現在の小規模保育や認証保育は区内に複数あることから、やはりそこの園の存在意義というのはありますので。正規に関しましては、約その半分、５５％程度、それ以外に関しては人材派遣や非常勤等で対応しているところです。","voiceIndex":198,"id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"そこはわかります。頭数をそろえていればいいのかどうかという考え方であってはならないと思いますので、その辺についての考え方も伺っておきたいと思います。認証保育園も小規模保育園も何らかの形で、否定的な意味ではなくいい意味で解消できるように、子どもたちが就学まで一つの同じ環境の中で育っていけることを保障していただきたいと思っていますけれども、改めてその辺についても伺いたいと思います。","respondent":"大澤保育支援課長、吉田保育施設調整担当課長、佐藤保育課長","answer":"必ず３歳児で受け入れはできる状況ではありますけれども、今後はやはり小規模や認証ではなくて。それとまた国では、民間でできることは民間でという方針もありますので。しかしながら、公立としては、特別支援であったりさらなる保護者支援等について、より進めている状況ですので。","voiceIndex":201,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"ゼロ歳から１歳のところでの一貫保育ができるようにしたいと、そこのところはそういう姿勢があるのだということを改めて確認できたので、ちょっとそこはほっとしたところですけれども、とにかく品川で育つすべての子どもたちが、このタイトルにあるように、一人ひとりが大切にされる、そういう保育行政というところを改めて深くかみしめていただきたいと思うし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"過去５年間の増設の数をもう一度教えていただきたいのと、あと請願にマンション建設によるファミリー世帯の増加が見込まれていますと書かれています。それで、さっき増設の数もお聞きしているところですけれども、現状においては増設しているけれども追いついていないと見ているのか、待機児童をなくしてほしいという願いが書かれているのですが、その辺の認識を聞かせてください。","respondent":"大澤保育支援課長、吉田保育施設調整担当課長","answer":"開設数につきましては、就学前人口増や就労率の増加を見込んで計画を立て直して、その計画どおりに今開設できておりますので、一定の需要を受けとめるだけの拡大はできていると認識しております。就労率の変化なのですけれども、今子ども・子育て支援事業計画というのを平成３２年度から新しく見直すための保護者向けの調査等をやっております。","voiceIndex":207,"id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"今のご説明だと、平成２５年度よりも１０％、保護者の皆さんの統計ですよね、既に預けていらっしゃるということですか。","respondent":"吉田保育施設調整担当課長","answer":"子ども・子育て支援事業計画をつくる意向調査の中では、就学前のお子さんがいる保護者の中から子どもの人数としては７,０００人分のサンプルを取りまして、その保護者に対して調査をかけた次第です。","voiceIndex":210,"id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"就学前ということで、区内全域でサンプルを選んだということなので、とても大事なことだと思います。この辺が、同じような状況で平成２５年に調査をして１０ポイントにということなのかどうか、そこももう一度教えてください。","respondent":"吉田保育施設調整担当課長","answer":"そのうちのたしか６割戻ってきたのが前回です。今回につきましては、就学前乳児人口が増えていることもありまして、７,０００サンプルをとったところです。ただし、回収率については若干下がっておりまして５５％程度で、前回よりも下がっているところです。","voiceIndex":212,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"確認","question":"その辺で昨年のところは不承諾通知が９５５だったのですが、この間のいろいろな答弁を聞いていると、待機児童は１９人でほぼ待機児童は解消したという答弁が何回かあったのですけれども、これにあわせて、今年の一次のところをもう一度確認させてほしいのです。","respondent":"大澤保育支援課長","answer":"追加でご説明すると、現在のところ二次の空き状況は１,１３７人になっています。平成３１年４月の入園状況ですが、平成３０年４月とほぼ同様の状態になると現時点では見込んでおります。","voiceIndex":214,"id":"exchange-055"},{"speaker":"飯沼委員","kind":"意見","question":"３歳以上の子どものところで待機児童が出ている、不承諾通知を受け取った子が１５２人もいると、これは大変な事態ではないかと思うのと、こういうのも含めて、一人ひとりのお子さんのことを考えたら、１人として入れない子どもはこれからどうするのだろう、幼稚園のところはとっくに終わっているというところでこの辺をどう考えているのかをお聞かせください。","respondent":"大澤保育支援課長","answer":"もちろん、いろいろ個別のご事情がありますから、他の園に行ってほしいということを申し上げているのではなくて、区として受入れ枠はしっかりありますということをご説明しているところです。","voiceIndex":216,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、すみません、もう一度元に戻りますが、平成３０年は９５５人が不承諾だったのですけれども、そのうち待機児童が１９人になっていて、ほかの人は待機児童ではないという扱いをしているあたり、私はここの数字の出し方、ぜひ明確な数字で教えていただきたいのです。９５５人がどうして１９人になるのか。ちょっとそこの数字の減らしていく中身を教えていただきたいと思います。","respondent":"大澤保育支援課長","answer":"不承諾の考え方なのですけれども、転園希望の方とか、入園が決まったけれども辞退をされる方というのが去年も３３１人出ていますし、ここからまた今年度も辞退をされる方がいて、そこに繰り上げで入る方が二次等で出てきますので。","voiceIndex":218,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"認証に預けていて認可を希望しているのです。待機児童のカウントの仕方を変えたのですから。改善もしてほしいと思うので、この待機児童、昨年の１９人、これが正しい数字でほぼほぼ解消したなどという宣伝はやめていただきたいと思うし、ここに書いているように、待機児童をなくしてくださいという願いを真摯に私は受けとめていくべきであると思っています。このことが一つです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これをどう考えていらっしゃるのか。そんな状況の中で、一番に安定した保育の保障をしていくためには、やはり公立の保育園が求められているのが私は当然であると思うので、こんなに保育園が足りなくて次々にできていて、中には問題を持っている保育園もできているといった中で公立をあえて民営化する必要は全くないと思っているのです。この点について見解をお聞かせいただきたいと思います。","respondent":"大澤保育支援課長、吉田保育施設調整担当課長","answer":"認証を含めて既存の施設の活用を前提として待機児童解消を進めていくことがやはり区として何年、何十年か後のこともありますので、それが適切な判断だというふうに考えています。民営化した際の安定的な人手不足の解消だとかその辺のところなのですけれども、比較的区として立地条件のいい保育園を民営化していくことを予定しております。そうしますと、立地条件がいいということはよい業者が集まりやすい。","voiceIndex":222,"id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"園庭はもちろん求めているのですが、地域の公園不足、遊び場が不足していることを保育支援課としてどのように受けとめ、考え、改善しようと考えているのか一点お聞きをしたい。３分の１ぐらいの平米数しかないのです。荏原もそうなのです、２分の１ぐらいで。この子たちはどこで遊んだらいいのですか。そういった面で保育支援課と公園課の両面にお伺いしたいので、よろしくお願いします。","respondent":"大澤保育支援課長、溝口公園課長","answer":"保育園の公園活用ですけれども、新規の園には近隣の保育園と調整して遊ぶようにというお話はしていて、私立園長会等でもいろいろな保育園が使うから譲り合ってください、一般の方もいらっしゃいますからというお話はさせていただいて。そういったものについては、引き続きやはり不動産とかそういったものも問いながら、公園としての適地、そういったものを探しながら、公園の整備には当たっていきたいと考えていますし。","voiceIndex":225,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公園、つくってください。子どもたちはどんどん育つのです。子どもたちというのは、日々よい環境で育てないと心身ともに成長が阻害されていくのです。もっと実態を知っていただきたい、園庭が必要だと。園庭も必要ですが、園庭で間に合わなかったら近くに公園をつくる、そのくらいの努力、未来の子どもたちのためにしていただきたいと思いますが、最後に一言、保育支援課と公園課にお聞きします。","respondent":"溝口公園課長","answer":"これからも新たにつくっていきたいと考えていますし、現状の公園も皆さんにより親しんでいただけるような整備、そういったものも行っていきたいと考えているところです。","voiceIndex":228,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委員長、聞いていることに直接、答えてないです。答弁をすればいいというものではないです。足りないところにつくっていただきたいと言いました。区民の皆さんから切実に出されているものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"質問者が納得し得ないような答弁だったら、また聞くしかないではないですか。きちんと発言させるべきですので、そういう運営をしてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-063"},{"speaker":"石田（し）委員","kind":"質問","question":"委員長が委員会を運営するに当たって、いろいろと調整するのはあることです。そのことに対してどうこうというのは、それは委員会運営の一つの調整ですから、そこは私は一定の理解をせざるを得ないのかなと思うので、そこだけは私もつけ加えておきます。ぜひそこは、理解する部分は理解をするというのも必要なのかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-064"},{"speaker":"南委員","kind":"意見","question":"委員会運営に委員長としてのいろいろな判断はあり得ると私も思っています。であるのだったら、委員会運営上こうしたいからと説明があってしかるべきです。それもなくて、一方的に判断してとめるというのは委員会運営としてはどうかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":237,"id":"exchange-065"},{"speaker":"渡部委員","kind":"質問・要望","question":"需要と供給のバランスをこの２３km2の中で考えたときに、それはしっかりとれていると会派としては認識しておりますし、今後子どもが増えていくということも確認させていただいている中で、それについても多様な方法で将来的な待機児童解消を目指してくださいということについて、区としてはしっかり政策を進めていただいています。公立保育園等につきましては、私たちは常に民営化を求めています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-066"},{"speaker":"つる委員","kind":"質問・要望","question":"当然さまざまな設備、また人員含め認可というところが一定求められるところであります。ただ、制度に人をはめていくような視点に見受けられるような形での求め方というのは、私は違うと思いますし、現実にそこにいる子どもたちの幸せのためにどう柔軟な対応をして、その子どもの健全な保育を担っていくか、担保していくかというところで、この間品川区は行ってきたと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":240,"id":"exchange-067"},{"speaker":"南委員","kind":"質問・要望","question":"この最低基準が現状に合っていなくて改善をしてほしいとう声が出ているにもかかわらず、この基準よりも低い多様化で十分だというのは明らかに私は間違っていることであると思っています。ぜひ公立保育園の基準がとても大事だということにおいては存続を求める、これも当然です。直ちに整備と改修が必要であると思いますので、この３つの請願項目はもっともであると考えていますので、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-068"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それはもちろん、ベンチをつくって高齢者の方たちがそこで休めるとかそういった部分はあるのかと思うのですけれども、では子どもたちが遊ぶ遊具でかつ高齢者も一緒に遊べるような遊具をというのはなかなか難しい話ですので、私はそのところどころのニーズだったり規模だったり、そういうのも含めてしっかり総合的に判断をして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":242,"id":"exchange-069"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、さまざま議論があったのですが、請願項目に関しての意見として、１番目のところでは、区のほうでは認可保育園をこれまで５年の例を挙げていただきましたけれどもつくってきた。もちろん１歳の方々がなかなか厳しいような現状もあるので、より一層スピーディーにということと人口の増加に対応する形を求めていきたいとは思いますが、現状実際に行われているのでという認識を持っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":243,"id":"exchange-070"}]},{"id":"topic-09","title":"平成３１年請願第１１号、小中学校の給食費の無償化を求める請願","agenda":"平成３１年請願第１１号、小中学校の給食費の無償化を求める請願","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"給食費の負担について、今説明がなかったので改めて伺いたいと思いますが、事務事業概要に小学１・２年生で２４０円等々書いてあるのですけれども、その金額でよろしいのか。そうすると、５・６年生は１日の食単価２８０円かける月、月は２０日で計算するのでしょうか、月額と年額がどういうふうになっているのか。","respondent":"篠田学務課長","answer":"国の動向についてですけれども、今回、あくまで給食費の無償化ですので、それについて今後国のそういった施策の中に給食費無償化にかかわるような施策が打ち出されるかどうかを注視してまいりたいと、そのようにお答えしたものです。","voiceIndex":250,"id":"exchange-071"},{"speaker":"南委員","kind":"質問・要望","question":"やはり今子どもを健全に育てる、そういう状況が求められていますし、それから今、子ども食堂というのが品川区でも１７カ所だったか、できているという状況を見ると、家庭での食事の状況が決して好ましい状況にはない家庭が結構あると捉えたときに、やはり給食の持つ意味は相当大きな意味があると思うのです。その点について、実態的に教育委員会としてはどういうふうに見ているのかも含めて考えを伺います。","respondent":"篠田学務課長","answer":"平成２０年からずっと同じ金額で維持しているということがありますので、委員ご指摘の順位よりも今はもう少し下に下がっている状況があったというふうに認識しています。","voiceIndex":252,"id":"exchange-072"},{"speaker":"南委員","kind":"質問","question":"来年度の予算も２５０億円ぐらい基金から取り崩していけているという、財政的に余裕がある区というところで、やはりそういう財政状況にあるわけですから、やはり品川区で育つ子どもたちにいろいろな教育条件、いい条件を提供していくという考え方に私は立つべきだと思のです。できない状況ではないと思います。教育の無償化という点とこの給食費の無償というところは、その中に入れて考えられないのかどうか。","respondent":"篠田学務課長","answer":"これは、せんだっての決算特別委員会でもご指摘をいただきましてお答えした金額ですけれども、実際に今いるお子さん方に対して無償化をするとなると、新に発生する経費は８億５,０００万円をこえる金額になるのではないかというお答えをさせていただきました。","voiceIndex":254,"id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、国の無償化を待つまでもなく、教育のこういう分野でも品川区は先進自治体というふうにとっていただきたいと私は思います。先ほど審査した１８歳までの入院にかかる医療費の無料化についても、２３区の中で品川区は３番目にスタートするということです。教育にお金をかけることが無駄なお金なのかどうか、そこについての認識を最後に伺って終わります。","respondent":"篠田学務課長","answer":"私どもといたしましても、できるだけ魅力的な教育をお子様方に提供したいという思いを持ってありますけれども、やはりそれは優先順位等を考えながら、どこまで何に取り組んでいくのかというのは、さまざまな状況を判断しながら考えていくべきものだと考えるところです。","voiceIndex":256,"id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"就学援助の割合を改めて教えていただきたいのと、あと、就学援助が受けられている、困難な低所得者の人は生活保護を受けている、あと、先ほどは多子家庭の３人目以降の補助も行っているということなのですが、今本当に子どもの貧困が問題視されていますし、朝食も食べない子どもがいたりとかそういう意味で、子どもが本当に健康、健やかな成長のためにいろいろな手立てがとられ始めているのですけれども。","respondent":"篠田学務課長","answer":"就学援助の小中学校の割合、人数でしょうか。","voiceIndex":259,"id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問","question":"規定に沿ってということですけれども、最低限ではある。これ以上は今は考えていないと。最低限をしているという捉え方なのですか。給食費の未納の状況はどれくらいあるのか、わかったら教えてください。","respondent":"篠田学務課長","answer":"給食費の最低限というお話ですけれども、要は法律に基づいた必要な対応をとりつつ、また低所得者等に対する施策も行っているという形で考えているところです。","voiceIndex":263,"id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区のアンケートでもはっきりしていますよね、経済的支援をしてほしいというのは。区の子育て世帯アンケートでも理想の子どもの数の実現の見通しの質問に、４割以上の方が実現は難しいと。子どもを３人持ちたくても１人ひとりにかかるので無理だといって１人から２人でとどまっていると。品川区はそういう力があると思うので、ぜひ踏み出していただきたいのですが、いかがでしょうか。","respondent":"篠田学務課長","answer":"そうしますと、無償化によりましてこの利益を享受できる方がどうしてもお子さんを通わせている保護者の方、ご家庭のみという形になってまいりますので、政策としてそれが一般の区民の方に受け入れられるかどうかというのは十分考えていく必要があろうかと考えているところです。","voiceIndex":265,"id":"exchange-077"},{"speaker":"石田（し）委員","kind":"質問","question":"先ほどの未納率の状況が出ていて、極めて品川区の場合は低い状況にあるのかと思うのですが、未納の対応、回収というのでしょうか、対応は誰がやっているのか教えてください。それと、未納が続いていて払わないとなった場合に、その子は給食が食べられないのか、そういう事例があったのか教えてください。","respondent":"篠田学務課長","answer":"ですので、ほかの自治体ですと先生方が教室で、お子さんから給食費を集めて、足りなかったらどうするかという対応をとっているところなのですけれども、品川区では全て事務室のほうで行っていまして、さらに全てご入学のときに口座振替の手続をとっていただいていますので。","voiceIndex":268,"id":"exchange-078"},{"speaker":"南委員","kind":"質問・要望","question":"そうではないですか。教育費予算との比較を正確にしていないのであれですけれども、やはり優先といったら今品川区が進めている開発、そういうものよりも教育は優先順位が低いですか。そういうふうに見ていいのでしょうか。ちょっとその辺の認識を伺いたいと思います。こういうふうに考えることは正論なのでしょうか。それで終わりにしたいと思います。","respondent":"篠田学務課長","answer":"公平性については、私のほうからは、先ほど区民の方から広く理解を得るのが難しいのではないかというお話をさせていただいたので、公平か公平でないかという言い方はあまり私もしたつもりではないのですけれども、そのように受けとめられたのであれば。","voiceIndex":271,"id":"exchange-079"},{"speaker":"南委員","kind":"質問・要望","question":"もっとしっかりと、失礼な言い方をしてしまって許していただきたいのですけれども、そういう部分にお金をかけるということについては、自信を持ってやっていただきたいし、区民の皆さんにも理解はしていただける問題だと思っていますので、そういう角度で一つひとつの問題を精査していただきたいということをあえて強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":273,"id":"exchange-080"},{"speaker":"つる委員","kind":"質問・要望","question":"請願の文章の確認からですが、最後に書かれている「憲法２６条では『義務教育は無償』」ということで、この憲法第２６条の理想を実現していくというか近づけていくという意味では、国政において公明党が教科書無償配布を加速させた質疑があって全面的に展開されたという経緯の中、その当時の議事録をひもとくと、憲法第２６条には義務教育の無償をうたっているから。","respondent":"篠田学務課長","answer":"憲法における第２６条の無償化の範囲です。こちらに関しましては、申し訳ありません、今手元にきちんとしたものを持ち合わせてないのですけれども、基本的に個人にかかるもの以外を無償化していくといったものであるように記憶しております。","voiceIndex":275,"id":"exchange-081"},{"speaker":"つる委員","kind":"提案","question":"あるのですが、国の財政等の事情を考慮して立法政策の問題として解決すべき事柄であって云々というところで、最高裁の判例としては、授業料が無償化のというところなのだというところがあって、そうしたやはりきちんと事実関係も確認をしていただいた上で、こういう請願の文章にしていただいたほうがよかったのかなというところがあるわけです。ただ、これは離島なのです。お考えがあれば教えてください。","respondent":"篠田学務課長","answer":"租税収入等がどのぐらい延びるのかですとかそういったことも十分見ながら、場合によっては基金の取り崩しですとか、そういったものをしないと一般財源は生み出されませんので、そういったことで財政全体の予算立てのときの工夫が必要になってくるかなと思います。","voiceIndex":277,"id":"exchange-082"},{"speaker":"つる委員","kind":"質問・要望","question":"ですから、ただ、そうした部分でも早急に全国的な、国を挙げてのそうした取り組みというのは求めていきたいというところなのですが、８億５,０００万円という財源の確保について、先ほどちょっとざっくりとした聞き方でお聞きしましたけれども、そこも含めて国の支援策、これをしっかりと見ていく必要性もあるのだろうなと思うのですが。","respondent":"篠田学務課長","answer":"特に今、国のほうでは子育て支援に関してさまざまな形での支援が検討されている状況ですので、学校給食もどのような形でかかわってくるのかということにつきまして、十分注視してまいりたいと考えておるところです。","voiceIndex":279,"id":"exchange-083"},{"speaker":"つる委員","kind":"確認","question":"一方で、またアレルギーのお子さんの対策等も今後あるわけです。そのあたりは、先ほど申し上げたとおり、公明党としては区としての支援策を今しっかり検討させているところというスタンスがあるので、今ちょっと聞いた中で区のお考えを確認できたので、わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":281,"id":"exchange-084"},{"speaker":"渡部委員","kind":"質問","question":"本日結論を出します。結論から言うと不採択です。決算特別委員会でいろいろ伺わせていただいて、そのときにも調べさせていただいて、今つる委員から話があったように、無償でやっているところというのはほとんど町村が多くて、そういうところというのはともかく自分の村、自分の町、我が町に子どもがたくさん来てほしいという施策の一つです。会派としてもそう思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-085"},{"speaker":"渡部委員","kind":"意見","question":"安全なものを子どもたちに提供するために幾ら必要なのかということで、たしかこの間の決算特別委員会で値上げしろと私は言っていたと思うのですけれども、しっかりとその時々の状況を見ながら、しかるべき費用はご家庭にその分、負担をいただいて、お子さんが３人以上いるようなところはその分は補助しますよというスタンスで、基礎的自治体としては今のままでいいのかなと私は思っていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":285,"id":"exchange-086"},{"speaker":"つる委員","kind":"質問・要望","question":"そうした意味からも、国の動きもある中で、党としてもそういうことも含め、しっかりとそれを今後も注視し、そして推進させ、品川区を含む全国のそうした自治体の学校給食への支援、これがきちんと結実する方向をこれからも推進するという意味で、先ほど区で単費で行った場合の財源の規模も概算ですが確認させていただいた中では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":286,"id":"exchange-087"},{"speaker":"南委員","kind":"質問・要望","question":"今日結論を出すで採択です。私たちは、先ほどの質問の中で表明してきましたけれども、やはり子どもたちの教育にかかわる費用については、無償化であるべきだと。それから、先ほどつる委員のほうから憲法２６条の部分のところ、判決の関係でもう少し精査をというお話がありましたけれども、やはり区民の方々にそこまで求めるということは酷かなと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":287,"id":"exchange-088"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今、国でいろいろと無償化、いわゆる子育てをどうやってやっていくのかという議論がされている中で、確かに国がやるべきものだと思っていますし、そこを強く我々も求めているところでありますが、区でできるのであれば、まずこの品川区で東京の特に２３区の中で始めて、それが大きなうねりとなって国に届いて、国が最終的に無償化をしていただくのだったらそれに越したことはないかという思いもありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":288,"id":"exchange-089"},{"speaker":"高橋（し）委員","kind":"意見","question":"結論を出すで、不採択です。そういったところから、もっと広い範囲での義務教育というところの給食費については考えていくべきだということで、現状無償化というのは、先ほどもあったように財源のほうの関係からなかなか状況的には厳しいことで、国のほうの政策も、先ほど注視していくということがありましたので、そちらをきちんと見ていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":289,"id":"exchange-090"}]},{"id":"topic-10","title":"を行います。 専決処分の報告","agenda":"を行います。 専決処分の報告","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"１点だけ。貸し付けの返済に応じない理由というのは把握されているのか、どのように把握しているのか教えてください。","respondent":"廣田子ども家庭支援課長","answer":"この方は貸し付けを受けた後に、区外、東京ではないところに転居されておりましてしばらく連絡がとれなかったところです。再三にわたり督促を行っており、お母様とは電話番号がわかりお話はできましたが、連帯借受人とは連絡が一切取れない状況にあるといった状況です。","voiceIndex":296,"id":"exchange-091"}]},{"id":"topic-11","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"「競争で子どもを追い込む品川『教育改革』から、子どもの権利条約活かした教育への転換を」の質問の中で、質問の４、「教員の多忙化解消へ土日祝日を含めた在校時間を把握すること」ということに対してのご答弁が、出退勤システムで管理していますということだったのですが、この出退勤システムの管理というのがどういうものなのか教えていただきたいのと、あと、土日祝日の在校時間に関しては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":302,"id":"exchange-092"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4964#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":76163,"voices":304}},{"id":"r01-20190225-5","meetingId":"r01-cm02","date":"2019年2月25日","dateIso":"2019-02-25","committee":"総務委員会","time":"午前１０時００分～午後 １時０５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"要するに、どうなるということですか。この条例を施行することで、品川区の業務内容が劇的に改善をされるというか、すごくやりやすくなるのか、わからないのですけれども、法令が変わったので品川区の条例を改正したのはわかるのですけれども、どういうことなのかなと。","respondent":"山本情報推進課長","answer":"一方、事務の廃止というところで今回２つの事務が廃止になるのですけれども、この事務で、個人番号を使うためには条例のほうで事務を定めておかなければならないという法律の規定がありますので、今までそれを使っていたのですけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問","question":"先ほどご説明にありましたけれども、個人番号の利用を定めることによって、わざわざ証明書等をとらずに申請が可能になるということは、俗に言うワンストップサービスではないですけれども、そういうのがだんだん可能になってくるということでよろしいのかというのが１点と、区独自の利活用を行うためというのも、この理由の中に入っているのですけれども、要は。","respondent":"山本情報推進課長","answer":"１点目の添付書類の省略のところなのですけれども、委員おっしゃるとおりでして、情報提供ネットワークシステム等を使い情報連携を行うことによって、区民の方は添付する書類の一部省略が可能になるということになっております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"確認","question":"先ほどのやりとりで、添付書類の一部がなくなると説明がありましたけれども、この進学準備給付金を申請するに当たって、何がどう変わるのか伺いたいと思います。合わせて、進学準備給付金の申請時に個人番号を記入しなくても、申請する区民に不利益になることはないのか、その点も確認したいと思います。","respondent":"山本情報推進課長","answer":"進学準備給付金で何が変わるのかというところで、先ほど一部お話ししたのですけれども、仮に新たにこの制度の申し込み手続きをされるというときに、区外から転入してきた方の前住所地の課税状況であったり、生活保護情報をこちらでは把握していないわけですので。","voiceIndex":10,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"手続きの一部省略ですけれども、区外の方というご説明がありましたが、区内の方は基本的に変わらないのか確認させていただきたいのと、記入をしなくても不利益にならないということは、個人番号を書かなくては事務処理はできるということなのか伺いたいと思います。","respondent":"山本情報推進課長","answer":"番号の記載がない場合なのですけれども、こちらは区の取り扱いで、本人確認の手順等を作成しておりまして、番号の確認がとれない場合は、住民情報システムで個人番号を職員が検索して、それを使うということを、あらかじめご本人にご説明した上で。","voiceIndex":12,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"これを記入したくないのだけれどもと言うと、それは記入しなくても大丈夫ですよ、手続きは当然行われますということをお伝えして、ああ、そうですかというふうにして、皆さんそのまま手続きされるのですけれども、やはり一般の区民は、個人番号を書かないとだめなのだと、あたかもそういうふうに読めるような記載がされています。今後、これについてどのような記載がされるか教えてください。","respondent":"山本情報推進課長","answer":"今回の進学準備給付金の事務の申請のところなのですが、まだ実際の利用ケースはないところになっているのですけれども、具体的にどういったご案内をしているかは把握しておりません。","voiceIndex":15,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"把握されていないということであれば、ぜひ、今後そういう記載については、個人番号を提出していただくことが前提だとしても、記載がなくても大丈夫ですということが、きちんと読んだ段階でわかるような記載をぜひしていただきたいと思います。それは要望しておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"中塚委員","kind":"確認","question":"態度表明をしたいと思います。女性福祉資金貸付事務の廃止に伴う削除ですが、この制度を継続すべきだと思うので、削除すべきではないと思います。最後に、進学準備給付金を加えるということですが、先ほどのやりとりでも、区内の方の利便性は特に見当たりませんし、個人番号を記入しなくても事務に支障はないということが確認されました。よって、番号法をさらに拡大させるものなので、反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-007"},{"speaker":"吉田委員","kind":"意見","question":"反対です。意見もつけ加えします。基本的に番号法自体に反対をしているということ。ただ、条例を法に従って改正ということではやむを得ないとは思いますけれども、基本的に番号法自体に反対しております。こうやって区の条例の中でも利用範囲が広がっていくことは、その危惧が現実となるということですので、反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-008"},{"speaker":"いながわ委員","kind":"質問・要望","question":"資料を見ると、職員の定数が９人増えたけれども、それとは別に、付則では７０人を限度としてと書いてあるのですけれども、要は過員という言い方なのか、これは今、実際に過員が全部の部署で何人ぐらいになっているのかわかれば教えていただきたい。要するに、数字のトリックではないですけれども、増えているのか減っているのかというのが現実わからなくて、過員もあるわけですから、どういう状況なのかなと。","respondent":"黒田人事課長","answer":"過員の７０名の考え方ですが、いわゆる定数外の職員、多くは病気休職、休職している職員ですとか、育児休業による休職者というところが定数外となっておりまして、例えば育児休業ですと、産休が終わった後に休職に入りますと、定数外になるのですが、結局。","voiceIndex":32,"id":"exchange-009"},{"speaker":"いながわ委員","kind":"質問・要望","question":"定数条例だけ見てしまうと、１２名減らして２１名増やしているのだというふうな安直な判断しかできない気がして、確認をさせていただきました。職員を増やしていただきたいというオーダーは全体で大体どれぐらい来ていたのか、またその要望がかなわなかったのは全体的に見て、どういう理由でかなわなかったのか。","respondent":"黒田人事課長","answer":"なぜかなわないのかというご質問ですが、１００名全て増員するというわけには、財政上の負担というのが何十年にわたるということもありますので、その年度の閑散期と繁忙期で、一定程度、増分に満たないような仕事につきましては、アウトソースなどを活用できないかなど。","voiceIndex":34,"id":"exchange-010"},{"speaker":"いながわ委員","kind":"質問・要望","question":"やはり１００人増やすのはどうかと思うのですが、ただ、適材適所、必要な配置というのは常々考えて、スリム化しつつも、区民サービスを低下させない人員配置をしっかりやっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"資料のつくり方なのですけれども、冒頭それぞれの増減についてご説明がありましたが、この資料だけだと増と減の数字だけなのです。ぜひ、資料に増減の理由を記載するなど、資料は丁寧につくっていただきたいと思うのですが、いかがでしょうか。全体的な話として、行財政改革という説明がありましたが、この定数の増減にかかわって区が考える行財政改革とは何なのか端的にご説明いただきたいと思います。","respondent":"黒田人事課長","answer":"職員数につきましては、あくまでも採用の計画、見込みでございまして、内定辞退等があれば採用できると見込んでいた職員数も減るということで、この課にこういう理由で何人配置するということを資料に記載することはなかなか難しいところですが、資料の記載方法について。","voiceIndex":37,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"行財政改革についてですけれども、先ほども、各所管からは１００名ぐらいの要望がある中で、今回２１増１２減ということですけれども、とりわけ、新規に事業が増えたので増員するというところと、職場によっては残業が多いため増員するというところがあるかと思うのですけれども、残業が多い理由で定数が増になった課というのは具体的にどこなのか、これが１つ目の質問です。","respondent":"黒田人事課長","answer":"２点目の、障害者福祉課のことを例にいただいておりますが、ほかの部署も、当然いろいろ執行の工夫を図り対応していただいているところもありますが、資料に記載していないところでも、一定程度、過員という形で人員配置は行っておりますので。","voiceIndex":39,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"児相の関係なのですけれども、今回、児童福祉士と児童心理士がそれぞれ３名増ということですけれども、現状でご説明できる範囲でいいのですけれども、将来的にはどのぐらいの規模になるという見通しを持っているのか、ご説明いただきたいと思います。次に、今回、品川歴史館の学芸員が定数化されたことは高く評価しております。どのような役割を位置づけているか、その点を伺いたいと思います。","respondent":"黒田人事課長","answer":"保育園の用務につきましては、今のところ用務職を配置していない保育園には非常勤職員、３時間の職員を２名体制で週５日配置しているという状況ですが、こちらも新年度の予算で所管から、環境整備において、清掃等については事業者に取り計ることで。","voiceIndex":41,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから多分、去年の定数条例の審議のときに、障害者福祉課の体制を変えると、今までは縦割りの相談しかできなかったのを、どの障害者に対しても相談できるような体制にするということが前提となっていて、３月３１日まで今までどおりで、急に４月１日から無理ではないですかと言ったのですが、案の定無理で、元に戻してほしいという要望も今出ているわけです。","respondent":"黒田人事課長","answer":"障害者福祉課の体制につきましては、所管からの要求に基づいて人員を配置しておりますので、執行体制、業務のやり方については所管で検討されると認識しております。","voiceIndex":44,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"先ほどの説明だと、時間数だけです。もともとが仕事量、うちの課ではこれだけの仕事量があるから、１人当たりこれだけ働くとこれだけの人数が必要になりますというふうなことを出させるのかなと思ったのですけれども、可能な限り係数的に記入せよと指示しておられますので、業務量をどのような形で、算出しているのでしょうかということを伺ったので、もう少し詳しく教えてください。","respondent":"黒田人事課長","answer":"可能な限りと申し上げておりますのは、例えば、何かの届け出件数が１,０００件増えている、前年比１.５倍という場合に、１件の処理のかかる時間数が５分なのか、１０分なのか、１件でも１時間相当かかることもあるのではないかという意味で言うと。","voiceIndex":48,"id":"exchange-016"},{"speaker":"吉田委員","kind":"提案","question":"済みません。まとめて聞けばよかったのですが、やはり定数があって、過員がある。その定数以上は増やせないから過員で配置するというのは、何か本末転倒のような気がして、やはり仕事量がこれだけあってこれだけ必要ということであれば、定数を増やす条例提案を受け議会の中で議論していくものではないかと思うのです。理解が悪くて申しわけありませんが、もう１回説明していただけますか。","respondent":"黒田人事課長","answer":"先ほど申し上げた職場に配置している定数と定数条例で定めた上限のところで職員を機動的に、本来年度間で配置できるという意味では、同じ定数という言葉を使っておりますが、意味合いが違うというものです。","voiceIndex":50,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問","question":"理解が悪くて済みません。では、この資料にある定数というのは、定数条例の定数ではないということですか。","respondent":"黒田人事課長","answer":"所要人員上で言っている定数と、条例上の定数は、定数という同じ言葉ですけれども、意味合いが違いますので、そこのところはご了解いただきたいと思います。","voiceIndex":52,"id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"全部足し合わせてはいないのですけれども、では、この資料上の定数というのは、足し合わせても定数条例にある数にはならないということですかね。","respondent":"黒田人事課長","answer":"平成３０年度で申し上げますと、配分定数を足し上げますと２,２５５でございまして、職員の現員数は２,４９９という意味では、２４０ほどの差があります。ここの部分はいわゆる過員となっておりまして、あくまでも定数条例は職員の人数の上限だです。","voiceIndex":54,"id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"現員というのは、それぞれの職場に過員配置されている人も含まれると考えてよろしいでしょうか。","respondent":"黒田人事課長","answer":"現員と書いてありますのは職員の数でございまして、それは定数条例の中で言う職員の数と同じものです。","voiceIndex":56,"id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"それと、先ほど保育園の用務職を、外部委託するということで非常勤職員の負担を軽減するというような話しでしたけれども、今まで、保育に専念できない状況が非常に負担になるということで質問させていただきたいのですが、その負担感は一定解消の方向にあるというふうに理解してよろしいでしょうか。","respondent":"黒田人事課長","answer":"そのほかに非常勤職員を配置して、有資格であったり、無資格非常勤は用務の代替等としていれておりますが、そのほかにも登園時・降園時の見守りも行っているというふうに伺っておりますので、清掃業務等を、全園とは聞いておりませんけれども。","voiceIndex":58,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"もし間違いがあったらそれも教えてください。そうすると、そういう方もここに載せておかなければだめではないですか。その方たちが戻ってきて、では２,０００名が２,０７０名になりましたと。でもそれは、条例では何ら違反行為ではないわけです。そうすると、我々はこの資料を見て、正確な職員数、それから正確な業務をどういう方たちが何人で担っているか、全くつかめないではないですか。教えてください。","respondent":"黒田人事課長","answer":"定数外職員における非常勤職員の数については、平成３０年度で言いますと年度当初で１,３００名ほど雇用しておりますので、そういった意味では正規職員と非常勤職員で区政を運営しているというのはご指摘のとおりです。","voiceIndex":60,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"その方たちの数について審議するとは言っていないです。だけれども、一体、全体として何名の方が区の業務を担っているというのは、全然これではつかめないではないですか。先ほど少し申し上げましたけれども、例えば休職中の７０名が戻ってきても、それは２,０００人として、７０名増えたって定数は２,０７０名ですよということで、条例違反にも何もならない。もう一度、ご見解をお聞かせください。","respondent":"黒田人事課長","answer":"条例審議の場でお示しするのか、予算審議の場で議論をいただいておりますので、そういった中で資料の出し方については検討させていただきたいと思います。","voiceIndex":62,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"態度としては反対です。理由を述べますと、問題点と改善された点がありますが、一般事務については１０増という意味では、一定改善しているとは言えるものの、１,０００名を超える非常勤職員の存在や、障害者福祉課の多忙化など、さらに改善をすべき点があると思います。児相については、今後どういう方向性が示されるか、国の動向も踏まえつつ、しっかりとした体制とするよう要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-024"},{"speaker":"いながわ委員","kind":"質問","question":"基本は総合的に見て賛成なのですが、先ほど申し上げたように適材適所、人員要求も入っているわけですから人員配置をしっかりとやっていただくということで、いただけるという大前提のもと、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川・生活者ネットワークとしては、結論としては反対したいと思います。非常勤職員ということでは、保育士の資格を持っていない人たちが今いっぱい増えていて、いろいろ保育上の課題があるということを伺っています。やはり、委員会の中で資料を出してほしいということをもっと請求すべきだったと思います。議員としての役割を果たすためという理由で、求めてはいけなかったなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-026"},{"speaker":"いながわ委員","kind":"質問","question":"地域の団体でも働き方改革における超過勤務などについては、地域の団体の青年部と言うのですか、社長の集まりなどに行くと、こういう話が頻繁に出てきていろいろやるのですけれども、要するに超過勤務の上限を決められてしまうではないですか。そのメリットとデメリットと言うのですか、区役所側のメリット・デメリット、職員側のメリット・デメリットがそれぞれあると思うのです。","respondent":"黒田人事課長","answer":"メリット・デメリットという意味で言うと、職員にとっては、健康を害して仕事をしないようにということで、一定程度、今もこちらで月間８０時間の残業を超えるような職員については所属長が必ず面談をして人事でチェックをして。","voiceIndex":78,"id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問","question":"おっしゃることは理解するのですけれども、要するに、これは民間の労働法制ですから、民間会社と労使関係にある労働者の間でこういうような取組み、すごい残業時間による自殺者であったり過労死というのは実際にあったのも事実で、それは社内でいろいろやるべきだと思います。それは、民間もそうだと思うのですけれども、有利なのは役所側になるのかなと。","respondent":"黒田人事課長","answer":"もう１点、好きで残業しているわけではないというご指摘がありましたが、先ほど申し上げたとおり、１時間で終わる仕事を突き詰めて２時間かけてやるというようなこともあろうかと思いますが、そういうことではなくて。","voiceIndex":80,"id":"exchange-028"},{"speaker":"いながわ委員","kind":"質問","question":"私も質問しながらだんだん何を聞きたいのかがあれだったのですけれども、全国的に４月１日から施行されるわけではないですか。そうすると、この制度の運用が始まることで、品川区役所全体の人件費というのは抑えられてくるということになるのですか。要するに、これをやることによって、人件費は平成３０年度より平成３１年度のほうが、やはりさまざまな部分で支出は抑えられるという感覚であるわけですか。","respondent":"黒田人事課長","answer":"全体の人件費から見ると、それほど大きな額というわけではございませんが、そういった職員は長時間労働をしているということでは間違いございませんので、健康確保も含め、仕事の能率化も含め、対応していきたいと考えています。","voiceIndex":82,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"過労死ラインを超える上限まで働かせるというものは、まさに最悪の法案に対する最悪の条例改正だと私は思います。実態を伺いたいのですけれども、１カ月間の超過勤務が８０時間を超える方、１カ月の超過勤務が１００時間を超える方、それぞれ何人いらっしゃるのか伺いたいと思います。そして、品川区としては、この超過勤務を減らしたい、改善したいという立場なのかどうかご説明いただきたいと思います。","respondent":"黒田人事課長","answer":"全体的に超過勤務は減らしつつ、区民サービスの向上を図りたいと考えております。","voiceIndex":85,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"その８０時間を超える方が延べで４２７人、１００時間を超える方が２０１人。先ほどのご説明だと、しようがないではないか、そんなふうに私には聞こえるのです。改めて、この８０時間、１００時間を超える超過勤務を改善させる立場にあるのか伺いたいと思います。合わせて、いわゆる過労死ラインというのは月何時間を超える超過勤務を指すのか、区の認識も伺いたいと思います。","respondent":"黒田人事課長","answer":"区としましては、働き方改革として「しながわ～く」を平成２９年度から取組んでおりますので、当然、超過勤務の縮減だけではございませんが、働き方について上司も部下も認識して変えていって成果を上げていこうという取組みを行っております。","voiceIndex":87,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"さらに答弁が後退しているのですよ。先ほどは、そうは言っても超過勤務は短くしなければならないと思うと言いましたが、今のご説明では、成果を上げていくのだと。要するに、月８０時間、月１００時間、品川区も認めるこの８０時間以上を超える超過勤務を改善させる立場にあるのか、はっきりとご説明いただきたいと思います。","respondent":"黒田人事課長","answer":"８０時間を超える職員を減らしていくというのが区の立場です。","voiceIndex":89,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"８０時間を超える職員を減らしていくのが区の立場であるならば、なぜ１カ月について１００時間まで、２カ月から６カ月平均で８０時間以下を認めるという条例改正を今回するのか伺いたいと思います。","respondent":"黒田人事課長","answer":"今回の月１００時間、８０時間という規制内容につきましては、人事委員会の承認を経ている規則ですので、実際にはこれから定めるものではありますが、あくまでも規定については民間の労働法制があり、国家公務員制度があり、地方公務員制度があるという中で。","voiceIndex":91,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"認めるためにではないとは言いながらも、１カ月について１００時間まで認める内容ですから、それは明らかにおかしいと思います。","respondent":"黒田人事課長","answer":"そういった意味では、職員が一定の品質のものを一定の時間でやるということが必要だというふうに先ほど申し上げたところでして、レイアウトに凝ってはならんということではないですけれども。","voiceIndex":93,"id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"だから本当に、その方の働いている部署や仕事の内容によって相当違うと思うので、どうなのかなと。特に大企業など、これは噂なので私もその現場を押さえたわけではないのですけれども、大企業の一部には、会社を５時または６時に退社しまして、別のオフィスで仕事をやっているという話まで聞いたのです。１つだけ疑問点なのですが、これは品川区の固有教員の方にも当てはまるのですか。","respondent":"黒田人事課長","answer":"教員につきましては、超過勤務手当が支給されるということではありませんが、今回の条例の考え方、教育委員会でも同じように条例が出されており、労働時間の上限規制ですので、手当を支給する・しないということではなくて。","voiceIndex":96,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"先に意見を言わせてください。ただ、一方で、区の職員に対して私たちはやはり区民サービスを求めるわけです。例えば、すごく具体的な事例ですけれども、公立保育園の質などはきちん担保してほしいということを、一方では求めてしまう。窓口での相談などもやはり丁寧にしてほしいとか、さまざまな調査も行ってほしいということを一方で求めるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-036"},{"speaker":"いながわ委員","kind":"確認","question":"済みません、質問が所管外になってしまうとあれなのですけれども、例えば大会組織委員会にプロパーはそれほどいないのですよね。品川区と大会組織委員会をしっかりしたパイプでつないで、品川区にいろいろな意味で、東京２０２０大会を通じて利益をもたらすために派遣をしているのかという感覚で私はいるので、どういった職務権限で行かれているのかというのがわかれば、わからないでしょうか。","respondent":"黒田人事課長","answer":"業務内容としましては、国内広報チームでありますが、報道対応支援チームということで、オリ・パラの全体にかかわるような仕事に携わっている職員もいれば、会場担当ということで、会場の競技を担当するところに配属になっている職員もいるのですが。","voiceIndex":112,"id":"exchange-037"},{"speaker":"いながわ委員","kind":"質問・要望","question":"やはり立ち位置が、区が上なのか、大会組織委員会が上なのかという議論になって、これは明らかに大会組織委員会だと私は思っているので、そんなことを言うのだったら、ではいいですよと向こうも言いかねないか、わからないですけれども、ただ、少なくとも関係が良好な中で、ビーチバレーボールが潮風公園、ホッケーが大井埠頭中央海浜公園で開催されるわけですから、あとは品川区内の動線の確保とか。","respondent":"黒田人事課長","answer":"派遣職員の給与の部分につきましては、基本的には品川区が払っておりまして、大会組織委員会につきましては、共済費の事業主負担を大会組織委員会が持つということで、東京都、２３区全体を含めて統一的な対応をとられております。","voiceIndex":114,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の条例改正ですけれども、併任となることで法人の立場で携わる業務の幅が変わるというところがよくわからないのです。今までの職員研修と、今回の条例に基づく派遣の違いというのは何なのか、区民にとって何がどう変わるのかご説明いただきたいと思います。","respondent":"黒田人事課長","answer":"なかなかわかりにくいところではありますが、研修派遣というのはあくまでも研修の一環として、能力の増進を図るため長期間研修に行っているという位置づけでございまして、今回の条例による派遣につきましては。","voiceIndex":118,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"職員を派遣する趣旨が異なるということですけれども、区民にとっては何か変わるのか伺いたいのです。","respondent":"黒田人事課長","answer":"区民にとって直接的に何かが変わるということはないとは思いますが、例えば、法人の業務に対して人的支援として、職員を派遣すると、今までは研修の立場でしか携われなかったのが、法人の職員として業務ができるという、少し抽象的なことになりますので。","voiceIndex":120,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"人的支援ということですけれども、相手から求められて区が送るのか、区の判断としてこれは送らないといけないということなのか、人的支援の必要性についてどちらが判断するのか、最後に伺いたいと思います。","respondent":"黒田人事課長","answer":"基本的には、研修派遣であれば、職員の研修として必要ということで区から送るわけですし、この条例による派遣につきましても、施策を推進するために人的支援が必要だということで送るわけですから、あくまでも職員の給与は公費ですので。","voiceIndex":122,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"去年の総務委員会で大会組織委員会のほうに派遣するための条例を審議したときに、一度伺っているのですけれども、この法律自体ができたときにあえて品川区は条例化をしないで、研修派遣という位置づけでいろいろな団体に派遣していたと。その中で、この５法人を選んだと、そのほかにもいろいろな研修派遣は続いていると思うのです。そことの違いはどうなのか。その辺を教えてください。","respondent":"黒田人事課長","answer":"今回、この５法人を追加した理由ですが、ご説明申し上げたとおり、対象となる法人が地方公共団体の事務事業と密接な関連を有し、施策推進を図るために人的援助が必要な団体という中では、区内にありますこちらの公益法人や社会福祉法人は。","voiceIndex":125,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問","question":"今でも研修派遣を行ったところでも結構そうなのではないかなと。その中で、特にこの５法人を選んで、あえて今回条例化した。今までは大会組織委員会への法に基づく派遣なら受け入れるよということで、他律的に条例化したのだけれども、こういうふうに今回、品川区として行っていくという、その差というか、判断した理由というか、そういうところを伺いたいと思うのですけれども、ぜひお聞かせください。","respondent":"黒田人事課長","answer":"現在、この５法人以外に職員を研修派遣で行っている団体は、社会福祉法人であったり、１つの事業を行うところというのはありますので、この中で公益的法人を選定したというものです。","voiceIndex":127,"id":"exchange-043"},{"speaker":"須貝委員","kind":"質問","question":"今回、５つの公益社団法人等が選定されたのですが、密接な関連を有し、施策推進を図るために人的援助が必要な団体とあります。逆に、せっかく品川区でいろいろ研修をして育てた有能な職員、人材を、派遣するというのは逆にもったいない話で、この５つの法人が自ら職員を、臨時職員でもいいですけれども、採用するというのは、本来の建前ではないですか。その点についてお聞かせください。","respondent":"黒田人事課長","answer":"今後、条例による派遣におきましても、学ぶというところもありますが、今度はその法人の職員として、その立場での仕事ができるということになりますので、法人の固有業務を進めるというところでは、法人が自ら職員を採用するというのは、それはご指摘のとおりかと思います。","voiceIndex":129,"id":"exchange-044"},{"speaker":"須貝委員","kind":"質問","question":"かえって区のほうでは、さまざまな業務をいろいろ関連して、ほかの部署ともいろいろ連携して事業をやっているので、逆にこの法人が区のほうに職員を派遣して、区の事業を学ぶというほうが本来の筋道ではないのかと思ったことと、この職員の派遣等に関してですが、派遣された職員、先ほども少し出たのですが、この方たちもここに３年間とか派遣されれば、職員定数から外れるということですか。","respondent":"黒田人事課長","answer":"この条例による派遣になりますと、定数条例の規定に、派遣の場合については定数から除くとしていますので、派遣している職員は、定数条例の員数から外れるというものです。","voiceIndex":131,"id":"exchange-045"},{"speaker":"須貝委員","kind":"質問・要望","question":"ますます定数がどんどん広がっていくのかという感じがしているのですけれども、こういうふうに改正するということで、いい効果が出ればいいと思うのですが、くれぐれも慎重にやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-046"},{"speaker":"吉田委員","kind":"意見","question":"今まで、やはり法律ができた段階でほかの自治体は結構条例化して、それに則って派遣をしております。今まできちんと研修派遣という形で派遣し、そこの団体で働いていたので、法人を限定したということについてはまだ少し疑問が残るのですけれども、条例という形で整理されていくということは評価したいと思いますので、賛成をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"利用する者がなくなったということによる廃止なので仕方がないかと思いますが、職員の福利厚生にかかわることなので、職員団体との協議や合意についてはどのような状況なのか、その点について伺いたいと思います。","respondent":"黒田人事課長","answer":"条例による制度ですので、職員団体との合意は特にしておりませんが、団体には廃止することについて説明しておりまして、同意ではございませんが了解したと認識しているというものです。","voiceIndex":149,"id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2130#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":38884,"voices":165}},{"id":"r01-20190226-6","meetingId":"r01-cm02","date":"2019年2月26日","dateIso":"2019-02-26","committee":"区民委員会","time":"午前１０時００分～午前１１時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"浅野副委員長","kind":"提案","question":"区民委員会の皆様、そして、理事者の皆様、関係各位の力をいただき、今期の区民委員会を進めることができました。本当にありがとうございました。そして、あの地震を参考に、委員各自がそれぞれ委員会などで震災対策に関する質問をすることができました。委員会審査などにつきましては、委員の皆様から活発な意見と提案などが質問され、実りある委員会とすることができました。どうもありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2834#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":2053,"voices":11}},{"id":"r01-20190226-7","meetingId":"r01-cm02","date":"2019年2月26日","dateIso":"2019-02-26","committee":"厚生委員会","time":"午前１０時００分～午後 ２時５９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第３期品川区地域福祉計画のパブリックコメント実施結果","agenda":"第３期品川区地域福祉計画のパブリックコメント実施結果","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちも読ませていただいて、特に障害者の意見が多く、親御さん、障害当事者の皆さんが、品川に対して障害者福祉の充実を、いろいろな場面から求めているというのも改めて認識しました。今度の３月末の策定委員会のときの修正を踏まえて、５月に意見が反映されたものが出るということでいいのか、確認をお願いします。","respondent":"大串福祉計画課長","answer":"２月１８日時点ということでお示しさせていただいた、資料３でパブリックコメント、資料４で地区懇談会でのご意見といったところを、今日はご説明させていただきましたけれども、３月末に行われる策定委員会ではこれを反映した形で。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ公開していただきたいという要望をしたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今の委員会をつくっていくというお話ですけれども、今回の計画は第３期地域福祉計画ということになると思いますけれど、今まではこの地域福祉計画を回していく委員会というのは、なかったのでしょうか。","respondent":"大串福祉計画課長","answer":"先ほど回答させていただいたように、今後座長となられる方について、こちらで検討させていただき、なおかつその座長になられる予定の方とは、委員会の持ち方についていろいろご相談させていただきたいと考えているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ずっと常設ということではない形なのか。そういうことで言えば、ずっと常設であってもいいのかなという思いがするのですけれど、期ごとに一度なくなって、新たにまたつくるといった形にするのはなぜなのか、というあたりもお聞かせいただきたい。先ほどのＰＤＣＡサイクルにしても、この推進委員会にしても、ぜひ公開ということで進めるべきではないかと思うのですけれど、その点についてもお聞かせください。","respondent":"大串福祉計画課長","answer":"このＰＤＣＡを回すというのは、地域福祉計画の中でもうたわれているところですので、対応はいろいろあろうかと思いますけれども、この計画に関連する方々に来ていただき、ご議論いただくというのは必要な場だと考えております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"パブリックコメントの最後のところにも、区民向けの説明会を実施してくださいと、これは私も再三要望してきているところです。やはり今回の計画ができたところでも、私は説明会をぜひやっていただきたいと思うのです。公開という点では、区の姿勢として、委員会の公開にしても、ＰＤＣＡサイクルの公開にしても、ぜひやっていただきたいということで、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"地区懇談会の実施について、参考までにお伺いしたいと思います。これはまだ続いているものなのか、これからやるものもあるのか、これまでやってきた会の進め方、概要を説明して、総時間はどのぐらいとったのかという、様子を少しお聞きしたい。聞き漏らしていたらすみません。この懇談会に参加されたのはどういう方たちなのか。その懇談会の様子を教えてください。","respondent":"大串福祉計画課長","answer":"それから後期は、今のところ１２地区まで終わっています。残りは３月に支え愛活動会議が予定されておりますので、そちらにまたお邪魔させていただいて、ご説明および意見交換といったところをしたいと考えているところです。","voiceIndex":13,"id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"概要を説明されて、区としてはこういう福祉計画で行きますよという、区の姿勢と考え方のご説明をされて、そこでご理解をいただきながら、またご意見をいただきながら修正をしていく、その作業の一つの声をいただくという場として年に２回実施したという理解でよいでしょうか。これは非常に大事な場面だと考えていますので、どうされてきたのか。","respondent":"大串福祉計画課長","answer":"今回の第３期地域福祉計画策定に当たっては、第２期と同じような形で、やはり地域の皆様方に区の考え方をご説明し、また皆様方のご意見をいただいた中で、行政のほうの計画ということではなく、やはりいろいろな方と一緒に地域をつくっていく計画という趣旨を踏まえて。","voiceIndex":15,"id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、課長が最後におっしゃってくださった、ご要望があれば行きますというところと、こちら側から説明させてくださいという形もあるだろうと思います。特に町会長はじめ、皆さんがどうやって地域の方たちを見守ろうか、支え合おうか、常に考えていらっしゃるのですが、なかなか具体的にどうする、こうするというのがない。最後に、その点はいかがですか。","respondent":"大串福祉計画課長","answer":"中にはそういった、ありがたいご意見をいただく方もいらっしゃいました。もう少しこういうことを説明してくれると、町会のほうにも話ができるのだけれど、というお話をいただいたところですので、そういった場合については機会を捉えてお伺いさせていただければと考えています。","voiceIndex":17,"id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。計画ですので、これが実行されることが大事で、地域の皆さんに、こういう福祉計画が大事だよねと実感していただくためには、地域の方と力を合わせてやるしかないと思うので、そのあたり、皆さんにとっていい計画となるように関係をつくっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-009"}]},{"id":"topic-02","title":"東品川シルバーセンターの大規模改修に伴うゆうゆうプラザへの転換","agenda":"東品川シルバーセンターの大規模改修に伴うゆうゆうプラザへの転換","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"東品川シルバーセンターの大規模改修というのは前から報告されていましたけれども、指定管理者制度を採用するということで、平成３１年度に指定管理者を選定ということですけれども、大まかに平成３１年度のいつごろ選定予定かというのは、まだわからないですか。わかれば教えていただきたいのと。そこを伺いたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"お尋ねを２点いただいたかと思います。指定管理者の公募手続のスケジュールですが、まだ細かく、いつからいつまでというようなスケジュールまでは、まだ至っておりません。ただ、おおむね平成３１年度の下半期ぐらいにはなるかなと考えています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほどご説明あったように、本当に浴室の利用者が多い施設なので、この約１カ月休館になるというのは周知されているのか。そして代替の場所が必要になってくると思うのですけれど、そのあたりの調整は、利用者の方に話ができているのか、伺いたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"約１カ月ほど、入浴サービスがご利用いただけなくなるという点も含めまして、実施設計終了後に予定しております、施設利用者向けの説明会にて、ご案内させていただきたいと考えています。","voiceIndex":26,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"前にも言ったのですけれどここだけ直すのは非常にもったいないなと、いまだに思います。この部分だけでなく、全体の計画を進めていってほしいと思うところはあるのですけれど。状況は前回ご説明を聞いているので、理解します。それから裏面で、男性用浴室工事期間で気になったのは、トイレがなくなっているのですが、どこかにつくるのですか。そこはどうなるのか、気になったので教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"この点につきましては、過去に大崎、平塚橋、平塚、このようなところで先行した事例もありますので、そのときの教訓等もしっかりと参考にさせていただきたいと考えております。トイレにつきましては、すみません、私の説明が漏れておりました。","voiceIndex":28,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ほかの施設というのも、窓口は区の職員の方ではなくて、シルバー人材センターの方がやっていると思うのですね。その方たちがその説明をうまくできるのかというのも気になるのと、事務方の説明でなく、利用者側に対して、その辺を理解してもらう形をとらなければいけないので、そのあたりをもう一回、どういうふうにしていくのか教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"シルバー人材センターのスタッフとは、定例的に庁舎で打ち合わせをしています。そういった機会もしっかりと活用させていただいて、Ｑ＆Ａですとか、過去にこういう事例があったというようなものを、しっかりと共有を図ってまいりたいと考えています。","voiceIndex":30,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"意見","question":"事務方と同時に、今現在、隣のシルバーセンターを使っている方たちに、説明会のようなものをやるのか。東品川で工事があることは承知しているのかどうかわかりませんが、やはりいろいろな問題が絡んでくる可能性があるので、そちらに対しても何かうまく説明してほしいというお願いなのですが。","respondent":"宮尾高齢者地域支援課長","answer":"代替の候補となるシルバーセンターの利用者の方向けにも、しっかりとスタッフから伝える、あるいは館内表示をするとか、いろいろ丁寧な方策を考えていきたいと考えています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"指定管理者制度の採用というところですけれど、ゆうゆうプラザというのは、たしか以前お聞きしたとき、指定管理者のところと指定管理者でないところがありますよね。そこで、どういう考え方で指定管理者とするのか、委託にするのかということをお聞きしたとき、複合施設は指定管理者ということで考えているというふうなご答弁だったと思うのです。","respondent":"宮尾高齢者地域支援課長","answer":"東品川シルバーセンターにつきましても、その広い敷地をしっかりと有効活用するという意味でも、指定管理者制度が有効であるというふうに判断いたしまして、今回も導入させていただこうというふうに考えてあります。","voiceIndex":34,"id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"大きくは指定管理者でいくという方針があるのか、そこのところが、前回はたしか複合施設なのでというご答弁だったのでお聞きしているところですが、その考え方を改めて伺います。","respondent":"宮尾高齢者地域支援課長","answer":"建物の立地条件と規模、実際の事業内容、そういったことを総合的に考えて、適切にその都度判断をしてまいりたいと考えていますが、いずれにせよ指定管理者が大きな選択肢の一つであるということは、言えるかなと考えています。","voiceIndex":36,"id":"exchange-016"}]},{"id":"topic-03","title":"障害者福祉事業の整備状況","agenda":"障害者福祉事業の整備状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"一つずつ聞いていきたいのですけれど、周知の部分で、手当に関するご案内でリーフレットを作成されたということは、支給対象であるのを知らなくて受けとれていない方がいるとか、そういう状況からこの案内をつくられたのか、またそういう受けとれていない方がいたのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"手当を知らないから受けとれないという方は、こちらには情報は入っておりませんけれども、引き続き周知を徹底していきたいと考えています。","voiceIndex":42,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"手当を受けとられていない方がいるか、報告は受けていないということですけれども、ちょっとお聞きしたいのですけれど、基本的に手当の対象ですよというのは、手帳の交付と同時に知らされるものなのでしょうか。","respondent":"松山障害者福祉課長","answer":"手帳の交付の時点で、窓口でこういう手当が対象になりますというようなご案内は、きちんと丁寧に行っておりますので、さらにわかりやすくなるように、こちらをつくったものです。","voiceIndex":44,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。障害児相談支援と医療的ケアへの対応、訪問リハビリの実施というところで、専門職の方がどれぐらいいて、職員体制は総勢で何人ぐらいでやるのか、この間の説明の中で聞いてはきたのですけれども、こういう感じで行きますという大まかにしか聞けていなかったので、もし決定されているのであれば、正確な数字を伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"障害児の相談についてのご質問です。こちら２カ所で行うかですけれども、まず障害児の相談というのは今現在、区の障害者福祉課だけで行っておりますので、外部、ほかにも常設ができたらと考えております。","voiceIndex":46,"id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、障害児相談支援では、相談支援専門員を配置し、とありますけれども、これは具体的にスタッフ何人とか、そして医療ケアの対応についても医師を週１回配置していくと、そして看護師も、もとから２名ぐらい配置されていたと思うのですけれども、その医療的ケアの対応をする職員配置はどれぐらいなのか、そして訪問リハビリの実施をする、これは例えば何人体制なのか、わかれば伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"当然障害児の相談を行う専門支援員というのは、少なくとも１名以上と考えております。それから看護師につきましては現在２名いらっしゃいますけれども、これは既に医療的ケアをやる方向で想定して２名確保しているというふうに、心身障害者福祉会館のほうからは聞いております。","voiceIndex":48,"id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その中でも伺っていきたいのですけれども、Ａ４の品川区障害者介護給付費等支給決定基準に関する要綱で、第４条、審査会との連動のところですけれども、そもそもこの審査会の名前が、旧のほうは障害支援区分認定審査会となっていまして、新のほうは障害者介護給付費等支給審査会というふうに、変わっているのですけれど、これは全く別の審査会なのか、名前が変わっただけなのか、やる内容が違うのか。","respondent":"松山障害者福祉課長","answer":"支給決定基準の見直しというのは、考え方は以前から、勘案をきちんと踏まえてということ、個人の状況、ご家族の状況、置かれている環境をきちんと踏まえた上で、サービス等利用計画案を相談員が作成するという方法はこれまでと変わりません。","voiceIndex":50,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、審査会としては新のほうが正しいといいますか、今までのものは間違っていたというか、何だったのか。審査会のメンバーも変わらないということなのでしょうか。","respondent":"松山障害者福祉課長","answer":"審査会のメンバーも行っている内容も、これまでと変わることはございません。ただ文言を修正したです。","voiceIndex":52,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、メンバーはどういう方で構成されている審査会なのか、今年度何回ぐらい開催されているのかというのがわかれば、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"２つの合議体がありまして、委員構成は５人ということで、医師、学識経験者といった方々です。審査会の回数ですけれども、平成２９年度につきましては３６回開催されております。","voiceIndex":54,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"意見","question":"わかりました。第５条の部分に移りますけれど、品川区障害者ケア計画検討会というものがあります。このメンバーというのはどういう方たちで構成されているのか、これも今年度何回ぐらい開催されているものなのか。","respondent":"松山障害者福祉課長","answer":"どちらかといいますと、これまでのケースワークも含めて検討しているような会議となっております。回数といたしましては、支給決定の件数とイコールぐらいの回数となっております。変更がある場合、あるいは検討が必要な場合に随時行っているものです。","voiceIndex":56,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"品川区障害者ケア計画検討会というのは、どういうときにかかるもので、どういう検討会なのか、そもそもを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"基幹相談支援センターの役割もありますので、その勘案事項も含めてケースワーカーが全て決定する場合にはその勘案事項もきちんと見直しながら、実際問題支給量が足りているのか、あるいはこのサービスだけでよろしいのか、というところを検討する会議となっております。","voiceIndex":58,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"今までの流れだと、ケア計画検討会で検討して、そして審査会にかけるかどうか判断しているという流れなのでしょうか。この要綱からはそれが読み取れないので、どのような流れになっていくのかということと、あと支給決定基準を大きく超える決定が必要な場合は、どういった流れになるのかがわかるように、記載することが必要なのではないかと思いますけれど、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"こちらのケア計画検討会で検討するということなので、特にここで決定しているわけではございません。","voiceIndex":60,"id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問","question":"新のほうも、支給量とはなっているのですけれども、これを超える場合も支給できるよというのが、旧のほうでは特記事項や審査会に諮る基準などでわかるのですけれども、この量を超えても利用できる場合があるというのが、新のほうでもわかるようにしたほうがいいのではないかと思うのですけれど、そこの考え方をお伺いします。","respondent":"松山障害者福祉課長","answer":"ですから、この特記事項につきましては、ちょっとそぐわないところがありますので、今回削除したものです。審査会に係る基準というのも、審査会に諮ることができるというような文言に変えましたので、こちらの形に縛られないように、記載については削除いたしました。","voiceIndex":62,"id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"確認","question":"それで、この支給決定基準表をそもそも事業所の相談支援員が知らないということが大問題だと、私たちは指摘させていただいてきました。先ほどの課長の説明の中で、相談員にも周知していくということでしたけれども、どのような周知の形をとられるのか、それがしっかり本当に行き渡るのか、確認したいのですが。","respondent":"松山障害者福祉課長","answer":"支援センター連絡会等においても、私のほうから支給決定基準がきちんとあることは周知しておりますし、考え方としてはこれから検討していくということも、その時点でコメントしています。","voiceIndex":64,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この支給決定基準が行き渡っていないために、制限をされていたという実態があったというところを、しっかり教訓にしていただいて、周知していっていただき、障害者福祉サービスを充実させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"１つは、施設も就労継続支援Ｂ型とグループホームが新たにできることになって、よかったなと思っているのですけれど、ここは区として誘導するというかどういうことで、特に就労継続支援Ｂ型とグループホームが足りないというのは、当事者の皆さんからも挙げられていたことで、増設になってよかったと思っているのですけれど、区が働きかけをされて、こういう状況になったのか。","respondent":"松山障害者福祉課長","answer":"ただ、ご相談の中で区の現状をお話ししまして、どういったものがということでは、日々相談を受けているところです。施設の種別に限らず、相談はいただいているところです。ただ、受け身ではなくて、今後区としても積極的に発信をしていきたいと考えております。","voiceIndex":67,"id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"こういうふうに就労継続支援Ｂ型とグループホームを設置したいという相談があって、実現したということですけれど、この場合、補助金というのはどういう仕組みになっていて、どういう形で出るのかといったことについてもお聞かせいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"やはり安定した継続というのが大事だと考えていますので、いろいろなタイプのものが結構出てきておりますので、この就労継続支援Ｂ型にしてもグループホームにしても、まだ建って間もないですから、区としても現状を把握しながら、よりよいサービスを区民の方に提供できるように。","voiceIndex":69,"id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"わかりました。ぜひ今後ともよろしくお願いいたします。それでお聞きしたいのが、第４条の審査会のところですけれど、この審査会は平成２９年度で３６回やったということですが、これはサービスの基準、支給に対しての審査会ということで３６回あったということなのでしょうか。その認定審査会に意見を求めるということになっていくのか、そこのところをお聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"なので、わざわざ独立してつくるというよりは、調査に基づく審査会という、審査、判定を行うという、本当に専門家のいらっしゃるところなので、そのよくわかっていらっしゃる方々にご意見をいただくということで、考えております。","voiceIndex":71,"id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうしますと、この第４条にあるような、必要があると認めたときに、この審査会に意見を求めることができるということの事例というのは、年間どれぐらいあるものなのか教えていただきたいです。第５条で、品川区障害者ケア計画検討会というのは、全ての計画が係るという形になるのか、そしてそのケア計画検討会のところで判断をして、審査会にかかるということになるのか。その仕組みも教えてください。","respondent":"松山障害者福祉課長","answer":"障害者ケア計画検討会ですけれども、課内の検討会ということで、全件がこちらにかかるというものではないです。変更があったとか、急激に何か変化があった場合が主です。どちらかというとケースワーク的な要素を持っている会議体です。","voiceIndex":73,"id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ありがとうございました。仕組みが随分わかってきました。そして、ケアプランの中でここにかかる件というのは、およそ何パーセントぐらいあるのかわかったら、教えていただきたいと思います。もう一つ。障害児の場合はこの審査会の規定がないですよね。それはなぜなのかということも、あわせてお聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"「障害者福祉のしおり」の表記の件、例えば障害支援区分、認定の流れや支給決定のプロセスのところで、こちらのケア計画検討会が入っていないというお声もいただいておりますので、また成人の場合と障害児の場合と、もう少しきめ細やかに。","voiceIndex":75,"id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"わかりました。そしてそのためには、現場にこれを、本当に大もとの相談支援のあり方、ケアプランを組むときの考え方、勘案事項をもとにして、これが上限ではないという、その人に合わせたサービスを組んでいいのだというあたりも、ぜひ徹底していただきたいと思いますけれど、その点について最後にお聞かせいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"この基準、今回は要綱の改正ということでしたけれども、これまでも平成３０年度当初から、私のほうからこちらが標準という考え方を連絡会のほうでも説明させていただいて、改正するのが遅くなってしまいましたけれども、それに合わせた形での改正になったかなと考えています。","voiceIndex":77,"id":"exchange-035"}]},{"id":"topic-04","title":"不妊治療費助成制度の変更","agenda":"不妊治療費助成制度の変更","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"確認ですが、一般の部分に関しては、区民の方からすると、品川区がやってきたものを東京都が一部スライドするというだけだと思うのですが、特定に関しては、所得の上限が上がるということで、これはもともと首都圏では共働きが多く、７００万円ぐらいでは結構対象にならないという話で、こうなったと思うのですが、所得制限を上げることで、何％ぐらいの方が対象として増えるのか。","respondent":"川島健康課長","answer":"所得制限の変更でどのぐらいのパーセンテージ、この申請が増えるかということは、私どものほうではまだ推定しておりません。この特定不妊治療助成というのは、国の制度を都が実施しているものでして、今回の変更でどうなるかというのも、私どももまだ読めないところです。","voiceIndex":84,"id":"exchange-036"},{"speaker":"こんの委員","kind":"確認","question":"確認ですけれども、そうすると一般不妊治療のほうは、３５歳から３９歳までの早く治療を始めたいという人は、どうなってしまうのですか。","respondent":"川島健康課長","answer":"ですので、３５歳より下の方は、当然助成対象になっております。４０歳未満の方まで、東京都が全部助成対象にするです。","voiceIndex":86,"id":"exchange-037"}]},{"id":"topic-05","title":"年金生活者支援給付金","agenda":"年金生活者支援給付金","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"１点だけ。他課との連携というところで確認しますが、多分この対象者となる方は、生活保護を受けていらっしゃる方が多いと想像するのですが、そことの連携、いわゆる受給者への丁寧な説明が必要かと思うのですが、その点、連携はどうされますか。","respondent":"三ツ橋国保医療年金課長","answer":"委員ご指摘のとおり、生活保護対象の方も多いと思われます。実際に担当者同士の説明であったり、国民年金係から生活保護の担当への説明などは、随時行っておりまして、実際に支給される方が漏れないのないようにしてまいります。","voiceIndex":92,"id":"exchange-038"},{"speaker":"こんの委員","kind":"意見","question":"本人が請求するという作業が、どうしても漏れてしまうことがあると思うのです。その来た通知がわかりにくかったり、なかなか理解ができなかったりして漏れてしまうことがないように、ぜひ他課との連携でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"対象者は総勢９７０万人で、それぞれの支給要件ごとに６１０万人、１６０万人、２００万人とあるのですけれども、これを品川区で考えるとどれぐらいの方が対象になるか、わかるのでしょうか。","respondent":"三ツ橋国保医療年金課長","answer":"所得については次年度以降のものになりますので、明確には出ないのですけれども、例えば平成２９年度の老齢基礎年金の市区町村で受付の部分は７６件、障害基礎年金は７９件、遺族基礎年金は３１件というような件数ですので、その部分に関してはこちらと同様と思われます。","voiceIndex":97,"id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"それで第１段階が３,３６０人、第２段階が１１万１,６０７人というのが、平成２９年度の状況ですけれど、パーセンテージで４.１％と１４.１％、合わせて１８％ぐらいなのですけれど。およそ１８％ぐらいの方が、所得というところからは対象になるというふうに考えていいのか、そこのところだけお聞かせください。","respondent":"三ツ橋国保医療年金課長","answer":"鈴木副委員長のご推察のとおりに、恐らくこの人数の方が対象となると思います。その中で、きちんと年金について対応されている方となると思われます。","voiceIndex":99,"id":"exchange-041"}]},{"id":"topic-06","title":"後期高齢者医療保険料軽減特例の見直し","agenda":"後期高齢者医療保険料軽減特例の見直し","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"年金は増えずに、この軽減特例がなくなっていくというのは、本当に高齢者の実態を無視したものだと思いますし、さらに医療の窓口負担を今、１割のところを２割にするという、そういった計画がされているというところで見ても、本当に長生きが喜べないという状況がつくられてしまっていると、私は感じています。この軽減特例の見直しで影響がある方の人数を教えていただきたいです。","respondent":"三ツ橋国保医療年金課長","answer":"東京都広域連合からの試算ですが、平成２９年度の９割軽減の方につきましては、８,３８１人です。８.５割軽減の方につきましては、７,１１６人です。","voiceIndex":105,"id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"今伺った方々が、２９年度でこの人数の方々ということで、そうすると、平成３１年は９割軽減だった方が８割になって、８.５割の方が８.５割で維持されると。要は９割軽減の方は、平成３１年度に８割軽減になったとき、この図を見ますと、介護保険料の軽減もあるとか、年金給付もあるとか、図はあるのですけれど、要はどうなっていくのか、わかりやすくご説明いただけたらと思います。","respondent":"三ツ橋国保医療年金課長","answer":"その差というのは、８,６６０円を１２カ月で割ったものが、この７２２円となっております。したがいまして平成３１年度、４,３３０円プラス７２２円掛ける半年分、１０月から始まりますので、その半年分が足されます、という部分になります。","voiceIndex":107,"id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問","question":"その算定方法はわかったとして、グラフの下の介護保険料の軽減というのがありますし、年金の先ほどの支援給付金もありますよ、だからちょっと支えられますよというのを、ここであらわしているということでいいのでしょうか。","respondent":"三ツ橋国保医療年金課長","answer":"委員おっしゃるとおり、介護保険料の軽減もありますし、また先ほどご説明しました年金生活者支援給付金もありますので、トータルした図となっております。","voiceIndex":109,"id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"７２２円というのはよくわかりました。ただ、そこで緑の矢印のところに、「３１年１０月から７割軽減（本則）に戻す」と書いてあるのですけれど、でも３１年では８割軽減ということですよね。それがなぜ７割軽減なのか。もう一つは、介護保険料の軽減強化ということとあわせてあるのですけれど、介護保険料の軽減強化というのは、中身はどういうものなのでしょうか。","respondent":"三ツ橋国保医療年金課長、寺嶋高齢者福祉課長","answer":"なぜ９割軽減が７割軽減にもかかわらず、８割と書いてあるのかですけれども、こちらは２番の条例上の見直しの内容にも書いてありますとおり。８.５割も同様となっております。ただし、国の政令公布が３月末なので、本日のタイミングではまだ正式に決まってないのでご案内できていませんけれども、７月の保険料を確定する段階で。","voiceIndex":111,"id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうしますと、この介護保険料の軽減というのも、消費税１０％が実施に移されるということになって、初めてこれが実施されるということになっていくのか、お聞かせいただきたいと思います。ということで、保険料としては１割から３割に、一気に３倍になるという、私は経過措置があるのかなと思ったのですけれど、本則の７割に、一気に３倍になると。そういう値上げだという確認を、お願いしたいと思います。","respondent":"寺嶋高齢者福祉課長、三ツ橋国保医療年金課長","answer":"消費税１０％と連動の件ですが、先ほどの国保医療年金課長の答弁と重複する部分がありますけれども、こちらで得ている情報としましては、消費税が１０％に上がったらということで聞いておりまして。今まで１割の方が、突然半年後に３割ではなくて、賦課料ですので８割、つまり２割通年していくです。","voiceIndex":115,"id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうしますと、４月の段階で既に８割ということで実施されてしまうという、１０月にもしかして消費税が……、これは消費税とは関係なく、ここだと連動しているみたいに書いてあるのですけれど、消費税１０％に関係なく、この軽減特例はなくして、保険料の値上げは実施されるということなのでしょうか。","respondent":"三ツ橋国保医療年金課長","answer":"一番最初に申し上げましたとおり、均等割の軽減につきましては、低所得者に対する介護保険料の拡充や、年金生活者支援給付金の支給と合わせて実施するというものですので、年金生活者支援給付金が例えば先延ばしになった場合は、同様と思われます。","voiceIndex":118,"id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"それが、ある程度の時がたったことで、３倍にも上げてしまうというのは、本当に政治のひどさ、自公政権のひどさというものがここにあらわれているということを、改めて指摘しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":120,"id":"exchange-048"}]},{"id":"topic-07","title":"視察の前に予定表３、その他","agenda":"視察の前に予定表３、その他","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"委員の皆さん、理事者の皆さん、本当に１年間ありがとうございました。そして委員長、１年間お疲れさまでした。改めてこの厚生委員会というのは、区民の皆さんの切実な問題について議論する場だなと、今の国保の問題、後期高齢者の問題、障害者の問題、介護の問題、また健康の問題、本当に区民の切実な問題を皆さんと議論ができて、本当によかったと思います。１年間ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3532#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":50645,"voices":132}},{"id":"r01-20190226-8","meetingId":"r01-cm02","date":"2019年2月26日","dateIso":"2019-02-26","committee":"建設委員会","time":"午前１０時００分～午後 ２時２４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の「立会川・勝島地区まちづくりビジョン」の策定","agenda":"の「立会川・勝島地区まちづくりビジョン」の策定","exchanges":[{"speaker":"横山委員","kind":"質問","question":"何点かお伺いをしてまいります。３点目なのですけれども、同じ資料の土地利用の現況等の勝島エリアのところなのですが、こちらの勝島の町会への加入率といいますか、どのぐらいの方が今参加されているような状況なのかというところもあわせて教えてください。","respondent":"鈴木都市計画課長","answer":"アンケート実施における戸建てとマンションの割合ですが、申しわけございません、今手持ちにはございませんで、申しわけございません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"横山委員","kind":"意見","question":"同じページのまちづくりの目標2)の拠点の形成というところなのですけれども、災害時の拠点となるよう事業者との連携や広域避難場所までのネットワークの形成を図りますというふうに記載されているのですけれども、例えば町会・自治会、もともと住んでいらっしゃる高齢の方々ですとかというところと新しい住民の方、例えばマンションですとか共同住宅にお住まいの方と一緒に防災訓練をされたりですとか。","respondent":"鈴木都市計画課長","answer":"立会川地区の歴史の趣を活かしながら、一方では、細街路という細い道路もありますので、そうした拡幅も進めていかなければいけないというところで、基本的にはやはり防災性の向上あるいは居住環境の向上には、４ｍの道路を建て替えに合わせてきちんと拡幅していただくと。","voiceIndex":7,"id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"歴史的な味わいですとか、品川区のよさ、水辺のよさ、歴史的なよさというものも感じられるような位置ですので、こうしてたくさんの方が品川区の魅力を感じてお住まいいただいていると、すごくうれしい土地だなと思っているところなのですけれども、やはり防災の観点から見ると、勝島というのは島になっておりまして、これから新しい道路のことですとか、あとは３６０度考えますと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"会派で話し合いをしまして、このビジョンについて地元の議員から、新妻議員が担当しているものですから、さまざまな質問がありました。その中で２点だけお伺いをしたいと思います。それと、そういう商業施設に出るのに京急のバスとか都営バスとか、そういうところにぜひそういう声を上げていただきたいのですがというお声があったのですが、この点についていかがでしょうか。","respondent":"鈴木都市計画課長","answer":"それで、今後のそうした地域内の交通ネットワークの充実につきましては、どうしてもこれはルートを走っているバス事業者とのお話もありますし、他地区とのバランス等もありますので、来年度のコミュニティバスの実施に向けた検討の中で。","voiceIndex":10,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと、この意見交換を３０回もやっていただいて、結構なことだと思うのですけれども、どうしてもお声がなかなか届きにくい世代の方たちだなと、その辺はちょっと地元の議員がいろいろ懇談会等をしていく中で、そういうお声があったということで、ぜひ要望として伝えていただきたいなと思います。","respondent":"鈴木都市計画課長","answer":"そうしますと、どうしても運河沿いに管理用の側道があるので、都市計画道路から直接道路という結びつきがとれないということで、以前はそういう部分を考慮させていただいたというところもありますが、一方では、その都市計画道路という位置づけではなくて。","voiceIndex":12,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"地元の皆さんと３０回重ねた協議の中で、おそらくそのあたりも今のお話を伺っていて、いろいろなご要望とか、さまざまなニーズを捉えながらということも今推察ができました。ぜひスムーズに進むようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"アクセスについて、鉄道駅のことについてなのですけれども、立会川駅と大井競馬場前駅というのが主要な駅だと考えられておりますけれども、やはり南大井一丁目と東大井二丁目の人は立会川駅を使い、勝島一丁目の人は大井競馬場前駅を使うのか、それともそれぞれ人によっては双方使うのか、何かそういった駅によってその地域の住む方の住所の特徴というのがあるのでしょうか。","respondent":"鈴木都市計画課長","answer":"資料の別紙１ページのほうに、鉄道駅の乗降客数ということで、立会川駅につきましては、利用者数は横ばいなのですが、定期の利用というのが増えているということも考えますと、一定程度勝島地区のマンションの方々も、この立会川駅をご利用いただいているのかなです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"その際、水辺のにぎわいの促進や舟運を活用した連携というのがあるのですけれども、舟運の活用、水辺のにぎわいは今後どうされるのかということと、あとまた橋をかけますと、今後このあたりの舟運事業をどのぐらいの大きさの船が通るのかによりますけれども、余り高さが低いと今度船が通れなくなるとか、そういったことがありますので、そのあたり、橋をかけるとしたら。","respondent":"鈴木都市計画課長","answer":"この地域は運河ルネサンスということで、東京都が天王洲から広がる水辺のエリアで広く取り組みを進めているところでございまして、こちらについても運河ルネサンスでは例えばカヌーやボートの教室の実施だとか。","voiceIndex":19,"id":"exchange-008"},{"speaker":"筒井委員","kind":"質問・要望","question":"そのあたり、よろしくお願いします。それとあと、このビジョンにぎりぎり一番北のほうで、鮫洲駅のほうも入っているのですけれども、旧東海道の歴史や観光資源を活かした軸の形成ということで、やはり鮫洲駅あたりの地域の方のご協力というか、地域のにぎわい創出というのも重要になるかと思うのですけれども、この鮫洲駅周辺の位置づけというのは、このビジョンでどのように捉えられているのでしょうか。","respondent":"鈴木都市計画課長","answer":"拠点としての位置づけはやはり中心的な位置にあります立会川駅を拠点としてビジョン的には位置づけしていますが、回遊性の創出の中で、勝島地区の人たちが立会川駅あるいは鮫洲駅。","voiceIndex":21,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"すごく単純な文言について伺いますけれども、駅の乗降客数ということで、定期利用者というのは何となくイメージがつくのですが、普通利用者との違いを教えていただきたいなと思います。そういうのもちょっと行ったほうがいいのではないかと私は思うのですけれども、いかがでしょうかというのが２点目です。","respondent":"鈴木都市計画課長","answer":"あわせて、全地域の方々にアンケートを実施して計画の反映につなげているですので、基本的には地域の声を活かした計画づくりを進めさせていただいているというようなことです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。用語のほうはわかりました。それと、新しくマンションが建ったようなところの大規模敷地の緑化の促進という方針もあるのですけれども、具体的にどういうふうに進めていくのか伺いたいと思います。公共施設等の要望というのが地元からどのように上がっているのか、そういった検討なども、配置の検討というのも５ページの右上にありますので、この辺もどういった要望か伺います。","respondent":"鈴木都市計画課長","answer":"公共施設というところでの記載は、アンケートの中でも、やはり公共公益施設という記載をしていますが、例えば病院等が近くに少ないというところのお声はいただいておりまして、そうしたことから公共公益施設という表現をしていますが、これはなかなか。","voiceIndex":26,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。やはり今ある魅力ですとか、等身大のよさというのも活かすことも必要ではないかと思うのですけれども、そういった視点というのは、このにぎわい拠点の方針には入っているのか伺いたいというのが１点です。","respondent":"鈴木都市計画課長","answer":"基本的にはビジョンの中には地域ルールの検討というところですとか、地域の方々とともにというところを書かせていただいておりますが、当然どういう形のまちづくりと商店街活性化に向けた取り組みが適正かというところは、これは区主導というよりも、まちづくりについて。","voiceIndex":28,"id":"exchange-012"},{"speaker":"安藤委員","kind":"提案","question":"人道橋のことはわかりました。ですから、住民の方が、地域の方が今までのよさを活かしたいというご意見がもし強いということであれば、そういったことも実現できるような手法をやはり行政としていろいろ研究して、そして提案していただきたいなというふうに思います。こちらなのですけれども、道路後退に向けた検討とはどのような方向性が考えられているのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"細街路の後退拡幅の検討というのは、新たにどこかの道路を指定して、道路を広げていくということではございませんで、今ある細街路の道路を建て替えに合わせて後退していただくと、そういう意味では、今建て替えなくても、場合によっては建物の敷地に余裕があれば。","voiceIndex":30,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一回、マンションの居住者の意見はどのように聴取できていたのか、ちょっとなかなかできていないということであれば、それはそれでそのようにお答えいただきたいと思いますし、それとあと、今後どうやってそういった方々の意見も取り入れていくかということもあわせて最後にお伺いして終わりにします。","respondent":"鈴木都市計画課長","answer":"今後、このエリアについて、具体的な整備計画を立てて、まちづくりを進めていくことになりますが、その過程の中でも地域の方にご説明して、お声をいただきながら、しっかりと進めていきたいというふうに考えてあります。","voiceIndex":32,"id":"exchange-014"}]},{"id":"topic-02","title":"の品川区空き家等対策計画","agenda":"の品川区空き家等対策計画","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"空き家問題というのは結構関心が高いと思うのですけれども、パブリックコメントが１名１件というのは、ちょっと残念だなというか、結構内容が非常に本人の思いがこもった意見が１件寄せられているだけに、もう少しこの問題を広く考える上で何とかならなかったのかなと思うのですけれども、担当の住宅課としても、１件という状況の受けとめをまずお伺いしたいなと思います。","respondent":"森住宅課長","answer":"１件というところでございましたが、いろいろな方に見ていただいて、ご理解、ご協力をいただけるものというふうに捉えているところです。","voiceIndex":38,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと中身についてお伺いしたいのですけれども、８ページ、改めてちょっとざっと読んだところで、これはこの条例における空き家と、いわゆる住戸が余っている空き室というのは違うので、非常に紛らわしいところであるなと思ったのですが、マンションとか共同住宅の場合、全部空き室にならないと空き家という位置づけにならないということですよね、この計画上は。","respondent":"森住宅課長","answer":"そういった中で、マンションの課題というのも整理されていくでしょうし、老朽化であったり、居住者の高齢化であったりというような課題が出てきておりますので、東京都とともに適正管理促進という面でしっかりと対応していければというふうに考えております。","voiceIndex":40,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"結果として放置されてしまうというところがあると思うのですけれども、ここの図の中で、建て替え困難とありますけれども、困難ということは、建て替え可能な手法がかなりあるのだということなのか、とは言っても困難でしょうから、こういうところにこそ対策していくということが私は空き家発生の予防ということにもつながっていくと思うのですけれども、ここら辺の対策。","respondent":"森住宅課長","answer":"無接道につきましては、ほかの区と話をする中で、なかなか根本的な解決策は難しいなというところは共通認識としてあるところですけれども、例えば周りの方々にアプローチをしていきながら、共同で建て替えていただくということもありますし。","voiceIndex":42,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"この所有者への意向確認というのは実際どのように行っているのかというのをお伺いしたいのと、それと公的利活用の調整と相談というのは、どんな調整を実際に行っているのか伺わせてください。","respondent":"森住宅課長","answer":"どういった空き家を使えば、どういった事業ができるのかという検討を具体的に進めているところでございまして、それとともに建物をそのまま居住の用で使うということではなくて、何かしら事業で使うということになりますと。","voiceIndex":44,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"ごめんなさい、最後の最後なので、３２ページなのですが、町会・自治会等への情報提供というところですけれども、結構やはり前回もちょっと伺ったのですけれども、特に公園とかが少ない自治会ですとか、町会ですとか、あるいは活動拠点の町会会館がないところというのは、やはり空き室、空き家ですね、土地などのこういった活用というのをすごく望んでいたりするところが結構あるのですけれども。","respondent":"森住宅課長","answer":"区のほうにご相談いただければ、例えば今関係団体との連携ということも計画の中にうたっておりますけれども、具体的な相談窓口の拡充でありますとか、そういった専門家へのつなぎの仕方とかということも含めて今不動産関係団体と協議を進めているところですので。","voiceIndex":46,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"さまざまあるのですけれども、ちょっと確認をさせていただきたいのですが、４１ページの実施体制というところで、四つの柱でいろいろなことを品川区がこれから取り組むという計画になっていると思うのですが、先ほど居住支援協議会の話もありましたし、そもそもある空き家の審議会、空き家等適正管理審議会があるのですけれども、おそらく今住宅課が事務局となってさまざまな取りまとめ。","respondent":"森住宅課長","answer":"委員ご指摘のとおりさまざまな関係部署が連携をしながらやっていかないと、当然空き家に関する問題、居住支援も含めて動いていかないかなと思っています。そういった意味では、空き家を所管している住宅課が居住支援についても事務局をする予定です。","voiceIndex":48,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２１ページですね。私もこういう相談をよく受けるのです。１件１件建築審査会にかけて、いろいろなさまざまな例外を、特例を活用しながら、何とか流通に乗せたいという所有者の気持ちもいろいろある中で、もう少し踏み込んだ対策が必要ではないかなと思うのですけれども、そのあたり、今後の検討になるのかもしれませんが、ちょっとお考えを伺いたいのが一つです。それについてお願いします。","respondent":"森住宅課長","answer":"そういった部分も含めて検討していかないといけないかなというふうに思いますけれども、当然先ほど委員がおっしゃいましたように、ほかの専門家たちの調整ですけれども、空き家の情報交換会という中で、十数団体の方に入っていただいておりまして、この空き家の計画も説明して。","voiceIndex":50,"id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問・要望","question":"前にも委員会等で申し上げたことがあるのですけれども、いわゆる私どもの会派として、さまざまな各種団体からヒアリングを受ける中で、空き家問題に関しては、さまざまな団体が関心を持ち、ある意味ビジネスチャンスでもある、これは率直なところですけれども、あとは非常に社会問題化していて、他区とのかなり比較もできるという中で、ぜひ活用をお願いしてきているところなのですけれども。","respondent":"森住宅課長","answer":"平成３１年３月の時点でのデータですので、来年度にかけて居住支援協議会で具体的な話が進んでいく中で、どこまで入れるかというところもございました。まだまだ検討中でありますので、そこまでは書けていないところが実態です。","voiceIndex":52,"id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-023"},{"speaker":"筒井委員","kind":"意見","question":"１２ページの空き家の地区別分布状況なのですけれども、これは大井地区の大井が空き家数７６戸以上ということで、意外に多いのだなとちょっと個人的に驚いたのですけれども、この大井に多いという理由というのは何かなということをお知らせください。","respondent":"森住宅課長","answer":"荏原地区が断トツで多いですけれども、荏原地区についても、そういったなかなか活用ができなかったり、あるいは小さな戸建てが多いということもあるのかなというふうに思いまして、ここについて、大井地区も同様の傾向にあるのかなというふうに思っております。","voiceIndex":55,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"やはり木密地域と空き家というのは関連性があるというか、リンクしてくるものがあると、そういった理解でよろしいでしょうか。","respondent":"森住宅課長","answer":"木密地域のような道が狭小であったりとか、あるいは先ほど言いました無接道であったりとか、そういったところが比較的多いところにつきましては、どうしてもそのまま残ってしまうということも出てくるのかなというふうに考えております。","voiceIndex":57,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"７ページの人口変動のところで、今後２０３３年をピークに人口が減っていくから空き家も増えていくのではないかということも、そうしたことを言われているのかなと考えていますけれども、人口変動がこの計画全体のどの辺あたりに影響があるのか、今長期基本計画策定委員会、今年の１月９日に出された資料によると、これは一番新しい人口動態なのかなと思うのですけれども、２０４４年にピークを迎えると。","respondent":"森住宅課長","answer":"今最新のというふうにご紹介いただいたものにつきましては、企画調整課のほうに確認いたしまして、最新のものが公表できるのであれば、しっかりと載せていければなというふうに思っております。","voiceIndex":59,"id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"４３ページの空き家ホットラインのところで、相談体制ということなのですけれども、見れば連携内容ということで、各課が皆さんでやっていただいているということなのですけれども、この中で、昨日も議案の審査かなんかで合理化をすることによって、物事の手続上の短縮を見ることができたという部分で、これは各課がいろいろなところで連携をしながらやっていただいているのですけれども。","respondent":"森住宅課長","answer":"下の相談体制の中では、空き家ホットラインを今開設しておりますので、そちらにご相談をいただいて、その内容によって専門家団体でありますとか、あるいは区の各課にそれぞれ情報を流しながら相談する方のご要望に対応していきたいというふうに考えております。","voiceIndex":61,"id":"exchange-027"},{"speaker":"大沢委員","kind":"質問","question":"全体調整で住宅課という表記があるのですけれども、今までの実績の中で、空き家の相談を受けてから解決するまで、大体どれぐらいの期間が、いろいろとものにもよるでしょうけれども、平均すると大体どのぐらいかかるものなのでしょうか。","respondent":"森住宅課長","answer":"その後通知を出しまして、所有者の方が改善していただくということで、すぐに対応していただければ２カ月程度で終わるのかなというところもありますし、なかなか通知を出しても改善されないところもありますので、そういったところについては２度、３度。","voiceIndex":63,"id":"exchange-028"},{"speaker":"大沢委員","kind":"質問","question":"この中で、法律は、区は法律を制定する側ではないのですけれども、条例等々は区で決まりをつくるということなのですけれども、国の動きで、空き家の通報なり、空き家の相談を受けてから解決するまでに合理的な方法でできるような、国土交通省とかという国のほうの動き、あるいは都の動きというのはあるのでしょうか。","respondent":"森住宅課長","answer":"基本的には市区町村が対応していくという形で、それを国や都がいろいろな財政面であったり、情報面であったりというのを補完していくということになるのかなというふうに思います。","voiceIndex":65,"id":"exchange-029"},{"speaker":"大沢委員","kind":"質問","question":"住宅課の方たちがこういうことで空き家対策担当の方もいらっしゃるのですが、今の住宅課の方たちの業務量からしても、人員というのは完璧に間に合っているのですか。","respondent":"森住宅課長","answer":"当然それぞれさまざまな問題が絡んできますので、空き家担当だけではなかなか難しいところもありますので、今４３ページの上のほうに記載してあります各課としっかりと連携をしながら進めていければなというふうに思っております。","voiceIndex":67,"id":"exchange-030"}]},{"id":"topic-03","title":"中延二丁目旧同潤会地区防災街区整備事業に伴う施設建築物の竣工","agenda":"中延二丁目旧同潤会地区防災街区整備事業に伴う施設建築物の竣工","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"権利者の方について伺いたいのですが、もともとこちらの地区内の地権者は何人で、うち何人が同意したのか、また、建物に実際入ったのは何人おられるのか伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"共有持ち分等がありますので、それを除きますと全１１７名の権利者という形になります。同意は１００％の方の同意をいただいていると事業組合から報告を受けております。この１１７名の権利者のうち、建物、竣工後の建物にお戻りいただく権利者数は６５名です。","voiceIndex":73,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"同意は１００％ということになるのですね。入ったのが６５名だということなのですけれども、そこら辺はどういうふうに考えたらいいのかというか、建物に入らなかった方というのは同意したということになるのか、そこら辺をちょっと伺いたい。それと、住戸数１９５戸のうち、従前住んでいた方のいわゆる権利床というのですかね、これは何戸なのか、残りの保留床はどこが買い取ったのか伺います。","respondent":"高梨木密整備推進課長","answer":"戻られていない方、それぞれご事情があるので一概には言えないのですが、皆様地区の外に転居されて、そちらで新たな生活を営むというような状況です。ですので、戻ってこない方々が同意していないといったような考えではございません。","voiceIndex":75,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"そこで働いている方にとっては、何かいいかもしれないのですけれども、もう少しこういう再開発的な手法で整備される公園というのは、区立なわけですから、地域の方の意見というのを入れて少なくともやらなくてはいけないのではないかと思うのですけれども、今回この公園の整備計画に当たって、周りの住民の方の意見というのはちゃんと聞いたのかどうか、伺いたいなと思います。","respondent":"高梨木密整備推進課長","answer":"公園のしつらえにつきましては、事業組合が地域の皆様、もともと住まわれた皆様で組織されている事業組合の中でどういったしつらえにするのかといったことをご議論いただいて、それを区とも協議の上しつらえについては決定したという状況です。","voiceIndex":77,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"それと、資金計画について伺いたいのですけれども、総事業費と補助金額と公共施設管理者負担金と協力事業者、先ほど旭化成不動産レジデンスという名前が出ていましたけれども、協力事業者が保留床を買い取った価格というのは、それぞれ幾らなのか伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"事業費にかかる質問ですが、まず総事業費は約１０１億円となっております。そのうち、補助金が全部で約３８億円となっております。公共施設管理者負担金はございません。旭化成不動産レジデンスが買い取った金額は、区では把握しておりません。","voiceIndex":79,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"こういった３８億円という額があれば、もともとこういう課題の解決ということでやっているのでしょうから、そういった何棟かあった住宅の耐震化に直接当てれば十分防災性の向上というのは達成できたのではないかというふうに思うのですけれども、私は今後そういう事業者をかませなくていいのではないかと、品川区がきちんと自分たちの責任で改善するというのであれば、防災対策。","respondent":"高梨木密整備推進課長","answer":"その効果としましては、その個々の建物が火災に強い建物に変わったのみならず、周辺の道路の拡幅、それとこれもまたエリアの中で不足している公園、広場の設置といったことで、その地区の中だけではなく、広くその周辺の防災性向上に寄与する事業であったという認識です。","voiceIndex":81,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは地元の議員からよく聞いているのですけど。ですから、私はそこら辺というのは大きな課題なのではないかと思います。高層化というようなところありきではなく、やはりもう少し同じ共同化にしても、きめ細かく住民と粘り強く対話をしながらできなかったのかと、３８億円もあればという思いがあるのですけれども、そういった方向で今後区も汗をかいていただきたいと思うのですけれども、いかがでしょうか。","respondent":"高梨木密整備推進課長","answer":"区のほうでこの事業ありきで、決め打ちで強引に進めたというようなものではございませんで、皆様方、まずは住んでいらっしゃる地権者をはじめ、区民の方々、皆さんのご同意を得て今回はこの手法を選び、進めたところで。","voiceIndex":83,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"そういういろいろな、さまざまな思いがある中で、本当に十分に選択肢が提示できていたのですかというのがちょっと私はもう少し努力が必要だと思うのですけれども、質問なのですけれども、そういう区道、道路が広がったとか、集会所とかというのは、確かに今回メリットなのでしょう。それというのは、この手法でないとできなかったのでしょうか。そこだけちょっと伺わせてください。","respondent":"高梨木密整備推進課長","answer":"当然そういったものをもらわずにできないかと、お金があれば幾らでもできる可能性はありますけれども、区といたしましては、そういったそこの場所だけではなく、周辺を含めた地域の防災性の向上を目指すといったところと、国。","voiceIndex":85,"id":"exchange-037"}]},{"id":"topic-04","title":"の武蔵小山賑わい軸街並み再生方針（案）の説明会開催","agenda":"の武蔵小山賑わい軸街並み再生方針（案）の説明会開催","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"資料の文言等についてお伺いしたいのですが、Ａ３のカラーのほうなのですけれども、右下のほうに再開発等促進区ということが書いてありますけれども、これはどういう内容なのかご説明いただきたいというのと、左上の中に、２の整備すべき公共施設ということで、道路の配置とありますけれども、現在のイメージとしてはどこら辺を想定しているのでしょうか、伺います。","respondent":"稲田都市開発課長","answer":"そういう中で、こういう方針等を策定するというもので、特にこの段階に来たから上位計画をつくらなければいけないとか、あるいはそのままでいいとか、進めておこうとか、そういう話ではありませんで、まちづくりの方針が必要というふうに考えられたときにつくるものです。","voiceIndex":95,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"それと、左のほうですけれども、一番下の実現に向けて講ずべき措置というところで、ルールを守った際の規制緩和等を定めるということですけれども、これだとルールを守るか守らないかというのは任意なのかなというような気もしてしまうのですけれども、ここら辺については、ルールを守ったらこういうメリットがあるのですよと、そういう意味なのかどうか、ちょっとお伺いしたいなというふうに思います。","respondent":"稲田都市開発課長","answer":"そういうものをやったら容積の割増ができます。それ以外に、この地区では、このまちの活性化、商業の賑わい、そういうものを高めるためのルールを守っていったら、さらにメリットがありますよというような制度です。","voiceIndex":97,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"そういう二段構えみたいな感じのイメージなのかと思いました。アーケード等の改修というものも入っていますけれども、地元の皆さんが感じている課題というのは、どこにあるのか、何なのかというのをお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"そういうものを改善して、災害に強いまちにしたいというところと、それからもう一つ大きいものは、商店街の賑わい、商店街を囲むような形でこの地区は設定しておりますので、そういう中におきましては、商店街の活性化をさらに進めて、よりよい賑わいを創出していきたいです。","voiceIndex":99,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"このまちづくり方針で、武蔵小山の一つの大きな特徴であるアーケードというのは残るのですかというのをちょっと伺いたいと思います。","respondent":"稲田都市開発課長","answer":"アーケードの再構築というものにおきましては、やはり重要なポイントでございまして、アーケードを残して、さらにそれを複層的な使い方というのですか、作り方というのですか、そういうものにしながら、まちを活性化できたらというところで、人々の回遊性、線的な商店街から。","voiceIndex":101,"id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後になりますけれども、説明会のことが書いてありますけれども、最初に東京都へ方針案を提出するのが４月ごろということで、かなりタイトなのではないかなと思うのですね。そういった意味で、この説明会でいただいた意見というのは、どういうふうに案に反映されていくのか、それを伺いたいと思います。","respondent":"稲田都市開発課長","answer":"そういう中におきましては、反映する基本的なところとか、そういうところとかは反映の仕方というのは考えなければいけないかというところはありますが、この地域説明会でいただいたご意見で、これは必要だなとか、そういうところに話がなってくれば。","voiceIndex":103,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"地権者ということで、それは基本的に地権者の財産ですから、そういうことになるかもしれませんけれども、やはりまちづくり、特に商店街のあるところですから、やはりそれを長年親しんで訪れてきた、買物で利用されていた方の意見というのは、すごく私はほかの地域以上に反映していく必要があるのかなというふうに思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-043"}]},{"id":"topic-05","title":"の区内の魅力的な建築物の公開イベント「オープンしなけん」","agenda":"の区内の魅力的な建築物の公開イベント「オープンしなけん」","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"非常にすばらしいイベントだなと思います。やはり、こういう魅力を発見して後世に伝えていくというのは重要ではないかと思います。東京建築アクセスポイントが行ったという調査の内容の概要をちょっと伺いたいのですけれども、事業として予算を計上されてやったことだと思うのですけれども、もう少し、今後委員会への報告などを別途求めていきたいなと思うのですけれども、いかがでしょうか。","respondent":"長尾建築課長","answer":"今後の議会報告につきましては、調査の結果や今回のようなイベントの開催につきまして、もう少し丁寧にご報告できるように努めてまいりたいと考えております。","voiceIndex":110,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"ぜひ、お願いします。今後の開催なのですが、今回１回目ということで、継続的に事業としてやっていくという予定があるのかどうか伺います。それはなぜなのかということと、それと原美術館の建物について、事業を行った区としての評価というのはどのような感じなのかお伺いします。","respondent":"長尾建築課長","answer":"ただ、今回１回目のオープンしなけんを開催した実施結果というか、実績をもって、改めて今回ちょっと協力を得られなかった建物の所有者についても、話を再度しに行ければというふうにも考えておりますので、その中で建築物の公開の協力が得られればと考えております。","voiceIndex":112,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ存続といいますか、少なくとも建物自体は存続していただきたいなという思いがあるのですけれども、区としては今何かつかんでいるところがあるのか、そして、こういう百景に入っているところがなくなってしまうというふうにもし仮になったら、それは区としても損失になるのではないかと思うのですけれども、存続に当たっての区のお考えなどはどういうふうになっているのか伺いたいと思います。","respondent":"長尾建築課長","answer":"原美術館の存続に関するご質問ですけれども、こちらのほうで今後の原美術館の予定は詳細には把握しておりません。","voiceIndex":114,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"大崎図書館のほうは、単独図書館ということ自体が珍しいという中で、図書館としてどういうふうな建物がいいのかということを考えてつくられたという経緯もあるので、やはりそういった思いというのは、すごく詰まったものだと思いますので、ぜひこちらも改めて調査をしていただきたいというふうに思うのですけれども、そして、できるのであれば、保存、活用を含めて検討していただきたいと思いますけれども。","respondent":"長尾建築課長","answer":"今後の調査につきましては、来年度の予算の中でも計上していますので、その中で区内の魅力の発見、再認識につながるような建物をまた改めて今回の調査も踏まえて、調査内容を深めていければと考えております。","voiceIndex":116,"id":"exchange-047"},{"speaker":"大沢委員","kind":"質問","question":"この事業というのは、建築課がやられていますけれども、国土交通省が策定した「歴史的建築物の活用に向けた条例整備ガイドライン」というのはご存じでやられているのですか。","respondent":"長尾建築課長","answer":"国土交通省のガイドラインで示されております歴史的建築物とか保存活動にかかわる部分のガイドラインかと思いますけれども、今回のこの調査に当たっては、特にそこの歴史的な建築物というところだけに縛られずに、もう少し幅広く調査を行っておりますので。","voiceIndex":118,"id":"exchange-048"},{"speaker":"大沢委員","kind":"質問","question":"直接的に、まず入口ということで、先ほど伺いましたけれども、これをやっていくうちの成果物として、どのようなことを見込まれながらこの事業をやっていくのか教えてください。","respondent":"長尾建築課長","answer":"そういった部分の側面を建物の所有者の理解と協力を得ながら、地域資源としての発掘といいますか、位置づけができれば、その先には特に建築課だけにとどまらず、今回もしながわ観光協会のホームページでの情報共有であるとか、あと調査に当たっては教育委員会事務局であったり。","voiceIndex":120,"id":"exchange-049"},{"speaker":"大沢委員","kind":"質問","question":"観光協会に観光ガイドがいるわけですけれども、今ざっと見たところ、専門家の方がガイドとして今回はつくようですけれども、今後そこの観光協会のガイドたちからレクチャーを受けながらこの事業を進めていくと思うのですけれども、そこが１点と、今度私有財産であると同時に、やはりある程度歴史的建築物であれば、観光資源としての意味合いも持って、半分公といいますか。","respondent":"長尾建築課長","answer":"建築基準法の中でも、先ほどご紹介いただいたガイドラインに沿った形での文化的な古い建築物の保存活用というところも一定程度国から方針が示されているところもありますので、そういったところを活用しながら、また建物所有者のご意向もありますので、丁寧に聞きながら。","voiceIndex":122,"id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それとあと、いろいろ私も東京デザインセンターなんかを見た時に、いつも非常にいいデザインだなと思ったり、さっき原美術館の話がありましたけれども、原美術館は私も大好きでよく行っていたのですけれども、群馬のほうの原美術館も行ったことがあるのですけれども、私は結構こういうのが好きなのですけれども、これを見ると、このツアーなのですが、基本的には一つの施設につき１回しか行けないというか。","respondent":"長尾建築課長","answer":"そのため、年度当初の段階でこういった内容でやるというところは決まっていなかった状況があります。ツアーの件につきましては、今回最後のクロージングトークを除くと、１５個イベントがあります。","voiceIndex":124,"id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"わかりました。多分参加するほうとしては、好きな人は多分ものすごく好きな区民の方、好きな方は好きでしょうから、次回はもっと行ってみたいとか、全部参加できないぐらいでちょうどいいのかなということもあるかもしれませんので、わかりました。それは一定の理解をいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-052"}]},{"id":"topic-06","title":"の目黒川安全航行啓発イベントの実施","agenda":"の目黒川安全航行啓発イベントの実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今年はちょっと桜の開花が早いという話もあるのですけれども、この日時、選定した理由を伺いたいのと、それで、この時期というのは、かなりこういう船が通る時期だと思うのですけれども、どれぐらいこの日以外にも就航して、このマナー啓発というのは、大体そのうちのどれぐらい、これで十分といいますか、運航の状況というのですかね。","respondent":"持田河川下水道課長","answer":"ともにやはり２日間、過去２年間とも２日間をマナー啓発イベントの実施時期というふうにしてございまして、船の２日間の総計ですが、平成２９年につきましては、２日間で３１２隻の船が通行しており、平成３０年につきましては、２５０隻ということで。","voiceIndex":136,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"かなりの数だということですよね。この日以外の運航の状況というのは、区としてはどれぐらいつかんでいるのか、もしつかんでいらっしゃいましたら、教えていただきたいなというふうに思います。実際にマナー向上委員会の警戒船に乗る方というのは、区の職員の方が乗って、現地で確認しているのか、そこら辺を伺います。","respondent":"持田河川下水道課長","answer":"１つ目のこの日以外の状況ですが、具体的数字としては、ちょっと今手元にございませんが、他のイベント等の実績からも、この２日が多いということで、これ以外の日は先ほど申した３００隻から２００隻よりもかなり少ない数という形になっております。","voiceIndex":138,"id":"exchange-054"},{"speaker":"筒井委員","kind":"質問","question":"護岸接触注意、別紙１の川のところに黄色い星マークのようなものがありますけれども、それが護岸接触注意の印なのだと思うのですけれども、実際やはり護岸にプロペラがぶつかって事故が発生したという事例が何回かあったからこういう星マークをつけたのか、もしかして、そういった事故があったのでしょうか。そうした記憶がありましたらお知らせください。","respondent":"持田河川下水道課長","answer":"大きな事故の報告というのは、所管のほうでは記憶としてはないのですが、そういった意見をたくさんいただいているというところから、このような形の注意喚起をしています。","voiceIndex":140,"id":"exchange-055"},{"speaker":"松永副委員長","kind":"質問・要望","question":"私から１点わからない部分があって、これは工事上のあれかもしれませんが、矢板の残置とあるのですけれども、よく川とか海沿いとかによく見られる光景なのですが、これは取り除いてはだめなのですか。それとも、何かそのまま残している理由等があれば、教えていただきたいと思います。","respondent":"持田河川下水道課長","answer":"全て引き抜くのはなかなか難しいということで、では上部を切断して撤去するというような方法をよくとるわけなのですが、目黒川などでちょっと目立つところはやはり上部を切断するときの切断の長さが少し短いのではないかと。","voiceIndex":142,"id":"exchange-056"}]},{"id":"topic-07","title":"の第３５回品川区防災フェア","agenda":"の第３５回品川区防災フェア","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"チラシのほうに豚汁の提供ということで、陸上自衛隊ということでありますけれども、関係団体による自主出店と、あるいは緊急車両展示など、実施内容にあるのですけれども、こちらの自衛隊の出店はあるのか伺いたいと思います。今安倍首相の発言などで、自衛隊募集に焦点が当たっておりますけれども、当日隊員募集のコーナーなどはあるのか伺いたいと思います。","respondent":"古巻防災課長","answer":"防災フェアに関しましての自衛隊の方のご協力につきましては、一つは毎年行っております豚汁の炊き出しをしていただくことと、あとは車両の展示等を予定しております。特にここで何かそういった募集事務等をやるというような予定はございません。","voiceIndex":148,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"この中で、今質問したのは、安倍首相が国会の中で自治体の自衛隊募集の問題についていろいろやりとりがあったのですけれども、やはり品川区のほうで自衛隊募集の協力というのは、現状どのようになっているのか。こういった場所では、どういうふうになっているのかなということもあって伺ったのですけれども、募集のブースはないということでしたけれども、もしわかれば現在の…。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-058"},{"speaker":"あくつ委員","kind":"確認","question":"毎年私も参加させていただいて、自衛隊の方と防災課ですよね、豚汁とカレーライスもいただいております。そこら辺について確認させてください。","respondent":"古巻防災課長","answer":"本年度予算でＶＲの機器にプラスしまして、オリジナルコンテンツの作成をしておりまして、３月９日を目指して今最終的な調整をして、この日にお披露目ができればというふうに考えております。","voiceIndex":154,"id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問","question":"いわゆる防災アプリと一緒なのかなと思うのですけれども、これは今後活用というのはあるのでしょうか。","respondent":"古巻防災課長","answer":"一つは、防災体験館で今でも既存のというのですかね、業者のほうで独自に開発したものは公開しておりますけれども、品川区の独自コンテンツにつきましても防災体験館で公開して、あとは防災訓練等を出張で公開して、皆さんに体験していただけるような形を考えております。","voiceIndex":156,"id":"exchange-060"},{"speaker":"あくつ委員","kind":"確認","question":"なぜかというと、例えば今ご家庭でもＶＲ対応のこういう機器というのはたくさん出ています。私の子どもも持っていますし、スマートフォンの中に入れれば見られるようなものもあって、コンテンツ自体は例えばそれを公開していただければ、そういうものが広くみんなが体験できるというものもあるのですけれども、品川区に何か特化したような内容になっているのか、そこだけ確認をさせてください。","respondent":"古巻防災課長","answer":"ただ、一般的な公開ができない、専用の機器で見ていただくものになりますので、今のところは公開という形では考えておりません。","voiceIndex":158,"id":"exchange-061"},{"speaker":"松永副委員長","kind":"質問","question":"今回のこの防災フェアについてなのですが、防災関係団体によるブース出店の中に、ペットと同行避難する際に必要なグッズ等の販売をしているブース等は出るのかどうかというのをお聞きします。","respondent":"古巻防災課長","answer":"特にペットの同行避難に関する物品等の紹介というのはなかったと思います。","voiceIndex":160,"id":"exchange-062"},{"speaker":"松永副委員長","kind":"質問・要望","question":"わかりました。ぜひ来年はよろしくお願いいたします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-063"},{"speaker":"横山委員","kind":"質問","question":"１点だけお伺いいたします。高知県の産業振興センターが参加団体ということで入っているのですけれども、高知県の内容などの詳細がもしおわかりになればですが、やはり防災に関する情報の共有であったりですとか、高知県の先進的な事例を紹介していただけるような何か資料ですとか配布物を見せていただけたりとか、そういったことはあるのでしょうか。","respondent":"古巻防災課長","answer":"初回ということもあって、そんなに大きなブースを出す予定ではございませんので、高知県はいろいろな防災対策製品の開発等をしておりまして、そういったものの紹介ということで、ご案内いただいております。","voiceIndex":163,"id":"exchange-064"},{"speaker":"横山委員","kind":"質問・要望","question":"高知県は昨年被災されて、色々な経験をされているかと思いますので、そういったさまざまな情報交換なども今後進めていただいて、また来年度以降に広げていっていただけたらと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-065"}]},{"id":"topic-08","title":"の品川区国民保護計画の変更","agenda":"の品川区国民保護計画の変更","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"主な変更点というのは、(1)のア、イのうちのイの部分かと思います。二つの合同対策協議会というのは、具体的にどのようなものなのか、それぞれありますこの事態、武力攻撃事態、緊急対処事態とはどういう事態なのか。それと、相互協力とありますけれども、区はどのような協力を行わなければならないのか、以上３点伺います。","respondent":"冨澤災害対策担当課長","answer":"武力攻撃事態等合同対策協議会ですけれども、これは国のほうで現地にどの大臣の方が来られるのか、ちょっとそこははっきりしないのですけれども、そこの本部長である方が仮に品川区で災害があった場合に、そこの対策本部と連携をしながら、どういう状況の支援ができるのか。","voiceIndex":170,"id":"exchange-066"},{"speaker":"安藤委員","kind":"意見","question":"国がこういう国民保護計画というものをどんどんつくって、下におろしていくのでやむを得ないところがあるのかもしれませんけれども、やはり明日は歴史的な２回目の米朝首脳会談が行われますけれども、こういった保護計画というのをどんどん具体化していくということに注意をするというより、私はやはり日本としてしっかりとこういう外交と対話による、こういった事態を起こされないような。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-067"},{"speaker":"筒井委員","kind":"質問・要望","question":"主な変更内容のところで、(2)区に関する箇所で、区の組織名称が修正されるということなのですけれども、具体的にどういう名称になるのか、わかる範囲でお答えいただきたい。","respondent":"冨澤災害対策担当課長","answer":"この部分を例えば徹底せよと、またあわせまして、昨年度地域防災計画が変更されております。その地域防災計画の中の災害に対応する組織体、こちらも変わっておりますので、それに合わせるような形で変更を行うものです。","voiceIndex":173,"id":"exchange-068"},{"speaker":"筒井委員","kind":"質問","question":"昔のそうした部とかの名称のままだから、それを単純に今のものに変えていくだけという理解でよろしいのでしょうか。","respondent":"冨澤災害対策担当課長","answer":"そのとおりです。","voiceIndex":175,"id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4258#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":64542,"voices":185}},{"id":"r01-20190226-9","meetingId":"r01-cm02","date":"2019年2月26日","dateIso":"2019-02-26","committee":"文教委員会","time":"午前１０時００分～午後 ０時２７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"確認","question":"ですから、できるだけ本当に慎重に、質問するべきはもっと事前の質問時間のときにしてそこの部分を確認されて、それで態度表明のときは、お互いに間違いはあることを前提で言っているのですけれども、私などは特にそうなのですけれども、やはり態度表明のときは本当にそういう取り消しがないような状況をつくって、質疑を完了していきたいと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"を行います。 予定表１、報告事項の聴取をいたします。初めに、(1)平成３０年度品川区教育委員会事務事業の点検および評価報告書","agenda":"を行います。 予定表１、報告事項の聴取をいたします。初めに、(1)平成３０年度品川区教育委員会事務事業の点検および評価報告書","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"改めて確認なのですが、今読み上げた名和田先生の１番のところの教職員支援経費の部分の中ほどで、教育委員会が充実した教職員支援体制を整備していることを評価されているわけですけれども、改めて、この教職員支援体制というのはどういうことなのかを確認をさせていただきたいと思います。","respondent":"熊谷指導課長","answer":"教職員支援経費ですけれども、まずこれまで品川区におきましては、学校働き方改革「しながわ働き方ルネサンス」を平成２９年から実施してきております。その中で、具体的にどのような支援を行ってきているかというところですけれども、人的措置・環境整備をまず行ってきています。","voiceIndex":11,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"ありがとうございました。改めてそうやって全体的な取り組みを一定程度まとめて報告していただくと、その支援体制の規模・中身がわかるかなと思って伺っていたのですけれども、そういう状況・体制をとっていただきながらも、現実的には先生方が十分な授業準備をする時間がなかなか確保できないという事実はあると思うのです。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは８番のマイスクールの運営のところなのですが、教育委員からの意見の「専門的な人員が必要になってくる」というところで、このところ浜川の中学校の中にもできて、マイスクールの環境が充実をしているのですけれども、やはりさらなるというか、いろいろ専門的な人を入れてというあたりでは、どのような関係の人が必要になっているのかというのを１点教えていただきたいです。","respondent":"大関教育総合支援センター長、熊谷指導課長、横山品川図書館長","answer":"直接対応した経験がなかったとしても、そのような学校の状況がわかっている、学校と情報共有が誰とでもできる、そのような人員が重要であると考え、今。学校図書館の司書教諭についてですけれども、１２学級以上は必ず司書教諭を置くと学校図書館法で決まっておりますので、こちらについては。外国の資料の充実のために、平成３１年度予算で多言語の図書の書籍の指標になりますＭＡＲＣというものを所蔵できるように。","voiceIndex":15,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"司書教諭のところは人数を教えてほしいのと、あと司書教諭の配置されていないところへの援助とか、何かそういう学校図書館に関しての話し合いとか連携が持たれているのかどうか、ひとつ教えていただきたい。","respondent":"熊谷指導課長","answer":"小学校につきましても１０名、中学校につきましては１名。本来でしたら２名配置の予定なのですけれども、ちょうど異動者で司書教諭が配置できなかったということで、今年度は１校のみ配置ができなかった学校があります。","voiceIndex":19,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つ先に聞いておきたいのは、小学校・中学校、教員の正規の方と非正規の方の割合、わかったら教えてほしいです。国の教員勤務実態調査というのが、２０１６年、小学校と中学校で調査されたのですが、その中身によると、教員は月曜日から金曜日まで毎日平均１２時間近く働き、あと休みのはずの土日も働いていますと。その点に対してどう考えていらっしゃるのか聞かせていただきたいと思います。","respondent":"熊谷指導課長","answer":"学校規模や教科によって持ち時数というのは様々ですので、これについてはコマが減ればということで一概に判断することは難しいと考えています。","voiceIndex":21,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"非正規の教員の方は割合的にどのぐらいいらっしゃるのですか。この中においては、本当に１授業に対して１時間の準備はできないと思うのです。そういった意味だけでなくて、現場を抱えている品川区の教育委員会として、やはりそこの教員の超過勤務のあり方とか、そういうことについてしっかりと意見を持って言っていかなければいけないと思うのですが、その点はいかがでしょうか。","respondent":"熊谷指導課長","answer":"超勤４項目につきましては、こちらも国で定めているところですので、私どもとしては国や都の動向を見ながら、それに準じて行ってまいりたいと考えております。","voiceIndex":23,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"授業のコマ数問題は多分大もとのところ、先生たちはすごく感じていると思いますので、４％の調整手当のところも国や都の動向を見るのではなくて、やはり現場の声をしっかり聞いて伝えていっていただきたいと私は思います。そういった意味においては、やはり広く意見を聞く必要があると思います。この教職員の給与４％上乗せというのが一律に支給されるようになってから、これは１９７１年の実績で４％ですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問","question":"とりあえずちょっと根本的な部分でお伺いしたいのですけれども、いわゆるこの事務事業、今日出されているものというのは、これは教育委員会として点検をしているものなのか。いわゆるシートの中に「教育委員からの意見」というのがあって、教育委員の方たちがチェックをされているのか、そこをまず教えてください。","respondent":"有馬庶務課長","answer":"要領の中の点検評価の実施というところで、教育委員会がまず対象事業の点検評価に関する評価案を審査していくということで、その管理等、執行状況について意見を付すと。","voiceIndex":26,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問","question":"そうすると、いわゆる教育委員会事務局がまず点検をして、それを教育委員会に上げて、教育委員の方たちの意見を付して戻してくるということの理解でいいのですか。","respondent":"有馬庶務課長","answer":"そこで議案として上げますので、戻すといいますか、そこで議案として今年度はこういう形で事務事業評価としますということで承認され、それを当然法律に基づいて議会に提出して、最終的には区民に公表するわけですので。","voiceIndex":28,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問","question":"ではこのシートに基づいていくと、総合評価があって、今後の方向性があって、教育委員からの意見があると。最終的には教育委員会で諮って決定はされるのでしょうけれども、ここに出てくるこの内容というのは、もともとはいわゆる事務局が評価をして、事務局が方向性を示したものを最終的に教育委員が決定をしていくというのでいいのでしょうか。","respondent":"有馬庶務課長","answer":"ただ、実際実務上とすれば事務局のほうで原案をつくって、こういう形で評価していますが、ご意見をくださいというような形にはなるわけですけれども、最終的にはそれを承認を得たということで教育委員会で決定した中身と、最終的には教育委員会で決めた中身ということになります。","voiceIndex":30,"id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問","question":"結局順序の問題で、最後にその意見が書かれると、今後の方向性と総合評価にはこの意見というのは、最終的には全部を教育委員会がオッケーを出すのでしょうけれども、この意見というのがそこに反映されることというのは、評価は変わらないのかもしれないけれども、例えば方向性が若干変わってくるのかなと思うのだけれども、そこは教育委員がそういう話をしてるから、じゃあ。","respondent":"有馬庶務課長","answer":"それで承認を受けて、初めて事業も決定されます。それから、それに基づいて我々が予算を通じて暮れぐらいまでにこのシートをつくり上げます。そのときに、一旦今こういう形でまとめておりますけれども、これについてご意見をくださいというような形で意見を聞く場があります。","voiceIndex":32,"id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問","question":"そこで、最後のところのいわゆる学識経験者からの意見というのが示されていますが、この意見についてのいわゆる教育委員会の見解というのはあるのですか。この意見というのは、いわゆるこの法政大学の教授の方に依頼をして、この対象事業２つについてご意見を頂戴したわけですね。この頂戴したご意見に対しての区の見解というのは、どこかに出てくるのでしょうか。","respondent":"有馬庶務課長","answer":"そこで意見はいただいてはいます。最終的には、今回で言えば、まず教職員支援経費というのは評価シートの４番にこれは重なっております。","voiceIndex":36,"id":"exchange-013"},{"speaker":"石田（し）委員","kind":"確認","question":"ということは、この意見も事前に聞いていて、このシートを作成するにあたって、その学識経験者の意見も全部このシート内に反映をしたものを教育委員会で諮って、最終的に議会に出てきたということでよろしいのでしょうか。そこを最後に確認です。","respondent":"有馬庶務課長","answer":"そのとおりです。","voiceIndex":38,"id":"exchange-014"},{"speaker":"石田（し）委員","kind":"確認","question":"それをもとに、品川区教育委員会としては、いわゆる教員がやるべき事務と教員がやらなくていい事務というのをしっかりと選別をして、そのやらなくていいですよという事務に対して、このスクール・サポート・スタッフも含めていわゆる専門的な人の配置をされているのかどうか、確認させてください。","respondent":"熊谷指導課長","answer":"その取り組みが教育委員会の効果的な取り組みということで、都のほうから効果的な事例として、全ての区立学校に公開されたところです。","voiceIndex":40,"id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なので、そこは引き続きやっていただきたいなと思うし、この負担軽減の部分というのは、もちろんそれもあるのだけれども、もう一方で、今、いわゆる最新技術を活用すれば大分減るのですよね。これはあくまでもスクール・サポート・スタッフの経費のみのことなのか、いわゆる教職員支援経費全体のことをこのシートで示しているのか、最後にそこだけ教えてください。","respondent":"熊谷指導課長","answer":"この中に、具体的にそういったものについては含まれておりません。","voiceIndex":42,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかあって、１つは先ほどこれはホームページにアップされるということですが、ホームページにアップしますよという広報はどのようにするのですか。は固有教員、これは前にほかの委員もお話しましたが、３０人に達するのに近いのですけれども、そこについて今後の方向性がちょっとわかりにくいので、その点をお尋ねします。本を中学生は学校図書館で年に１０冊ぐらいしか借りていない。","respondent":"有馬庶務課長、熊谷指導課長、大関教育総合支援センター長、横山品川図書館長","answer":"私から、最初の公表、ホームページへのアップと、最後のほかの事業についてお答えいたします。固有教員についてですけれども、１５中学校区に３０名の配置を目途に行ってきているところです。特別支援に関する研修の状況ですが、まず初任者の年１０回程度行われる研修会の中で、必ず特別支援の内容は位置づけて実施しております。これは全国的な傾向でございまして、国のほうは不読率という形で目標を定めて改善計画を立てているところですが。","voiceIndex":45,"id":"exchange-017"},{"speaker":"つる委員","kind":"確認","question":"確認で、１７ページの名和田教授の教職員支援経費のところですが、触れられている中ほどの部分、品川区として独自支援をしたことを高く評価されている中で、「例えば」というところで、「国の調査においても教職員の業務上の負担感を感ずる場合のトップをなしている『国や教育委員会の調査等』についても、教職員自身でなくても回答可能な項目は教育委員会で埋めてしまうなどの配慮をするなど」とあり。","respondent":"熊谷指導課長","answer":"こちらについては、国や文部科学省、それから東京都教育委員会から、学校に調査が入ることがありますけれども、そのときの調査ということで、学校がたくさん空欄を埋めていくのは大変なので、区教育委員会として把握しているところは先に区教育委員会で埋めてしまって。","voiceIndex":51,"id":"exchange-018"},{"speaker":"つる委員","kind":"確認","question":"教育委員会も教育委員会で大変な業務を抱えている中で、現場の学校の先生をサポートしているということで、そういうひずみがどこかで起きてはいけないのかなということで、あえて確認をさせていただきました。","respondent":"篠田学務課長","answer":"ですので、お子さん方が増えたことによって学級数が増えますと、それによって要はまた基準のハードルが上がってしまうものですから、そういったことも含めましてなかなか達成できていないというような状況もございまして、ご説明させていただいたところです。","voiceIndex":53,"id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"そうするとこれは蔵書となっているので、学校図書館ではない通常の図書館などはバックヤードとかそういうものもありますけれども、学校の場合でも本棚に置いてあるものとバックヤードという部分があるのかどうかわかりませんが、そういうのを含めていわゆる蔵書という中で、今の学級数が増えていることでのどうしても追いつかないというところなのかなというのと。","respondent":"篠田学務課長","answer":"予算のほうのお話ですけれども、学校図書館に関しましては、長年にわたって充実というのが問題になってくることがありましたので、平成２７年度までは、大体小・中学校合わせまして３,６００万円程度の予算をつけたのですけれども。","voiceIndex":55,"id":"exchange-020"},{"speaker":"つる委員","kind":"意見","question":"細かいことを言います。なので、予算確保をしていただいている中で、だから廃棄分を当然見越して購入できると思うのです。もう生徒数が増えるというのはわかっているわけですよね。だからそこのところ、本が売れすぎて買えないということではないと思うのですが、そこはちょっと細かいことなのですけれども。","respondent":"篠田学務課長","answer":"ただ、やはり基準として一つ設けられているものですので、その辺は今後工夫しながら考えていきたいとは思っております。","voiceIndex":57,"id":"exchange-021"},{"speaker":"つる委員","kind":"質問・要望","question":"よくある話なのですが、今後の方向性には「スクールコーディネータ」で、教育委員からの意見では「スクールコーディネーター」と、そういったところもホームページにあげるときに、どう検索をかけるかわかりませんけれどもチェックしていただいて、多忙化になってしまうかもしれませんが、精査して、ホームページ掲載するときは修正していただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-022"},{"speaker":"石田（し）委員","kind":"質問","question":"いわゆる中学生とか小学校の高学年ぐらいになるとまだあれなのかもしれませんが、やはり低学年・中学年は、学級閉鎖されてしまうと子どもが家にいるということは、親御さんたちもそのときは会社を休んで家にいざるを得ないような状況にもなって、社会的損失もこれは大きいわけで、またそういった部分も含めると、私はこの学級閉鎖がどこまで効果があるのかなと非常に疑問なのですが、教育委員会としては。","respondent":"篠田学務課長","answer":"感染症の話ですけれども、基本的にはやはりその時点で欠席されている方だけが感染しているとは限らない、当然まだ発症していない状況で菌をお持ちの方もいらっしゃるということで、いわゆる蔓延を防ぐという意味では、２割まで子どもたちが休めば。","voiceIndex":66,"id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"確かに感染症の部分に関してはそうなのですけれども、これはいろいろ考えていただきたいと思いますので、要望だけしておきます。それで、学級閉鎖をされたときの子どもたちのいわゆる教育的なことはどのようにやられているのか。いわゆる課題を与えているのか、どのような教育体制をこの学級閉鎖のときにとられているのか、教えてください。","respondent":"大関教育総合支援センター長","answer":"ただし、教育の必要な時間数につきましては、年間授業時数は当然インフルエンザ、学級閉鎖等もあることを見越して、年３０時間程度は余剰の時間をきちんと見込んで、各学校は計画を立てておりますので、不足するような事態には陥っておりません。","voiceIndex":68,"id":"exchange-024"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"これは全く意味がない。家にいても兄弟姉妹が休んだら元気な兄弟姉妹まで家の中でうつってしまうわけですから、だからそういう学級閉鎖だとかをした場合に、その子どもとそれを取り巻く保護者の方がどういう形で生活できるか、対応できるかということに関して、やはり行政も少しその辺に視点を向けたほうがいいのではないかということを問題提起して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-025"}]},{"id":"topic-03","title":"学事制度見直し案","agenda":"学事制度見直し案","exchanges":[{"speaker":"渡部委員","kind":"意見","question":"これは例えば小山三丁目の方にはこういう説明というので、一般に出すときはもう小山三丁目の話は出さないほうがいいですよ。それと、中学校の選択制に関して広く周知するというよりも、もうこの７年生、８年生、９年生に関して言うのであれば、もっと簡単な資料で地域には説明した上で、３年生、４年生、５年生の保護者会でしっかり状況を伝えれば、もっと区民には簡単な説明でいいのかなという気がする。","respondent":"若生学校制度担当課長","answer":"そういったものも含めまして、個別にご利用される保護者の皆様ですとかご本人が実際どうなのか、自分がどうなるのかというところがより具体的にわかるような形で周知を工夫してまいりたいと考えております。","voiceIndex":76,"id":"exchange-026"},{"speaker":"渡部委員","kind":"質問・要望","question":"先ほど課長のほうから、インターネットで見られるような仕組みをやっていくということで、それも前から要望していたことなので、もうそれをやっていただければ、簡単な説明のほうがいいですよね。選択制が変わりますというのだけざっくり言っておいて、あとは調べてくださいにしたほうが。これは聞けば聞くほど多分わからなくなってしまいますよ。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"でも、今その制度を知らないわけですから、親御さんたちは知らずにして、今ある制度の中で入れていたわけで、彼らにとっては何のあれもないわけですよね。だけど、小学校は６年間なのに経過措置が２年だと、すごくレアケースかもしれないですけれども、そういう方が出てきてしまうのかなと思うのですけれども、その辺はどう考えているのか、その２点を聞かせてください。","respondent":"若生学校制度担当課長","answer":"こちらについては次年度、どういった対応ができるかということを考えてまいりたいと思います。","voiceIndex":79,"id":"exchange-028"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"失礼しました。２点目は大丈夫です。１点目ですけれども、これはぜひスマートフォンでというか、いわゆる携帯電話で入力できるようにというのは強く要望しておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-029"},{"speaker":"つる委員","kind":"確認","question":"先に１ページの２の（２）のところですが、昨年の１０月にご説明いただいたときには私の中で理解していたのですが、今回いろいろ学事制度見直しの中で、新７年生入学時、これはどこに住んでいようと、どこの中学校ないし義務教育学校後期課程を選べるということでいいということですね。改めて確認です。","respondent":"若生学校制度担当課長","answer":"おっしゃるとおり、７年次の入学、これは現在も全校自由に区内どこでも選べるというのをそのまま続けるということです。","voiceIndex":82,"id":"exchange-030"},{"speaker":"つる委員","kind":"確認","question":"ですから、今端末とかを使って自分がどうなのだろうかというところは、結局自分のお住まいのところだけで見てくれればいいのだけれども、どうしても他地域とか少し離れた友達の話とかを聞くと、「え、そういうことできるの」といって、あまりそこに住んでいる方には関係ない情報が入ってきて混乱してしまうということもあるのだろうなと思ったときに。","respondent":"若生学校制度担当課長","answer":"さらに地域別で、住民の方々に、これは学区域が変わるというようなこともありますので、そういった地域に特化した情報をお伝えできるような説明会を、６月以降になるかと思うのですが実施していく。","voiceIndex":84,"id":"exchange-031"},{"speaker":"渡部委員","kind":"確認","question":"なぜわかりづらいのかわかりました。小学校と中学校を一緒に説明するからです。全く制度が違うのですよね。今のつる委員の最初の確認のところでやっと気づきました。今すごくすっきりしました。これはやはり小学校は小学校でプリントをつくってやる。というのは、学区域の変更というのは基本的に中学校区だけじゃないですか。中学校はどこを選んでもいいのですから。回答は要らないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実に本当に複雑で、ちょっと普通の頭では考えにくい。該当する方がアプリなどで簡単に自分の子どもがどこを選べるのかというのは、そういうのは今の技術でできると思いますけれども、地域の方も含めて、やはり自分たちの住んでいる地域がどう変わっていくのかというあたりはきちんとご説明をしていただきたいと思いますので、その点をよろしくお願いいたします。","respondent":"若生学校制度担当課長","answer":"確かに制度のほうを、地域も含めまして丁寧に説明していくということは必要だと認識しています。","voiceIndex":87,"id":"exchange-033"}]},{"id":"topic-04","title":"の２、その他を議題に供します。 初めに、(1)所管質問","agenda":"の２、その他を議題に供します。 初めに、(1)所管質問","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"教員の多忙化解消へ、土日祝日を含めた在校時間を把握することという質問があるのですが、それに対してのご答弁のところで３点もう一度お伺いしたいのですが、出退勤システムで管理をしているという答弁だったので、この出退勤システムの管理の状況がどのようになっているのか教えていただきたいのが１点です。","respondent":"熊谷指導課長","answer":"今回開発した在校時間統計システムにより、教育委員会としましては、教職員の在校時間をこれまで以上に適切に把握し、様々な業務改善を進めていくための基礎とするとともに、学校管理職に教職員の在校時間を確認する手段を提供することで。","voiceIndex":92,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問","question":"打刻してもエラーになる。だから何も残らないわけですね。実際においては仕事が存在するので学校にいるのだと思うのです。その辺の考え方というか、そこをどう改善していったらいいのかというのが悩みだと思うのですが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"都立高校もやはり土日の勤務、例えば部活動等については出退勤システムでかなりできている。これも本区のものを参考にして入れたシステムなのですが、部活動に関して、それから勤務を命じたもの、例えば土日の学校説明会については、これは出退勤システムに勤務として登録。","voiceIndex":95,"id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"そういうことがあるのかなという印象を持ちながら伺っていたのが一つで、現状どうなのかというところを聞きたいのと、それから、やはりそういうところは、今働き方改革みたいなところもある中で、風呂敷残業みたいな表現が昔ありましたけれども、職場で残業するのではなくて家に持ち帰るなりして、出退勤にはなかなかつけないよう仕事の解消をする。","respondent":"熊谷指導課長","answer":"勤務時間のほとんどを仕事で使える方もいれば、なかなか家のこともあって学校に来て業務することができないという方もいらっしゃると思いますので、そういったことも含めてしっかり把握していくことが重要だと思っています。","voiceIndex":97,"id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"把握をすることが重要だとおっしゃって、そのとおりだと思います。したがってここではもうこんな時間になってしまったので、また改めて質問させていただきたいと思っていますけれども、教員を増やすということを抜きにどれだけコーディネーターを採用しても、やはり基本的なところというのは解消されていかないと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-037"}]},{"id":"topic-05","title":"委員長報告","agenda":"委員長報告","exchanges":[{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"１年間、このメンバーでいろいろ活発な討論等もありまして、いろいろ勉強させていただきました。この１年間無事に、先ほど正副でまとめたレポートもできましたので、実りある１年間だったと思います。いろいろ感謝を申し上げながら、副委員長として最後のご挨拶とさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4966#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":45685,"voices":109}},{"id":"r01-20190226-5","meetingId":"r01-cm02","date":"2019年2月26日","dateIso":"2019-02-26","committee":"総務委員会","time":"午前１０時００分～午後 ０時２１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"業務改善推進プロジェクトチームの検討状況","agenda":"業務改善推進プロジェクトチームの検討状況","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"会議を短くするというご説明が先ほどあり、２月から運用されているということですが、私もこの１２年間議員をやっている中で、予算特別委員会や決算特別委員会で会議が長いのではないかという話も何か出たような気がするのですけれども、何でこの時期に、今さらという言い方はおかしいですけれども、品川区は昔から会議を短くするための会議をとよく言われていた時代がありましたが、その時代はとうの昔で。","respondent":"柏原企画調整課長","answer":"皆さんの共通認識として、それぞれの所管で、会議のやり方を工夫してきてはいたのですけれども、これはやはり全庁としてルール化してやらなければいけないだろうというのがありまして、タイミングとしてなぜ今さらというような印象もあるのかもしれないですが、我々とすると。","voiceIndex":5,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"会議については、会議が長いよねというのは、どちらかというと、職員の方々が会議に参加したときに、若い職員はそういう感覚でいる可能性もあるし、問題意識を持ってもらいたかったというのがあって、要は、このＰＴが設置されたからこそそういう話が出てきたということで、もし設置されていなかったら、国の働き方改革とかがあって、「しながわ～く」の一環として、ＰＴを設置してやってみようといって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区働き方改革における業務改善推進プロジェクトチームの検討状況についてご説明がありましたが、何のために働き方改革をしているのかという目的や目標がご説明ではよくわからなかったのです。資料には、業務改善課題や風土・意識・慣習などに起因する課題などとありますが、これらを何のために、また目標をどこに置き働き方改革として位置づけているのか、そこをご説明いただきたいと思います。","respondent":"柏原企画調整課長","answer":"その一環ということで、業務改善を行っているのですけれども、区職員の働き方の意識や働き方を変えることによって、例えば、超過勤務の削減であったり、業務改善によってできた時間を、違うところにパワーを注ぐとか、そういったところにつながるようにということで。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"いわゆるワーク・ライフ・バランスと長く言われておりますけれども、なかなか実現に至っていないだけに、目標や目的を１つの指標として定めて進めていくということが必要だと思うのです。例えば、超過勤務、有給取得率、生理休暇、男性の育児休暇の取得など、そういうのを物差しとしてはかるという考えがあるのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"ただ、今回業務改善というところで取り組みましたのは、それをする上で、例えば、重複した仕事があったのかとか、これはやらなくても済む仕事ではないのか、もっと違うサービスができるのではないかなど、そうした視点で仕事そのものに対する改善といいますか。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"そういう意味では、こういう取り組みが進められること自体は大事なことだとは思いますけれども、率直に言って職員の風通しというのはどうなのですか。","respondent":"柏原企画調整課長","answer":"そういう意味では、風通しということについてのお答えになっているかわからないですけれども、全庁的な風潮といいますか、流れをつくるのにはいいきっかけになっているという感じがしています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"それなりの成果が出てきているのかどうか、要は働き方改革として超過勤務の改善、重複した仕事を見直す、仕事の中身を改善するとか、資料には会議効率化の基本ルールというのが大きく出ていて、他にも引継ぎ、スクラップ・アンド・ビルドというのも出ているのですが、実際に成果はこれで出るのでしょうか気になっているので、教えてください。","respondent":"柏原企画調整課長","answer":"これは予算審議にもちょっとかかわってしまうのですが、例えば、平成３１年度予算で会議スペースの整備、フリーアドレスのモデル実施など、いろいろＩＴ関係でできるようなこととかをご提案していますので、こういったところによっても。","voiceIndex":16,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"これは各部から代表が集まって進めていったら、それぞれの部の業務内容が違うのですから、深掘り云々というお話があったのか、効率的な業務をやるなら、各部で徹底的に意見を出し合って、そこで議論していかなければ、これはちょっとおかしいのではないかと思ったのです。なぜなら、各部でそれぞれ働いている人たちが３０人、５０人いれば、その方たちそれぞれがいろいろなご意見を持っている。","respondent":"柏原企画調整課長","answer":"もちろん最初のブレインストーミングのときには、そういった細かい話も出ていたようですけれども、全庁的なルール、まずベースになっている部分をつくりましょうというのが今回の業務改善チームの主眼といいますか、そういう趣旨で立ち上げていますので、それぞれの部署で。","voiceIndex":18,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"これからどういうふうに進んでいくのか、業務改善を含めて、我々も見ていくしかないのですけれども、それぞれ違った部の人がいろいろな考え方、ここの部はこういうふうに進まなければいけない、この部はこうだという意見が出てしまうとかみ合わないようなことも多いのではないかという気がして、ちょっと質問させていただきました。こういうふうに統括リーダーのほか各部代表１６名が集まっている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"スケジュールというのか、今後のことなのですけれども、２月から会議効率化の基本ルールの運用を開始したということでよろしいですか。２月から運用を開始したら、今度はその結果を点検をする時期が来ると思うのです。それをやらないと意味がないと思うのですが、このプロジェクトチーム自体は実施期間として、とりあえずこの３月で終わるということなのでしょうか。会議の時間が長過ぎるのはないかと。","respondent":"柏原企画調整課長","answer":"こういったことで進めていきたいということを、先日、区長も含め、報告をする場を設けましたがその場でも点検に対する考え方だとか、スケジュール感はという指摘がございまして、その部分についてはこれからの検討というところでした。","voiceIndex":21,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"今それはまだ全然考えられていないのでしょうか。そこをもう一度伺いたいと思います。どれくらいやったところで１回検証する、検証も１回でいいわけではないと思います。自分でも経験がありますけれども、会議を短く、議論しやすいように事前に資料送付というのは別のところに必ず大きな負荷が発生しますので、その辺をどのように考えておられるかという点を確認したいと思います。これは要望です。","respondent":"柏原企画調整課長","answer":"そういった中で、今お話がありましたけれども、会議の準備、今申し上げた資料の関係だとか、そういったところもろもろについて１回検証するタイミングかと思っています。","voiceIndex":23,"id":"exchange-010"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１つだけ、区民への周知というところをお伺いしたいのですが、先ほど、今回は会議のルール化がメインということで取り上げられていて、庁舎内の会議室に職員向けにということだと思いますが、ポスターが貼られるとありますけれども、区民に向けて品川区役所がこうやって働き方改革に取り組んでいるというところをどのように周知されていくのか、教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"今のところ大々的な形で何か打ち出すということではないのですけれども、区の働き方改革ということで、こういうことを実行していますという周知につきましては、どういったやり方が効果的かというのはありますけれども、何らかの形での周知は検討していきたいと思います。","voiceIndex":25,"id":"exchange-011"}]},{"id":"topic-02","title":"平成３１年度都区財政調整","agenda":"平成３１年度都区財政調整","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"確認だけなのですけれども、３ページにある新規算定等の主な項目で、新規算定が１７項目、算定改善等項目が２９項目あるとおっしゃっていたのですけれども、新規算定というのは必要性がある中で、これは品川区の事業にしっかり盛り込んでいったと理解できるのですけれども、改善というと、今まで多過ぎたからちょっと少なくしてくださいというイメージで、東京都からの交付金ですから。","respondent":"品川財政課長","answer":"これが過去と比べて市場価格等が上がっておりますので、こういった単価の改善等を改善項目では行っているというものです。","voiceIndex":32,"id":"exchange-012"},{"speaker":"いながわ委員","kind":"確認","question":"だから、それはプラスに考えた改善という意味でいいのかということ、あと街路灯に関しても、プラスに考えていいことなのかどうなのか、要するに、算定の中で、認証保育所運営費等事業費とかを見ると、今後の子どもの増減を考えると、これは増やすべきなのか、減らすべきなのか、議論があると思うのです。プラスに考えていいものなのかどうなのかというのをちょっと確認したいです。","respondent":"品川財政課長","answer":"基本的に考えれば、工事単価を上げて、工事費用も今までの算定費用よりも増えたという形になりますので、各区でやる基準財政需要額というものが、この見直しによって上がるです。","voiceIndex":34,"id":"exchange-013"},{"speaker":"いながわ委員","kind":"質問","question":"質問が全く変わるのですけれども、こういう質問をしていいかどうかわからないのですが、これは東京都からの交付金ということで、２３区が平等にという話があるのですけれども、正直な話、この場所で私がこういう質問をしてはいけないのかもしれないけれども、財調があるおかげで本来品川区はこういうことをやりたいのだけれども、財調はいろいろ算定とかが厳しく行われるわけではないですか。","respondent":"品川財政課長","answer":"原則的な考え方とすれば、基準の収入額と、それを超える需要額があって、その超えた分については財調で賄おうという考え方になると思います。品川区の場合、何かをやったことによって、大きく財調に影響してくるという事業は、今私が考えている中ではちょっと思い浮かびません。","voiceIndex":36,"id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問","question":"例えば、今回ふるさと納税による減収は１８億円だという話をちらっと聞いたのですけれども、要するに、品川区において１８億円が控除されてしまうわけですから、１８億円マイナスと表現すると、それを取り戻すために品川区もふるさと納税をやっていて、水辺千本桜計画とか、いろいろやられていますけれども、もっと大胆なことをやったときに、それを算定に入れ込んでいったら、大胆なことをやることによって。","respondent":"品川財政課長","answer":"ふるさと納税については、本区において今年度１８億円ぐらい減の見込みということで、これは国の制度ですが、他の自治体と比べれば、なかなか厳しいところはある中で、いろいろと努力して税外収入、ふるさと納税を税外収入と言ってはいけないのですけれども。","voiceIndex":38,"id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"今質問があったと思うのですが、今回の新規算定等の主な項目で、項目は出ているのですけれども、金額をあえて書かないというのは、別に項目だけ見てもらえればいいということなのでしょうか。東京都は出しております。この資料に書いておいていただければ、我々がここで議論するときもすごく参考になると思うのですが、その辺についてご見解を教えてください。","respondent":"品川財政課長","answer":"金額の面に関しては、算定項目がかなり多いところもありまして、どこまで書いていくかというところもありますし、いろいろ入れていくと、資料の中でつじつま合わせとか、そういったところでいろいろありますので。","voiceIndex":40,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"細かくはあれですけれども、東京都もちゃんと発表しているわけですから、区立施設定期点検調査費の需要額の増減がこういうふうになっているとか、ここは増額して、ここは減額したとかというのは大まかに出ていると思うのです。だから、金額があれば我々も、これが増えたのだな、これがマイナスになったのだなというのがわかりやすいので、できれば検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"３ページにあります新規算定等の主な項目ということで、基本的にプラスされるというご説明でしたけれども、逆に今回新たになくなったものというのはあるのか、あれば具体的に何か伺いたいと思います。","respondent":"品川財政課長","answer":"当然都のほうは金額を少しでも減らしたいという考えがあるので、都から挙げてきている項目として、今回需要額をマイナスで算定されたという部分もあります。一例としましては、勤労福祉会館管理運営費などが減の項目となっています。","voiceIndex":43,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"この資料をつくる際に、減となったものとして、勤労福祉会館管理運営費を例として挙げられましたけれども、東京都が主張しているものを全部書けとは言いませんので、結果として何が減になるのかは資料に載せていただきたいと要望したいと思います。もう一点、１ページ目の基準財政需要額についてです。","respondent":"品川財政課長","answer":"それに対して区としてどうかというところですけれども、財調の標準の数字がいろいろ出ています。例えば、学校数だとか、保育園の数だとかあるのですけれども、品川区は、基本的には標準にほぼ近いぐらいの数字で算定数字としては出てあります。","voiceIndex":45,"id":"exchange-019"},{"speaker":"中塚委員","kind":"意見","question":"大体品川区と同じということですけれども、新しい人口統計でも品川区の人口が今度４０万人をまた大きく超えるという動きがあって、２３区も自治体によって多少違いはあるものの、今後増える見込みです。２３区が同じような割合で増えれば、特別変わらないとは思うのですけれども、品川区だけ特出して人口が増えたとき、どのような影響があるのか、ご説明いただけますか。","respondent":"品川財政課長","answer":"ただ、これは仮定の話しですので、実際の数字としてどうかというところは今現在お話しすることはできませんが、人口が増えていけば、需要額も増えていくという計算式になっております。","voiceIndex":47,"id":"exchange-020"}]},{"id":"topic-03","title":"第２３回品川区世論調査","agenda":"第２３回品川区世論調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１点だけ、調査対象なのですけれども、満２０歳からということでこの間ずっと続けておりますが、１８歳選挙権が始まり、成人年齢の引き下げもある中で、経年変化や定住性、重点施策はよくわかるのですけれども、今後調査対象を１８歳に広げていくという方向性はあるのか、その点だけ伺いたいと思います。","respondent":"中元広報広聴課長","answer":"それで私ども品川区といたしましても、今後２年後に向けましては、他自治体の状況等もありますので、経年変化というところでは少し意味合いが変わってしまいますが、見直しを検討してまいりたいと考えています。","voiceIndex":53,"id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問","question":"世論調査をするに際して、調査項目はだれが設定したのかというのが１点と、選定した調査項目に関する質問はだれがつくったのか教えてください。","respondent":"中元広報広聴課長","answer":"その中でお申し出があった課の方を個別にヒアリングさせていただき、ヒアリングの際には調査会社の職員、専門家も一緒に同席し、そういう意図であれば、こういう項目がいいのではないでしょうかという調整もその中でやりながら、ただ、全体的なボリュームに限界がありますので。","voiceIndex":55,"id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問・要望","question":"質問項目もその場所で、株式会社タイム・エージェントの職員と一緒につくっているということだと思うのですが、調査の結果を見てしまうとあれなのですが、例えば質問の中で、１０ページにオリンピック・パラリンピックについてということで、競技会場を観客で満員にするために効果的だと思う方法という問いがあって、９割近くが競技会場周辺でのＰＲイベントの開催と答えていて。","respondent":"中元広報広聴課長","answer":"３点ご質問をいただきました。１０ページのオリンピック・パラリンピックについての質問項目ですが、こちらの効果的だと思う方法というのは、実は今回初めて実施した質問でございまして、オリンピック・パラリンピック準備課からいただいた質問をそのまま出させていただきました。","voiceIndex":57,"id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問","question":"とにかくこういったわかりやすい報告書があるので、こういうのを見てまた興味がわいてくる部分もあると思うので、品川区がポスティングをやると苦情が来るというのは、政治家がやると大体来ますけれども、私は初めて聞いたのであれなのですけれども、紙の無駄とかいろいろありますが、とは言いながらも、紙媒体で見るというのは大切だし、とにかく４,０００部というか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"２年ごとにやっている世論調査の手法について、今後どういう形でやっていくのかということもご検討されているのかとも思いますけれども、約７０％の回答率というのが、この数年間７０％ぐらいで一定なのか、それとも下がってきてしまっているのか、それとこの７０％ぐらいを維持するのであれば、例えば、対象を広げていく、１,５００人ですけれども、回答をたくさん求めるためには。","respondent":"中元広報広聴課長","answer":"１８歳以上を対象にするというのはまだ決まったことではございません。これからの検討でその方向性も視野に入れて考えているということで、回収方法とあわせて検討してまいりたいです。","voiceIndex":60,"id":"exchange-025"}]},{"id":"topic-04","title":"男女共同参画のための品川区行動計画第５次等の策定","agenda":"男女共同参画のための品川区行動計画第５次等の策定","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"さっきの寄せられた意見と区の考え方の２番に関して、ご意見を要望として承ってしまっているようなのですが、多分課長から所管の課長にこういう話があるからというのが行っているのかどうなのかというのだけ、確認させてください。","respondent":"島袋人権啓発課長","answer":"ですので、４月からこの計画を実施いたしますので、その中で関係各課といろいろな啓発を進めていきたいと考えているところですし、男女共同参画センターで実施している講座におきましても、思い込みをなくす、偏見をなくす、アンコンシャス・バイアスというものなのですけれども。","voiceIndex":67,"id":"exchange-026"},{"speaker":"中塚委員","kind":"提案","question":"この間、区議会を見ていましても、さまざまな会派からセクシャル・マイノリティについての質問や提案がありますけれども、同性パートナーシップ制度について、具体的な文言はこの中に書き込まれておりませんが、「マイセルフ品川プラン～誰もが自分らしく～」の中に、どのように同性パートナーシップ制度が位置づけられているのか、その趣旨が盛り込まれているのか、その点を伺いたいと思うのと。","respondent":"島袋人権啓発課長","answer":"アンケート等をとりますと、自身の性自認や性的指向に関して悩まれている方に関して、世の中に知れてしまうのではないかとか、とても心の問題に入っていきますので、なかなか難しい問題であることは認識していますが、この計画が実際４月以降に動き出したとき。","voiceIndex":69,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"私も６月の一般質問で、性的マイノリティへの理解促進ということで、次の計画の中に位置づけられることを求めましたし、ここが一番ふさわしいと思いましたので、それがきちんと位置づけられたことは大変歓迎をしております。何かお考えがあれば、後で伺いたいと思います。その辺、何かお考えがあれば、教えてください。","respondent":"島袋人権啓発課長","answer":"今年度実施いたしました「普通ってなに～違うことを認め合う」は、大変好評をいただきまして、こちらは次年度以降も継続していくテーマだと思っているところです。映画に関しましては、１００名を超える方々に集まっていただけました。","voiceIndex":71,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"時間設定ですけれども、よくわかります。夜だったおかげで私たちも参加できたかなとは思うのですけれども、一方で、昼間でないと行かれないという方たちもいらっしゃると思うので、回数を重ねられ、今後拡大していく場合は、夜の講座と昼の講座としたらどうか、検討していただきたいと思います。もし計画されているようなところがあれば、教えてください。","respondent":"島袋人権啓発課長","answer":"デートＤＶと言われております、要するに、交際相手、元恋人からのＤＶ相談、あるいはこれはそういうことなのかなという若い高校生や短大、大学の方たちに講座を出前で行うものも計画しておりますので。","voiceIndex":73,"id":"exchange-029"},{"speaker":"吉田委員","kind":"提案","question":"最後に、去年１２月の人権啓発週間のときに、配偶者の暴力のことをパネルで掲示してほしいということで、品川・生活者ネットワークが提案したパネルが、きゅりあんのイベントホールに展示されたことは大変評価したのですが、残念だったのは、パネル全部ではなかったのです。あのとき何でああいう使い方だったのかというご答弁がいただければ、それと今後のことについてもお考えをお聞かせください。","respondent":"島袋人権啓発課長","answer":"今年度は、１１月１日号の広報しながわに、配偶者暴力の特集号を掲載させていただきましたので、こちらも活用しながら、またいろいろと啓発を進めてまいりたいと思っているところです。","voiceIndex":75,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"会場の制約とかがあると思いますけれども、当事者にとっては命にかかわる大変な問題ですので、ぜひその辺のことを工夫しながらやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-031"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"そういう中で当事者の方の気持ちをどうやって受けとめていくのかというところも日々お話を伺っているところであります。何かご見解がありましたら、お聞かせください。より一層細やかな配慮が必要かなと思うのですが、何かもう一文加えて、すぐにわかるように、ここはちょっともう少しご配慮いただけないかと思うのですが、このような工夫というのが具体的にできるのかどうかお伺いしたいと思います。","respondent":"島袋人権啓発課長","answer":"「マイセルフ品川プラン」と検索してというような検索のマークが必要だとは思っているところなので、検討して工夫してまいりたいと思っているところです。","voiceIndex":79,"id":"exchange-032"},{"speaker":"新妻副委員長","kind":"意見","question":"ホームページに関しては、具体的に、例えば、「マイセルフ品川プラン」で検索をとか、そうすると、ＰＤＦがあってそこにつながっていくとか、そういうこともできるかと思いますので、ぜひ工夫をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-033"}]},{"id":"topic-05","title":"受動喫煙対策強化に伴う総合庁舎屋内の禁煙化","agenda":"受動喫煙対策強化に伴う総合庁舎屋内の禁煙化","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"しかしながら、パーテーションを立てるだけ、そうすると、さっきのパブリックコメントの意見にありましたけれども、煙が嫌だと言う人はどうするのですかとなると、今度はもう庁舎内どころか、庁舎外のやつも撤去しようという話にいずれなる時代が、来てもらいたくはないですけれども、そういう状況にどんどん追いやられるということが、それこそこれは人権的にどうなのですかという話になってしまうので。","respondent":"立木経理課長","answer":"実は庁舎の敷地の中に、屋根つきの建物を新たに設置することが難しい状況になっている中で、そのためにパーテーションで囲い、煙を少し遮る形にしておりまして、こちらの経費と設置場所、それから広報という形をとらせていただきました。","voiceIndex":86,"id":"exchange-034"},{"speaker":"いながわ委員","kind":"意見","question":"屋根つきができないというのは、容積率とかいろいろな問題で、構造物はだめとか、それはいろいろ考えていただいて、できる限り吸う人間もいい環境で吸えるというのは大切なことではないかと思いますので、それはしっかりやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-035"},{"speaker":"須貝委員","kind":"質問","question":"我々みたいに吸わない人は、そうですか、決まったのですか、ではそうしてくださいとなるけれども、区の職員の作業効率のことも考えると配慮しなければいけない。来庁者のことも考えなければいけない。ＪＴでもさまざまな研究がされていると思いますので、そういう会社に支援をしてもらうなり何かして、実験的に別の対応策も考えてやっていくべきでないかと私は思うのですが、どうでしょうか。","respondent":"立木経理課長","answer":"そういった中で、まずは屋外喫煙所を用意するということでやらせていただいております。実際ご利用の方のお声を聞きながら、また何か工夫できないだろうかというのは、いろいろ検討させていただきたいと考えています。","voiceIndex":90,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"その次のときにはいろいろな方が外部からいらっしゃる建物については、必ずどこかに吸う場所を求められるので、本当は喫煙場所がちゃんとあったほうがいいのではないかと考えが変わったのです。そこに灰皿が置いてあったりするではないですか。いきなりやめてしまうということが、近隣にどういう影響を及ぼすか注視していただいて、今後の対策をぜひ考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-037"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。今さまざま出た中で、私の会派としても、これはぜひ進めていただきたいと思うのですけれども、４８０万円というこの予算の根拠を教えていただきたいのです。東京都の補助金１０分の１０で、４８０万円、これは平成３０年度の予算ということなのか、なぜ４８０万円なのかというところをお聞かせください。","respondent":"立木経理課長","answer":"予算の年度ですが、これは平成３０年度の予算で工事を行いまして、補助金も平成３０年度ということで入ってまいります。工事費の４８０万円ですけれども、今１カ所パーテーションを設置いたしまして、設置する場所が資料の1)と2)の２カ所になります。","voiceIndex":96,"id":"exchange-038"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。４８０万円しか申請ができないのか、かかる費用はもうちょっと上乗せして東京都に申請ができるのかというところをお伺いしたいのです。においは、風向きによって、どうしたってにおってしまいますので、そういう意味では今回この３カ所を整備するのであれば、多少予算がかかったとしても、中途半端ではなくて、ちゃんとしたものをつくっていただきたいと要望いたします。","respondent":"立木経理課長","answer":"ＪＴとの連携は今のところしておりませんので、今後アドバイス等をもらえるようなところがあれば、ぜひいただいてまいりたいと考えています。案内に関しましては、総合案内のほうでももちろんしっかりするようにいたします。","voiceIndex":98,"id":"exchange-039"}]},{"id":"topic-06","title":"その他を議題とします。 まず、(1)議会閉会中継続審査調査事項","agenda":"その他を議題とします。 まず、(1)議会閉会中継続審査調査事項","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"直ちに倒壊しないということは、しばらくすると倒壊するということですか。それと、専門の学者のお墨つきがあるならわかります。ただそう言っている、調べたら、こうだと。私も倒壊はないとは思いますけれども、例えば、亀裂が入ったとか、いろいろな問題が出てくると、区庁舎は災害対策本部になるわけですから、それに対して非常に心配するところなのですけれども、裏づけというのはちゃんとあるのですか。","respondent":"立木経理課長","answer":"震度７程度の地震で直ちに倒壊しないという部分ですが、建物が倒れたり、崩れたりはしませんと確認されてあります。確かに壊れる部分も当然出てくるかもしれないですけれども、命の危険があるような倒れ方、崩れ方はしませんということで確認がとれているです。","voiceIndex":112,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"１点だけ、先ほどこれからも引き続き対応を求めていくとおっしゃったのですけれども、対応というのは具体的にどういうことでしょうか。区は、直接的な契約ではないので、施工会社がそれを選んだということだと思うのですけれども、区として直接ＫＹＢ社にどういう対応を求めていくのか、またそういうことが可能なのか教えてください。","respondent":"立木経理課長","answer":"しっかりした説明と謝罪、あと契約に沿ったものが使われていないというところで、交換を求めていくという対応を、直接、もちろん施工会社も通して、両面で今行っているところです。","voiceIndex":114,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2132#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":42326,"voices":118}},{"id":"r01-20190227-14","meetingId":"r01-cm02","date":"2019年2月27日","dateIso":"2019-02-27","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時２８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３１年請願第８号 都営住宅跡は特養ホームなど区民の願い実現の活用を求める請願","agenda":"平成３１年請願第８号 都営住宅跡は特養ホームなど区民の願い実現の活用を求める請願","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"ありがとうございました。地域の方からさまざまな声というものが届いている中で、この話というものがあったことも事実です。今回、跡地の活用を求める請願が提出されましたが、どうしようもできないところはどうしようもできないですが、地域からの声もありますので、区のほうとしても、すでにある程度動いていくということは見えましたので、それで承知いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"確認","question":"多分活用意向の調査なので、まず区にどうしますかと確認して、その後の協議の中で、都としてはこのような考えもあるのだけれどもというようになっていくのではないかと思うので、まず区の考えをお聞かせください。","respondent":"柏原企画調整課長","answer":"ここは都有地で都が持っているということになります。都のほうで、まず自分たちがどのように使うのか、活用方法というものを内部で検討するということがまず第１順位といいますか、最初になってくるところです。","voiceIndex":10,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"都のほうから、これに対してどうだろうかということが来ているということで、区のほうとしては今検討しているということですけれども、この回答として区が取得します、買い取りますということを積極的に言えるのか、言えるか言えないかでいえば、言えるということでよろしいでしょうか。","respondent":"柏原企画調整課長","answer":"そこに、例えば取得の意向であったりというものをつけるとすると、基本的には照会の文書に書く欄がありませんので、もしそのようなことを言うのであれば、別に書面をつけたりなど、そのような形でできるかと思いますけれども、今来ている照会は、施設の用途といいますか。","voiceIndex":12,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、都から来ている活用意向の調査は、どのような施設がいいかということで照会が来ているが、どのような形で返すかは別として、区としては買い取りたいという意向を示すことはできる。それを区が、ではこのような施設がいいですというように答えてしまうと、民間事業者に低廉な価格で貸し付ける仕組みに則って、区と都がいいと思った施設で進んでしまうということなのでしょうか。","respondent":"柏原企画調整課長","answer":"ただ、今回の照会に回答することによって、一義的にはそのような形で検討が、東京都の中で進むというところは想定できると思います。","voiceIndex":14,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、こういった３,０００m2を超える土地ですので、そうした土地を、この請願にもありますけれども、特養ホームなど区民の願い実現の活用を求めるということは大いにわかると思いますし、区のほうとしても、なかなか出てこない土地、大きい土地が出てこない都心部ということを考えれば、ぜひ積極的に買い取っていただいて、区民の願い実現の要望、要は地域の声を聞いて区民参加で整備を行い。","respondent":"柏原企画調整課長","answer":"ただ、今の段階では都有地で、こういった形で都から照会が来ているということで、それに対してどう回答といいますか、反応すべきかというところを検討しているです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"区もそうですし、区民の皆さんもやはりこの都営住宅跡地がどうなるのか、そしてこれだけの大きな土地であるほか周りが公園、学校というところで、いい環境の土地ですので、興味、関心があるということは同じだと思うのですけれども、ぜひ区として積極的に取得し活用する方向で、そのような姿勢で臨んでほしいと思うのです。それとも、あの土地自体を活用できないということなのでしょうか。","respondent":"柏原企画調整課長","answer":"区としてというよりは、土地そのものがそのスキーム、地域の福祉インフラ整備による活用も含めて、都は活用できない可能性もあるということを言っているということです。","voiceIndex":18,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"請願審査ですので、請願内容について確認をします。この移管に関する照会が、品川区にあったと思いますが、この状況をひとつ教えていただきたいと思います。どのような状況で現在に至るのかということを教えてください。これまで品川区の中で東京都の土地を区が買い取った事例があるのかどうか、また、その際はどのような手法で区は買い取ることができたのかということを教えていただきたいと思います。","respondent":"森住宅課長、柏原企画調整課長","answer":"ただ、昭和３０年代につくられた団地で、耐震性が不足する一方、耐震改修を予定していないということで、都のほうでも早急に対応を検討する必要があるというお話でした。ですので、その時々によって東京都の打ち出し方や相対する部局が違ったりするのですけれども、そういった事例があって、そのときは個別の対応ということで、それ以外のスキームがなかったということもありまして。","voiceIndex":23,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。ケース・バイ・ケースというか、土地の状況によってその買い取りの手法があるということがわかりました。それで、ここの地域、私も昨年ここの都営住宅が廃止になるということで、地元地域の方からは、建物がなくなるということだから、その次は何かできるのだよねという期待のお声等々も伺っているところであります。","respondent":"溝口公園課長","answer":"来年度以降、仮設園舎の設計等に入っていくところではありますが、できる限り公園利用者にご迷惑をおかけしないような形で、今元芝アパートのほうに仮設園舎を寄せる計画を進めているところです。","voiceIndex":26,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。そのような状況もあるのかということがわかりました。ただ、まだ東京都が手放さないということで、今回東京都が活用するという形で、照会が来ているところですので、もう一段区のお考えを再度また確認させていただきたいのですが、今回の照会に対する回答とともに、区は取得の希望があるということを、回答されるのかどうか、そのお考えの方向性をお聞かせいただきたいと思います。","respondent":"柏原企画調整課長","answer":"ですので、具体的に回答という形で出せるかどうかということはあるのですけれども、そういった思いというものは持ち続けることになるですが、先ほど来申し上げているとおり、ちょっと保険ではないのですけれども。","voiceIndex":28,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"大変活用ができる土地であるというふうに、区も認識があるということですので、都とのやりとりをしっかりしていただく中で、区が活用できる方向を見出していただきたいと思いますのと、もう１点が、今回の請願では特養ホームなどということでありますけれども、地元のニーズをしっかり地元の方からお聞きいただいて、区が活用できる方法をぜひ探っていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"やはり品川区ができるのだから、そしてやろうとしていることに関して、このような約１００坪もあるいい土地に都が自分の力で建物を建てられないなら、私は区に任せるべきだと思う。かといって都の土地ですから、勝手には言えませんけれども、私は照会に対してこのような施設がいいということを逆に書かなくてもいいのではないかと思いますので、かえって我々にやらせてくれという一言だけでいいと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで質問ですけれども、この資料の説明なのですが、照会の内容は２つあって、活用意向の有無があるのかということと、都が民間に貸すという事業の中で、どのような施設にしたらいいですかという２つ聞かれているというのですけれども、区に対して活用意向の有無を聞くということはどういうことなのか、少し矛盾していると思うのですが、その辺少し説明していただきたいということと。","respondent":"柏原企画調整課長","answer":"それ以外のものは該当にならないと聞いてありますので、公営住宅については、住宅関係は該当にはならないというふうに聞いてあります。それから回答期限なのですが、この照会文書は、１月の終わりに来ているのですけれども、今月末までということで、もう間がないところです。","voiceIndex":34,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"東京都がそれらの活用はまだ未定だと言っているからこそ、いや、これは区として取得も含めた強い希望があるのですということはやはり言っていくべきだし、そうしたことで東京都のほうの活用方針も、では区に譲るか、売却しようかという話になるかもしれませんので、私はそういった取得の希望を、やはり区としてしっかり出してほしいと思うのです。ぜひやっていただきたいのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"再三に渡り申しわけないのですが、東京都が今持っていて、まず１つの活用の手法ということで、このスキームで照会が来ておりますので、それに対してどう答えるべきなのかというところがありまして、そこの検討とあわせて、区としてそこの土地に関する今後の考え方といいますか。","voiceIndex":36,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから地元である区の意向として、ここに書かれているような特養や、あるいはこの間議論されておりますけれども、これから将来人口推計でもまだまだ若年人口が増えていくわけですから、保育園ということもあるでしょうし、障害者の施設も足りていないということは区自身も認めている中で、この土地について区も関心を持っているということですが、その活用。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-014"},{"speaker":"渡部委員","kind":"質問","question":"今、説明を聞かせていただいて、ある程度の方向性は見えている中で、都のほうの考え方もありましょうし、今後まだまだ話を詰めていただかなければならないところもあるのかという部分で、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"},{"speaker":"新妻委員","kind":"確認","question":"公明党も継続でお願いをいたします。さまざまご説明をいただく中で、区の意向もわかりました。活用したいという方向性も確認ができましたけれども、東京都がまだ実際に使えるかどうかわからないということを注意事項でも言われている中でありますので、しっかり今後都とやりとりをしていただいた上でのご判断が必要かと思いますので、継続でお願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして採択を主張したいと思うのですけれども、やはり私も住民の皆さんに直接伺ったり、また、解体説明会等でも本当に多くの皆さんから、この土地がどうなるのか、そしてやはり区民の願いに沿ったものに活用してほしいという声が本当に多く寄せられましたので、東京都との協議もあるかもしれませんが、ぜひここを区が積極的な姿勢で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"我が会派といたしましては、継続にします。先ほどの説明にもありましたが、都からの照会があり、そして都に対する回答を考えている段階であるということでありました。この跡地については、区としても今後活用していく方向であることも説明があり、また私たちの会派でも、地域住民から今後どうなるのかという声も伺っていることから、この請願第８号に関しましては継続にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-018"},{"speaker":"須貝委員","kind":"意見","question":"私も、今区のほうがいろいろ対応を迷っているということで、今の段階では継続がいいのかなと。この請願の趣旨はごもっともだと思いますし、区のほうとしても同様の考え方をお持ちだと思うので、私はごもっともだと思います。それだけ、意見として述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"5)の重い知的障害を持った子どもを含む近隣住民には命の危険があるというように訴えておられるわけなのですが、区はこういった状況を把握しているのか、その状況を伺いたいと思います。１点目です。それと、3)に都の発言が紹介されていますけれども、区は東京都に、地域住民の土地取得における、こうした声というものを具体的に伝えていなかったのでしょうか。どちらなのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"今お尋ねいただきました知的障害の方についての区の把握ですが、状況としましては、都市計画審議会が開かれる前に都市計画法第１７条に基づく公告・縦覧を行い、縦覧していただいて意見をいただくという中で、その中の１つとして、区のほうではその時点で把握をしたです。","voiceIndex":52,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"ぜひよろしくお願いしたいというところです。それで３月に大体の位置関係を決めたとここに書いています。３月に西側敷地の取得に向けた協議方針を決定とありますけれども、その方針を決定する前に、区として、こういった地域住民の土地取得における声というものをつかんでいなかったのか、あるいはつかんでいたけれども都に伝えなかったのかということをお伺いしたいので、もう一度お伺いします。","respondent":"柏原企画調整課長","answer":"ですから、この段階でまだどこになるかというところが確定できない状況もありますので、そういった部分がありますので、このタイミングでご意見をお伺いするということは、逆に混乱も起こる可能性もあるというところがありましたので。","voiceIndex":54,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"私がお伺いしたのは、その協議の方向性を区として決めたものですと。それは区として決めるでしょう。それは内部で協議せず何の考えも持たないで東京都と交渉、協議するということはあり得ないということは私もわかります。区がその協議の方向性を決める上で、その前に地域住民の土地取得における、こうした声をつかんでいたのか、つかんでいなかったのかということをお伺いしましたので、お答えください。","respondent":"柏原企画調整課長","answer":"ただ、議会もそうですけれども、地元の町会であったりとか、そういったところには、こういう方向性もあるというお話をさせていただいたことはありますけれども、今委員がおっしゃるような意味合いとして、全員の方にお話を聞くだとか。","voiceIndex":56,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう少し伺いますけれども、この都市計画審議会の中でも企画調整課長がおっしゃっていましたが、この交渉の過程の中で都や国などいろいろな関係者が入る中で、なかなか方向性が定まらない、双方の意見が一致しないということがあってかなりの時間がかかったということは事実なのですと述べておられますけれども、この東京都と品川区の意見の相違というものは。","respondent":"柏原企画調整課長","answer":"例えばその建物を建てるにしても、どういったボリュームがいいかだとか、それから避難路になる部分がありますので、そういったところをどのようにあけるのだとか、区側の話した内容と都側で言っていることがそこで調整といいますか、意見が合わなかったりであるとか、途中。","voiceIndex":58,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"望ましいゾーニングを検討する際の計画視点としてその報告書でまとめられたというものは、区が取得したほうの西側というのは身近な公園として地域住民の活用を図るゾーンとなって、逆にこの旧官舎がある東側というのですか、それは、東側敷地は奥行きが狭いため、減築による延焼遮断が効果的と書かれていて、防災機能を強化したゾーンとされたのですけれども、これがなぜ最終的にですが。","respondent":"柏原企画調整課長","answer":"それで品川区といたしましても、どちらがいいのだということは幾つかのパターンを検討しながら、先ほど申し上げた区の内部としては、方向性として西側のほうが、道路づけの関係であったりといったところ、それから東京都のほうも我々が聞いているところは。","voiceIndex":60,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、あと3)にあるように、やはり理解なしには絶対進められないと思いますので、周辺住民の意見を反映させる手続きの１つにしてほしいと思って今までも求めてきているのですけれども、そういった１つになっていくのか。それと、消防署の移転計画というものが、周辺環境に大きな変化を及ぼすと思うので、東京都が出席して消防署の件なども説明される場になるのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"こちらにつきましては、こういった陳情が出る前から個別のお問い合わせであったり、お話を聞いたりしている部分がございまして、現況区が何を考えてどのようなことを進めようとしているのかについて、必ずしもその説明が十分だったかというと。","voiceIndex":62,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"ただ時期があれかと思うのです。やはり交渉に当たって区の方針、考えというものを定めると思いますが、地域住民はじめ、区民意見を十分に聴取した上で、定められるべきだったと私は思いますし、今後、説明会で出された意見というものを踏まえて、見直すべきところは真摯に見直していく、そしてしっかりと地域住民の理解を得て進めていくという方向にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"余りにも日程が短く、私は地域住民の皆さんに少なからず迷惑をかけてしまって申しわけないと感じております。ただ品川区にとっては、このような社会福祉に関する施設を建てるわけですから、区民の皆さんが利用していただけるということで、多くの方が助かるということも事実ですから、あと地元の人に対してできるだけ配慮していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-027"},{"speaker":"新妻委員","kind":"質問・要望","question":"１点だけ、この陳情の中に近隣の住民の方の中で、特に重い知的障害を持った子どもさんがいらっしゃるご家庭があるというところがここに書かれておりますが、これまで直接区のほうにこの方から個人的にご相談があったかどうか、また、今後個々に区へご相談があった際には、丁寧な対応をしていただきたいと思うのですが、その辺について、区のお考えをお聞かせいただきたいと思います。","respondent":"柏原企画調整課長、鈴木都市計画課長","answer":"今後ですけれども、先ほど申し上げました住民説明会、住民の方々へ広く説明をするなどということとあわせて、個別のいろいろな対応といいますか、ご相談等々につきましては、こちらのほうも区として対応させていただこうと思っています。その後も担当のほうで何度か電話のやりとりの中で、ご意見いただいております。先ほどお話しさせていただきましたが、今後の３月末の説明会の中では、そうしたことも含めてしっかりと地域の声に耳を傾けていきたいです。","voiceIndex":68,"id":"exchange-028"},{"speaker":"渡部委員","kind":"質問","question":"ご説明を聞きまして、３月にこれから説明会があるということです。それについてもさまざまな議論ありまして、そのように進めていただければと思いますので、様子を見ていきたいと思います。継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-029"},{"speaker":"若林委員","kind":"質問・要望","question":"ただ、やはりこのような近隣の方にとっては、それはそれとして、もう少しより丁寧な、また寄り添ったご説明なりということがしばしば言われるわけで、そういったところは今後の３月の説明会を含めて、区の姿勢を今日は確認できましたので、引き続き近隣の皆さんとしっかりと寄り添って、ここは区全体、特に福祉政策・施策の重要な。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-030"},{"speaker":"安藤委員","kind":"提案","question":"本日結論を出すで採択を主張しますけれども、繰り返し当委員会でも述べさせていただきましたが、やはりこういった大きな公有地の活用等に当たっては、その計画段階からの住民参加というものは不可欠だということを提案させていただきました。今回このような陳情も出まして、こういった公有地活用についてはやはり大きな宿題といいますか、課題があると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-031"},{"speaker":"松永委員","kind":"意見","question":"我が会派といたしましては、継続とします。先ほどもご説明あったように、近隣住民への丁寧な説明が重要だと我が会派としても考えている中、本年３月に事業経過の説明会などを開催し、しっかりと近隣住民に対して説明するということでしたので、その経過を見据えながら考えていきたいと考えていますので、この陳情第２号に関しましては継続とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6066#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":24843,"voices":89}},{"id":"r01-20190228-18","meetingId":"r01-cm02","date":"2019年2月28日","dateIso":"2019-02-28","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ０時３６分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４号、第３２回オリンピック競技大会（２０２０／東京）における競技施設等工事において","agenda":"第４号、第３２回オリンピック競技大会（２０２０／東京）における競技施設等工事において","exchanges":[{"speaker":"南委員","kind":"質問","question":"このあたりの関係でどういうふうになったかということを一つ伺いたいのと、私どもは長時間労働、過労死という事実があった、そこはやはり重く受けとめなければいけないということで、これについてはきちんと品川区でできることというのは限界はありますけれども、しかし建築の状況を見守り。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"品川区としてどういうふうに取り組むべきかというお話、質問ですが、こちらのほうは、発注元である東京都であったり大会組織委員会が一義的にはきちんと責任を持ちルールを守って労働者の保護をしていくべきものだと認識しております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"調達コードが第３版ということで、第２版と違いがあるのであればどこかを教えていただきたいということを改めて伺いたいと思います。その辺の認識がどうなのかを伺いたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"非常に残念だという感想を、今のご答弁を聞いて思いました。調達コードについては持ち合わせてないからということで、具体的な変化については示していただけなかったのですが、私もちょっとなかなかそこまで準備してこれなかったので、そうですかと聞くしかないのかなと思うのですけれども、少なくとも労働の部分についての変化というのはあるのかないのか、その辺について確認させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"でも、調達コードそのものは公表されているわけですから、つくったところが違うからできないというふうにはならないと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"南委員","kind":"確認","question":"所管が違う。総務委員会ということですか。だって、これはオリンピックに関する調達コードなのだから、そういう点では所管が違うということはあり得ないと思うので質問させていただいたのですが。そうではないのか、ちょっとその辺確認をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、前回もお聞きしたのですけれども、多分この大成建設に対してもこの改善計画の提出が求められて、改善がされていったというところになっているのではないかと思うのですけれども、そこら辺のところが実際に改善されているかどうかというあたり、そしてまたこの品川でも実際にオリンピックの会場の建設がされているわけですが、その中での労働の実態というところは、区としては。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こういう工事をするということは東京都などと話し合いをする機会はありますので、そういうときには進捗状況を聞いたり、そういったことでの確認というのはしていますが、一つずつの労働時間がどのぐらい、超過勤務がどのぐらいだというような踏み込みというのは。","voiceIndex":19,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことからすれば、そこら辺のところの確認というのは一義的には東京都と大会組織委員会というところは理解するところですけれども、区も関係はないということではなくて、大会組織委員会としてもそこら辺のところをしっかりと共有して報告もあるべきだと思いますし、報告がなければ報告を求めて確認をしていくということも私は必要なのではないかと思うのですけれども、その点について。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区でも道路整備ですとかを行っております。それぞれの主体が責任を持ってやるべきであって、その内容について調達コードに沿っているかを区が東京都や大会組織委員会の内容についてまで踏み込むのは本旨ではございませんので、それをするつもりはございません。","voiceIndex":21,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そういうところで言えば、私は二度とこういう犠牲を出さないというところからも、オリンピックを進める側全体がこの調達コードについて関心も持ち、把握もし、そしてこの調達コードで実施されているというところの確認をする。オリンピックを進める、みんなで共有していくというのがとても大事なのではないかと思うのです。その点、改めてお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはり、このオリンピックを成功させていくというところからも、オリンピックの醸成というだけではなく、本当に持続可能な、私は調達コードで求められているものというのは本当にそのとおりだと思うのです。そして、あと１年後ということになるわけですから、今多分さまざまな建設現場で急ピッチで工事が進められているところがあると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"１点確認させていただきたいのですが、先ほど注視はしていくというお話がありましたけれども、一つひとつのことに踏み込むものではないということでした。東京都あるいは大会組織委員会がしっかり労働環境改善に向けて動いている、あるいはそういった改善する担保がきちんとされているということを大会組織委員会や東京都のほうに確認もしないということですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今委員おっしゃるような確認というのは特にしておりません。","voiceIndex":29,"id":"exchange-010"},{"speaker":"のだて委員","kind":"確認","question":"やはり、品川区にも競技場があるという中で、実際にやはりそこで長時間労働によってふたたび過労自殺が発生するという悲劇が起こったらどうするのかという問題もありますので、やはり品川区としてもしっかり改善されているかどうか、取り組まれているのかどうかというのを確認するというのは必要なことだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"簡単に理由を述べますけれども、請願項目に書いてある1)と2)について、労働災害防止の行政監督、これは労働基準監督署というところがしっかりあって、こういった事故等、痛ましい事故ではありますけれども、起こったときにはそこがしっかりと対応する、行政指導するということがあるということ、また調達コードにうたわれていること、長時間労働の禁止だとか労働環境、持続可能性。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"結論を出すということで、採択をして、そしてぜひ意見書を上げていくということでお願いしたいと思います。いよいよあと１年後ということに迫ってきているわけです。そしてまた、今回のところで継続というふうなことになれば、これは今度選挙があるということで廃案になってしまいますので、ぜひここで採択を主張し、意見書を出していくということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-013"},{"speaker":"大倉委員","kind":"意見","question":"私たちの会派としては、本日結論を出すということで採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"結論を出すで、採択をし、意見書を出したいと思います。やはり命が亡くなってしまったとても悲しい事故、事件だったので、幾ら遵守が徹底されてきているといっても、今以上にもっと慎重にしっかりと徹底を求めていきたいというこの請願の思いは強く私も生活者ネットワークとしても思うので、ぜひ皆さん一緒に採択をして、意見書を出しませんかということを呼びかけたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"}]},{"id":"topic-02","title":"清泉女子大学と区のコラボ授業","agenda":"清泉女子大学と区のコラボ授業","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ聞かせてください。本当にこれはこれでありがとうございました。いろいろ学生さんのいい意見があるなと考えていますけれども、発表会があった、そのときそれを聞く側のメンバーを教えていただきたいのと、各所管に渡したというのだけれども、その後どうするのか。そこら辺のところはどこまでどういうふうになっているのか、もうちょっと教えてほしいです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"報告会に参加したメンバーなのですが、職場企画研修、私どもの課が企画した研修ということで、各課から１名から２名ということで希望者が出てまいりました。品川第一地区の連合町会長と、まちづくり協議会の会長などに出ていただきましていろいろコメントをいただいたところです。","voiceIndex":44,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"お願いだけしておきます。では、こういうのをこういうふうにしていこうよとかいろいろな考え方があると思うので、ぜひそういう、もう一回会長から下のメンバーにそういうのを投げかける作業というのを検討していただきたいと思っていますので、それはお願いだけにしておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-017"},{"speaker":"田中委員","kind":"意見","question":"先ほどのお話と関連すると思うのですけれども、もしこの事業の中で一つでも先に進みそうな、実現しそうなものがあった場合に、ぜひ学生の皆さんたちにそういう声を届けてほしいということ、実際に形になったときにも声を届けてほしいです。何かあればお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"学生へのフィードバックというところなのですが、この授業というのは１年生対象の授業ですので、是非進捗状況をお知らせしながら、区のことにもまた関わっていただけたらなと思います。","voiceIndex":48,"id":"exchange-018"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"１年間ありがとうございました。委員長、１年間、ありがとうございました。殊に、公益財団法人東京オリンピック・パラリンピック競技大会組織委員会、そこにお邪魔して我々の意見も申し上げさせていただき、これを結びつけていただきたいと思います。ぜひ理事者の方もこれからどうぞよろしくお願いいたします。１年間ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-019"},{"speaker":"いながわ委員長","kind":"質問・要望","question":"１年間、効率的な委員会運営にご協力いただきまして、本当にありがとうあります。この１年間さまざまなご意見が出され、非常に有意義な特別委員会だったと私は思っております。さまざまな意見が出されている中で、品川区役所ができることについてはしっかりとオリンピックに向け機運の醸成を含め、まちづくりを進めていただきたいと思います。１年間ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6552#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":13679,"voices":59}}]);
